   public List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> fieldConfig() {
      this.requireSystemConfigPermission();
      return this.payrollRepository.findNumericFields();
   }

   @Transactional
   public List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> updateFieldConfig(com.dxsoft.rsgzgl.payroll.PayrollFieldConfigUpdateRequest request) {
      this.requireSystemConfigPermission();
      Set<Integer> numericIds = this.payrollRepository
         .findNumericFields()
         .stream()
         .map(com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata::id)
         .filter(Objects::nonNull)
         .collect(Collectors.toSet());
      List<Integer> enabledIds = request != null && request.enabledIds() != null
         ? request.enabledIds().stream().filter(Objects::nonNull).filter(numericIds::contains).distinct().toList()
         : List.of();
      this.payrollRepository.updateNumericFieldEnabledFlags(enabledIds);
      this.calculationFieldsCache = null;
      return this.payrollRepository.findNumericFields();
   }

