   private com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState applyReformLevelRollingState(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year,
      List<String> lines
   ) {
      String previousLevel = state.level();
      String previousStep = state.stepOrSalaryLevel();
      int currentSalary = this.gradeSalaryAmount(state, previousLevel, previousStep, state.salaryStandardYearMonth());
      String nextLevel = this.cappedPromotedLevel(state.positionCode(), String.valueOf(Math.max(1, this.payrollRepository.intValue(previousLevel) - 1)));
      String nextStep = this.firstHigherGradeStep(nextLevel, currentSalary, state.salaryStandardYearMonth());
      String nextStepStartYear = this.gradeIncreaseExceedsStepDifference(previousLevel, previousStep, nextLevel, state.salaryStandardYearMonth())
         ? String.valueOf(year)
         : state.stepStartYear();
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState next = this.projectionWithLevelStep(
         state, nextLevel, nextStep, String.valueOf(year), nextStepStartYear
      );
      if (lines != null) {
         int reformYears = start.wageReformYears() + (year - 2006);
         com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode positionMode = this.resolveReformRollingPositionMode(
            latest, start, state.positionCode(), year
         );
         String ruleNote = this.resolveReformLevelRollingRulePath(
               state, start, latest, year, reformYears, this.payrollRepository.intValue(previousLevel), positionMode
            )
            .map(this::reformLevelRollingRuleNote)
            .orElse("");
         this.appendProjectionLine(
            lines,
            state,
            next,
            year
               + " 年：2007-2010 套改后级别滚动"
               + (ruleNote.isBlank() ? "" : "（" + ruleNote + "）")
               + "，上一年度考核称职及以上且达到套改表规定年限，晋升级别 "
               + this.levelStepDisplay(this.resolvedBaseSalarySource(state), previousLevel, previousStep)
               + " -> "
               + this.levelStepDisplay(this.baseSalarySource(state.positionCode(), nextLevel), nextLevel, nextStep)
               + "。"
         );
      }

      return next;
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState advanceSimulatedNormalLevelPromotion(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year,
      int qualifiedLevel,
      List<String> lines
   ) {
      String previousLevel = state.level();
      if (this.atHighestPositionLevel(state.positionCode(), previousLevel)) {
         return this.promoteCivilServantGradeStep(state, year, lines, "累计 " + qualifiedLevel + " 年考核合格，已达到所任职务最高级别，按级别晋升口径级别不变", true);
      } else {
         String previousStep = state.stepOrSalaryLevel();
         int currentSalary = this.payrollRepository.gradeSalary(previousLevel, previousStep, state.salaryStandardYearMonth());
         String nextLevel = String.valueOf(Math.max(1, this.payrollRepository.intValue(previousLevel) - 1));
         String nextStep = this.firstHigherGradeStep(nextLevel, currentSalary, state.salaryStandardYearMonth());
         String nextStepStartYear = this.gradeIncreaseExceedsStepDifference(previousLevel, previousStep, nextLevel, state.salaryStandardYearMonth())
            ? String.valueOf(year)
            : state.stepStartYear();
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState next = this.projectionWithLevelStep(
            state, nextLevel, nextStep, String.valueOf(year), nextStepStartYear
         );
         this.appendProjectionLine(
            lines,
            state,
            next,
            year
               + " 年：累计 "
               + qualifiedLevel
               + " 年考核合格，晋升级别 "
               + this.levelStepDisplay(state.baseSalarySource(), previousLevel, previousStep)
               + " -> "
               + this.levelStepDisplay(state.baseSalarySource(), nextLevel, nextStep)
               + "。"
         );
         return next;
      }
   }

   private Set<Integer> appliedReformLevelRollingYears(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      return this.payrollRepository
         .findHistoryChain(history.organizationCode(), history.personCode())
         .stream()
         .filter(record -> "级别滚动".equals(record.calculationType()))
         .map(record -> this.yearOf(record.calculationYear()))
         .collect(Collectors.toCollection(TreeSet::new));
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation simulateReformLevelRolling(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      int limitYear,
      Set<Integer> appliedRollingYears,
      int payrollPeriod
   ) {
      if (start.eligible() && start.wageReformYears() > 0 && limitYear >= 2007) {
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state = this.createInitialProjectionState(
            history, start, this.initialRankAllowanceState(history, start.period())
         );
         String endPeriod = String.format("%04d12", limitYear);
         String regularizationYearMonth = this.payrollRepository.findRegularizationYearMonth(history.organizationCode(), history.personCode());
         List<com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionEvent> projectionEvents = this.wageProjectionEvents(
            history.organizationCode(), history.personCode(), start.period(), endPeriod, regularizationYearMonth, history
         );
         ArrayList<String> ignoredLines = new ArrayList<>();
         int eventIndex = 0;
         int baseYear = this.yearOf(start.period());

         for (int year = Math.max(2007, baseYear + 1); year <= limitYear; year++) {
            for (String yearStart = String.format("%04d01", year);
               eventIndex < projectionEvents.size() && projectionEvents.get(eventIndex).period().compareTo(yearStart) < 0;
               eventIndex++
            ) {
               state = this.applyWageProjectionEvent(state, projectionEvents.get(eventIndex), ignoredLines, history);
            }

            String salarySource = this.resolvedBaseSalarySource(state, history);
            if (this.supportsGradePromotion(state) && this.payrollRepository.intValue(state.level()) > 1) {
               int levelStart = this.assessmentStartYear(state.levelStartYear(), start.positionStartYearMonth(), state.positionCode());
               int stepStart = this.assessmentStartYear(state.stepStartYear(), start.positionStartYearMonth(), state.positionCode());
               int qualifiedLevel = this.payrollRepository
                  .countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), levelStart, year - 1);
               int qualifiedStep = this.payrollRepository.countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), stepStart, year - 1);
               boolean specialLevelPromotionDue = this.specialWageReformLevelPromotionDue(state, start, history, year);
               if (specialLevelPromotionDue && payrollPeriod >= year * 100 + 1 && !appliedRollingYears.contains(year)) {
                  return new com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation(OptionalInt.of(year), state);
               }

               if (specialLevelPromotionDue && appliedRollingYears.contains(year)) {
                  state = this.applyReformLevelRollingState(state, start, history, year, null);
               } else if (!specialLevelPromotionDue && qualifiedLevel >= 5) {
                  state = this.advanceSimulatedNormalLevelPromotion(state, start, history, year, qualifiedLevel, null);
               }

               if (qualifiedStep >= 2) {
                  state = this.promoteCivilServantGradeStep(state, year, null, "累计 " + qualifiedStep + " 年考核合格");
               }
            } else if ("WORKER_GRADE".equals(salarySource)) {
               int stepStartx = this.assessmentStartYear(state.stepStartYear(), start.positionStartYearMonth(), state.positionCode());
               int qualifiedStepx = this.payrollRepository
                  .countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), stepStartx, year - 1);
               if (qualifiedStepx >= 2) {
                  state = this.promoteWorkerGradeStep(state, year, null, "累计 " + qualifiedStepx + " 年考核合格");
               }
            }

            for (String nextYearStart = String.format("%04d01", year + 1);
               eventIndex < projectionEvents.size() && projectionEvents.get(eventIndex).period().compareTo(nextYearStart) < 0;
               eventIndex++
            ) {
               state = this.applyWageProjectionEvent(state, projectionEvents.get(eventIndex), ignoredLines, history);
            }
         }

         return new com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation(OptionalInt.empty(), state);
      } else {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation(OptionalInt.empty(), null);
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode reformRollingPositionMode(String reformPositionCode, String currentPositionCode) {
      if (reformPositionCode != null && !reformPositionCode.isBlank() && currentPositionCode != null && !currentPositionCode.isBlank()) {
         int reformLayer = this.positionLayer(reformPositionCode);
         int currentLayer = this.positionLayer(currentPositionCode);
         if (reformLayer <= 0 || currentLayer <= 0) {
            return com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.UNSUPPORTED;
         } else if (reformLayer == currentLayer) {
            return com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.UNCHANGED;
         } else {
            return reformLayer - currentLayer == 1
               ? com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.SINGLE_LEVEL_PROMOTION
               : com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.UNSUPPORTED;
         }
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.UNSUPPORTED;
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode resolveReformRollingPositionMode(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      String replayPositionCode,
      int year
   ) {
      String reformPositionCode = this.payrollRepository
         .findPositionAtOrBefore(latest.organizationCode(), latest.personCode(), "200607")
         .map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::positionCode)
         .orElse(start.positionCode());
      String comparisonPositionCode = this.payrollRepository
         .findPositionAtOrBefore(latest.organizationCode(), latest.personCode(), String.format("%04d12", year - 1))
         .map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::positionCode)
         .orElse(replayPositionCode);
      return this.reformRollingPositionMode(reformPositionCode, comparisonPositionCode);
   }

   private com.dxsoft.rsgzgl.payroll.PositionChangeCandidate reformAppointmentAt200607(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start
   ) {
      return this.payrollRepository
         .findPositionAtOrBefore(latest.organizationCode(), latest.personCode(), "200607")
         .orElse(new com.dxsoft.rsgzgl.payroll.PositionChangeCandidate(start.positionCode(), start.positionName(), start.positionStartYearMonth()));
   }

   private Optional<com.dxsoft.rsgzgl.payroll.PayrollService.ReformLevelRollingRulePath> resolveReformLevelRollingRulePath(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year,
      int reformYears,
      int currentLevel,
      com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode mode
   ) {
      return switch (mode) {
         case UNCHANGED -> {
            String currentPositionStart = this.payrollRepository
               .findPositionAtOrBefore(latest.organizationCode(), latest.personCode(), String.format("%04d12", year - 1))
               .map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::startYearMonth)
               .orElse(start.positionStartYearMonth());
            int currentAppointmentYears = this.reformLevelRollingAppointmentYears(currentPositionStart, year);
            if (this.reformLevelRollingTableDue(state.positionCode(), currentAppointmentYears, reformYears, currentLevel)) {
               yield Optional.of(com.dxsoft.rsgzgl.payroll.PayrollService.ReformLevelRollingRulePath.CURRENT_POSITION_PREVIOUS_LEVEL);
            } else {
               String regularization = this.normalizeYearMonth(
                  this.payrollRepository.findRegularizationYearMonth(latest.organizationCode(), latest.personCode())
               );
               List<com.dxsoft.rsgzgl.payroll.WageReformPosition> positions = this.resolveWageReformPositionsForSelection(latest, regularization);
               if (positions.size() < 2) {
                  yield Optional.empty();
               } else {
                  com.dxsoft.rsgzgl.payroll.WageReformPosition currentPosition = positions.getFirst();
                  com.dxsoft.rsgzgl.payroll.WageReformPosition lowerPosition = positions.get(1);
                  int mergedLowerAppointmentYears = this.wageReformAppointmentYears(lowerPosition)
                     + this.wageReformAppointmentYears(currentPosition)
                     + (year - 2006);
                  yield this.reformLevelRollingTableDueForReformLevel(
                        lowerPosition.positionCode(), mergedLowerAppointmentYears, reformYears, start.level(), currentLevel
                     )
                     ? Optional.of(com.dxsoft.rsgzgl.payroll.PayrollService.ReformLevelRollingRulePath.LOWER_POSITION_REFORM_LEVEL)
                     : Optional.empty();
               }
            }
         }
         case SINGLE_LEVEL_PROMOTION -> this.reformLevelRollingDueWhenSinglePromotion(start, latest, year, reformYears, currentLevel)
         ? Optional.of(com.dxsoft.rsgzgl.payroll.PayrollService.ReformLevelRollingRulePath.ORIGINAL_POSITION_AFTER_SINGLE_PROMOTION)
         : Optional.empty();
         case UNSUPPORTED -> Optional.empty();
      };
   }

   private String reformLevelRollingRuleNote(com.dxsoft.rsgzgl.payroll.PayrollService.ReformLevelRollingRulePath path) {
      return switch (path) {
         case CURRENT_POSITION_PREVIOUS_LEVEL -> "职务层次未变，按现任职务达到上一级别规定年限";
         case LOWER_POSITION_REFORM_LEVEL -> "职务层次未变，按原任低一职务达到套改确定级别规定年限";
         case ORIGINAL_POSITION_AFTER_SINGLE_PROMOTION -> "晋升职务只晋升一个级别，按原任职务达到晋升后级别规定年限";
      };
   }

   private int reformLevelRollingAppointmentYears(String positionStartYearMonth, int year) {
      return Math.max(1, 2006 - this.yearOf(positionStartYearMonth) + 1) + (year - 2006);
   }

   private boolean reformLevelRollingTableDue(String positionCode, int appointmentYears, int reformYears, int currentLevel) {
      return currentLevel <= 1
         ? false
         : this.lookupWageReformStandard(positionCode, appointmentYears, reformYears)
            .map(standard -> this.payrollRepository.intValue(standard.convertedLevel()) < currentLevel)
            .orElse(false);
   }

   private boolean reformLevelRollingTableDueForReformLevel(
      String positionCode, int appointmentYears, int reformYears, String reformDeterminedLevel, int currentLevel
   ) {
      if (currentLevel <= 1) {
         return false;
      } else {
         int reformLevel = this.payrollRepository.intValue(reformDeterminedLevel);
         return reformLevel <= 0 ? false : this.lookupWageReformStandard(positionCode, appointmentYears, reformYears).map(standard -> {
            int tableLevel = this.payrollRepository.intValue(standard.convertedLevel());
            return tableLevel <= reformLevel && tableLevel < currentLevel;
         }).orElse(false);
      }
   }

   private boolean reformLevelRollingDueWhenUnchanged(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year,
      int reformYears,
      int currentLevel
   ) {
      return this.resolveReformLevelRollingRulePath(
            state, start, latest, year, reformYears, currentLevel, com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode.UNCHANGED
         )
         .isPresent();
   }

   private boolean reformLevelRollingDueWhenSinglePromotion(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year,
      int reformYears,
      int currentLevel
   ) {
      int reformLevel = this.payrollRepository.intValue(start.level());
      if (currentLevel > 0 && reformLevel > 0 && currentLevel < reformLevel) {
         com.dxsoft.rsgzgl.payroll.PositionChangeCandidate reformAppointment = this.reformAppointmentAt200607(latest, start);
         int appointmentYears = this.reformLevelRollingAppointmentYears(reformAppointment.startYearMonth(), year);
         return this.reformLevelRollingTableDueAfterSingleLayerPromotion(reformAppointment.positionCode(), appointmentYears, reformYears, currentLevel);
      } else {
         return false;
      }
   }

   private boolean reformLevelRollingTableDueAfterSingleLayerPromotion(String positionCode, int appointmentYears, int reformYears, int currentLevel) {
      return currentLevel <= 1 ? false : this.lookupWageReformStandard(positionCode, appointmentYears, reformYears).map(standard -> {
         int tableLevel = this.payrollRepository.intValue(standard.convertedLevel());
         return tableLevel > 0 && tableLevel <= currentLevel;
      }).orElse(false);
   }

   private boolean specialWageReformLevelPromotionDue(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int year
   ) {
      if (year >= 2007 && year <= 2010 && start.wageReformYears() > 0 && this.yearOf(state.levelStartYear()) <= 2006) {
         if (this.payrollRepository.countQualifiedAssessmentYears(latest.organizationCode(), latest.personCode(), year - 1, year - 1) <= 0) {
            return false;
         } else {
            int reformYears = start.wageReformYears() + (year - 2006);
            int currentLevel = this.payrollRepository.intValue(state.level());
            if (currentLevel <= 1) {
               return false;
            } else {
               com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingPositionMode positionMode = this.resolveReformRollingPositionMode(
                  latest, start, state.positionCode(), year
               );
               return this.resolveReformLevelRollingRulePath(state, start, latest, year, reformYears, currentLevel, positionMode).isPresent();
            }
         }
      } else {
         return false;
      }
   }

   private OptionalInt findPendingReformLevelRollingYear(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart start
   ) {
      int limitYear = Math.min(2010, this.yearOf(history.calculationYear()));
      int payrollPeriod = this.payrollRepository.intValue(this.normalizeYearMonth(history.calculationYear() + history.calculationMonth()));
      return this.simulateReformLevelRolling(history, start, limitYear, this.appliedReformLevelRollingYears(history), payrollPeriod).pendingYear();
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState projectionStateFromHistory(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      return new com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState(
         history.positionCode(),
         history.positionName(),
         history.gradeSalaryLevel(),
         history.positionSalaryGrade(),
         history.gradeSalaryStep() == null ? "0" : history.gradeSalaryStep(),
         history.levelAssessmentStartYear(),
         history.stepAssessmentStartYear(),
         this.baseSalarySource(history.positionCode(), history.gradeSalaryLevel()),
         history.salaryStandardYearMonth(),
         history.allowanceStandardYearMonth(),
         history.rankName(),
         history.rankAllowanceStandardYearMonth(),
         history.storedRankAllowance(),
         history.postAllowanceCategory()
      );
   }

   private String cappedPromotedLevel(String positionCode, String promotedLevel) {
      com.dxsoft.rsgzgl.payroll.PositionLevelRange range = this.payrollRepository.findPositionLevelRange(positionCode).orElse(null);
      if (range != null && promotedLevel != null && !promotedLevel.isBlank()) {
         int promoted = this.payrollRepository.intValue(promotedLevel);
         return range.maximumLevel() != null && promoted < range.maximumLevel() ? String.valueOf(range.maximumLevel()) : promotedLevel;
      } else {
         return promotedLevel;
      }
   }

   private boolean atHighestPositionLevel(String positionCode, String level) {
      com.dxsoft.rsgzgl.payroll.PositionLevelRange range = this.payrollRepository.findPositionLevelRange(positionCode).orElse(null);
      if (range != null && range.maximumLevel() != null) {
         int currentLevel = this.payrollRepository.intValue(level);
         return currentLevel > 0 && currentLevel <= range.maximumLevel();
      } else {
         return false;
      }
   }

