   private String formatAssessmentYearChanges(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState before, com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState after
   ) {
      if (before != null && after != null) {
         ArrayList<String> parts = new ArrayList<>(2);
         if (!this.assessmentYearsEqual(before.levelStartYear(), after.levelStartYear())) {
            parts.add("级别考核起算年（xckhndjb）更新为 " + this.displayAssessmentYear(after.levelStartYear()));
         }

         if (!this.assessmentYearsEqual(before.stepStartYear(), after.stepStartYear())) {
            parts.add("档次考核起算年（xckhndzw）更新为 " + this.displayAssessmentYear(after.stepStartYear()));
         }

         return parts.isEmpty() ? "" : "，" + String.join("，", parts);
      } else {
         return "";
      }
   }

   private boolean assessmentYearsEqual(String left, String right) {
      return Objects.equals(this.displayAssessmentYear(left), this.displayAssessmentYear(right));
   }

   private String displayAssessmentYear(String year) {
      return year != null && !year.isBlank() ? year.trim() : "-";
   }

   private void appendProjectionLine(
      List<String> lines,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState before,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState after,
      String message
   ) {
      if (lines != null) {
         lines.add(message + this.formatAssessmentYearChanges(before, after));
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState applyProjectionEventWithCapture(
      List<com.dxsoft.rsgzgl.payroll.WageProjectionStepDetail> stepDetails,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      List<String> lines,
      String period,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state,
      boolean lightweightStepCapture,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionEvent event,
      UnaryOperator<com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState> action
   ) {
      String determinationType = event == null ? null : this.emptyToNull(event.personnelDeterminationChangeType());
      if (determinationType != null) {
         String description = this.formatYearMonth(period) + " " + determinationType + "（同等条件推算定资）";
         if (lines != null) {
            lines.add(description);
         }

         this.captureProjectionStep(stepDetails, latest, period, description, determinationType, state, lightweightStepCapture);
         return state;
      } else if (stepDetails == null) {
         return action.apply(state);
      } else {
         int lineStart = lines.size();
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState next = action.apply(state);
         if (next == state) {
            return next;
         } else {
            String description = lines.size() > lineStart ? String.join(" ", lines.subList(lineStart, lines.size())) : "工资状态更新";
            this.captureProjectionStep(stepDetails, latest, period, description, next, lightweightStepCapture);
            return next;
         }
      }
   }

