   private com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditSummary projectionAuditSummaryForUids(List<Integer> uids) {
      if (uids != null && !uids.isEmpty()) {
         com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext batchContext = this.buildProjectionAuditBatchContext(uids);
         List<com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit> audits = this.runProjectionAuditsInParallel(
            uids, uid -> this.safeProjectionPersonAudit(uid, false, batchContext)
         );
         List<com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit> differences = audits.stream()
            .filter(audit -> !Boolean.TRUE.equals(audit.latestMatched()) || audit.historyMismatchCount() > 0)
            .toList();
         BigDecimal maxAbsoluteDifference = audits.stream()
            .map(audit -> audit.latestTotalDifference() == null ? BigDecimal.ZERO : audit.latestTotalDifference().abs())
            .max(Comparator.naturalOrder())
            .orElse(BigDecimal.ZERO);
         int historyMismatchPersonCount = (int)audits.stream().filter(audit -> audit.historyMismatchCount() > 0).count();
         int totalHistoryRecordsCompared = audits.stream().mapToInt(com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit::historyRecordCount).sum();
         int totalHistoryRecordMismatches = audits.stream().mapToInt(com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit::historyMismatchCount).sum();
         int latestDifferenceCount = (int)audits.stream().filter(audit -> !Boolean.TRUE.equals(audit.latestMatched())).count();
         return new com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditSummary(
            (long)uids.size(),
            audits.size(),
            latestDifferenceCount,
            historyMismatchPersonCount,
            totalHistoryRecordsCompared,
            totalHistoryRecordMismatches,
            maxAbsoluteDifference,
            differences,
            audits
         );
      } else {
         return new com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditSummary(0L, 0, 0, 0, 0, 0, BigDecimal.ZERO, List.of(), List.of());
      }
   }

