   public com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditExportData buildProjectionAuditExport(String organizationCode, String keyword, boolean mismatchesOnly) {
      OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
      String scopedKeyword = this.emptyToNull(keyword);
      List<Integer> uids = this.payrollRepository.findAllPersonnelUidsWithPayrollHistory(scope, scopedKeyword);
      long totalPersonnel = this.payrollRepository.countPersonnelWithPayrollHistory(scope, scopedKeyword);
      log.info(
         "Starting full projection audit export for {} personnel (parallelism={})",
         uids.size(),
         Math.min(PROJECTION_AUDIT_PARALLELISM, Math.max(1, uids.size()))
      );
      AtomicInteger progress = new AtomicInteger();
      List<com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle> bundles = this.runProjectionAuditsInParallel(uids, uid -> {
         com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle bundle = this.exportProjectionPersonBundle(uid);
         int done = progress.incrementAndGet();
         if (done == 1 || done % 25 == 0 || done == uids.size()) {
            log.info("Projection audit export progress: {}/{}", done, uids.size());
         }

         return bundle;
      });
      ArrayList<com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit> summaries = new ArrayList<>(bundles.size());
      ArrayList<com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditDetailRow> details = new ArrayList<>();

      for (com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle bundle : bundles) {
         summaries.add(bundle.summary());

         for (com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit audit2 : bundle.historyAudits()) {
            if (!mismatchesOnly || !Boolean.TRUE.equals(audit2.matched())) {
               details.add(
                  com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditDetailRow.of(
                     bundle.summary().uid(),
                     bundle.summary().organizationCode(),
                     bundle.summary().personCode(),
                     bundle.summary().name(),
                     this.withoutStepDetails(audit2)
                  )
               );
            }
         }
      }

      int latestDifferenceCount = (int)summaries.stream().filter(audit -> !Boolean.TRUE.equals(audit.latestMatched())).count();
      int historyMismatchPersonCount = (int)summaries.stream().filter(audit -> audit.historyMismatchCount() > 0).count();
      int totalHistoryRecordsCompared = summaries.stream().mapToInt(com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit::historyRecordCount).sum();
      int totalHistoryRecordMismatches = summaries.stream().mapToInt(com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit::historyMismatchCount).sum();
      log.info(
         "Projection audit export finished: {} personnel, {} history rows, {} mismatches",
         new Object[]{summaries.size(), details.size(), totalHistoryRecordMismatches}
      );
      return new com.dxsoft.rsgzgl.payroll.PayrollProjectionAuditExportData(
         totalPersonnel,
         summaries.size(),
         latestDifferenceCount,
         historyMismatchPersonCount,
         totalHistoryRecordsCompared,
         totalHistoryRecordMismatches,
         summaries,
         details
      );
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle exportProjectionPersonBundle(int uid) {
      try {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository
            .findLatestHistory(uid)
            .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
         this.accessControlService.requireOrganization(latest.organizationCode());
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain = this.payrollRepository
            .findHistoryChain(latest.organizationCode(), latest.personCode());
         List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> historyAudits = this.auditHistoryChainWithProjection(uid, latest, historyChain, false);
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle(
            this.buildProjectionPersonAudit(uid, latest, historyAudits, false), historyAudits
         );
      } catch (RuntimeException var5) {
         log.warn("Projection audit export skipped for uid {}: {}", uid, var5.getMessage());
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionPersonExportBundle(this.skippedProjectionPersonAudit(uid, var5.getMessage()), List.of());
      }
   }

   private <T> List<T> runProjectionAuditsInParallel(List<Integer> uids, Function<Integer, T> task) {
      if (uids != null && !uids.isEmpty()) {
         if (uids.size() == 1) {
            return List.of(task.apply(uids.getFirst()));
         } else {
            int poolSize = Math.min(PROJECTION_AUDIT_PARALLELISM, uids.size());
            DelegatingSecurityContextExecutorService executor = new DelegatingSecurityContextExecutorService(Executors.newFixedThreadPool(poolSize));

            ArrayList var26;
            try {
               ArrayList<Future<Object>> futures = new ArrayList<>(uids.size());

               for (Integer uid : uids) {
                  futures.add(executor.submit(() -> task.apply(uid)));
               }

               ArrayList results = new ArrayList(uids.size());

               for (Future future : futures) {
                  try {
                     results.add(future.get());
                  } catch (InterruptedException var21) {
                     Thread.currentThread().interrupt();
                     throw new IllegalStateException("推算对账被中断", var21);
                  } catch (ExecutionException var22) {
                     Throwable cause = (Throwable)(var22.getCause() == null ? var22 : var22.getCause());
                     if (cause instanceof RuntimeException runtimeException) {
                        throw runtimeException;
                     }

                     throw new IllegalStateException("推算对账失败：" + cause.getMessage(), cause);
                  }
               }

               var26 = results;
            } finally {
               executor.shutdown();

               try {
                  if (!executor.awaitTermination(2L, TimeUnit.HOURS)) {
                     executor.shutdownNow();
                  }
               } catch (InterruptedException var20) {
                  executor.shutdownNow();
                  Thread.currentThread().interrupt();
               }
            }

            return var26;
         }
      } else {
         return List.of();
      }
   }

