   public com.dxsoft.rsgzgl.payroll.PayrollChangeComparison payrollChangeComparison(String payrollHistoryId) {
      Map<String, Object> afterValues = this.payrollRepository.findHistoryValuesById(payrollHistoryId);
      String organizationCode = this.textValue(afterValues, "dwbm");
      this.accessControlService.requireOrganization(organizationCode);
      Optional<Map<String, Object>> beforeValues = this.payrollRepository.findPredecessorHistoryValues(payrollHistoryId);
      return this.buildPayrollChangeComparison(payrollHistoryId, afterValues, beforeValues);
   }

   public List<com.dxsoft.rsgzgl.payroll.PayrollChangeComparison> payrollChangeComparisons(List<String> payrollHistoryIds) {
      List<String> ids = payrollHistoryIds == null
         ? List.of()
         : payrollHistoryIds.stream().filter(idx -> idx != null && !idx.isBlank()).map(String::trim).distinct().toList();
      if (ids.isEmpty()) {
         return List.of();
      } else {
         long startedAt = System.nanoTime();
         Map<String, Map<String, Object>> afterById = this.payrollRepository.findHistoryValuesByIds(ids);
         long afterHistoryAt = System.nanoTime();
         Map<String, Map<String, Object>> beforeById = this.payrollRepository.findPredecessorHistoryValuesByIds(ids);
         long beforeHistoryAt = System.nanoTime();
         LinkedHashSet<String> organizationCodes = new LinkedHashSet<>();
         LinkedHashSet<String> personCodes = new LinkedHashSet<>();
         int minStartYear = Integer.MAX_VALUE;
         int maxEndYear = 0;

         for (String id : ids) {
            Map<String, Object> afterValues = this.resolveHistoryValues(afterById, id);
            if (afterValues != null) {
               Optional<int[]> range = this.resolveBasisAssessmentYearRange(afterValues, Optional.ofNullable(this.resolveHistoryValues(beforeById, id)));
               if (!range.isEmpty()) {
                  String organizationCode = this.textValue(afterValues, "dwbm");
                  String personCode = this.textValue(afterValues, "grbm");
                  if (!organizationCode.isBlank() && !personCode.isBlank()) {
                     organizationCodes.add(organizationCode);
                     personCodes.add(personCode);
                     minStartYear = Math.min(minStartYear, range.get()[0]);
                     maxEndYear = Math.max(maxEndYear, range.get()[1]);
                  }
               }
            }
         }

         Map<String, List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear>> assessmentsByPerson = minStartYear <= maxEndYear
            ? this.payrollRepository.findAssessmentResultsByPersons(organizationCodes, personCodes, minStartYear, maxEndYear)
            : Map.of();
         long assessmentsAt = System.nanoTime();
         ArrayList<com.dxsoft.rsgzgl.payroll.PayrollChangeComparison> comparisons = new ArrayList<>(ids.size());

         for (String idx : ids) {
            Map<String, Object> afterValues = this.resolveHistoryValues(afterById, idx);
            if (afterValues == null) {
               throw new NotFoundException("未找到工资变动记录：" + idx);
            }

            this.accessControlService.requireOrganization(this.textValue(afterValues, "dwbm"));
            comparisons.add(
               this.buildPayrollChangeComparison(idx, afterValues, Optional.ofNullable(this.resolveHistoryValues(beforeById, idx)), assessmentsByPerson)
            );
         }

         log.info(
            "payrollChangeComparisons ids={} historyAfter={}ms historyBefore={}ms assessments={}ms build={}ms total={}ms",
            new Object[]{
               ids.size(),
               (afterHistoryAt - startedAt) / 1000000L,
               (beforeHistoryAt - afterHistoryAt) / 1000000L,
               (assessmentsAt - beforeHistoryAt) / 1000000L,
               (System.nanoTime() - assessmentsAt) / 1000000L,
               (System.nanoTime() - startedAt) / 1000000L
            }
         );
         return comparisons;
      }
   }

   private Map<String, Object> resolveHistoryValues(Map<String, Map<String, Object>> valuesById, String id) {
      Map<String, Object> values = valuesById.get(id);
      return values != null
         ? values
         : valuesById.entrySet().stream().filter(entry -> id.equals(String.valueOf(entry.getKey()).trim())).map(Entry::getValue).findFirst().orElse(null);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollChangeComparison buildPayrollChangeComparison(
      String payrollHistoryId, Map<String, Object> afterValues, Optional<Map<String, Object>> beforeValues
   ) {
      return this.buildPayrollChangeComparison(payrollHistoryId, afterValues, beforeValues, null);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollChangeComparison buildPayrollChangeComparison(
      String payrollHistoryId,
      Map<String, Object> afterValues,
      Optional<Map<String, Object>> beforeValues,
      Map<String, List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear>> assessmentsByPerson
   ) {
      List components = PAYROLL_CHANGE_COMPARISON_FIELDS.stream()
         .sorted()
         .map(fieldName -> this.componentComparison(fieldName, this.approvalCaption(fieldName, fieldName), beforeValues.orElse(null), afterValues))
         .collect(Collectors.toCollection(ArrayList::new));
      String educationName = this.firstNonBlank(this.textValue(afterValues, "approval_xl"), this.textValue(afterValues, "approval_zgxl"));
      return new com.dxsoft.rsgzgl.payroll.PayrollChangeComparison(
         payrollHistoryId,
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "id")).orElse(null),
         this.textValue(afterValues, "dwbm"),
         this.textValue(afterValues, "approval_dwmc"),
         this.textValue(afterValues, "approval_dwsx"),
         this.textValue(afterValues, "approval_xtlb"),
         this.textValue(afterValues, "approval_jxbl"),
         this.textValue(afterValues, "grbm"),
         this.textValue(afterValues, "xm"),
         this.textValue(afterValues, "approval_sfzh"),
         this.textValue(afterValues, "approval_xb"),
         this.textValue(afterValues, "approval_csny"),
         educationName,
         this.resolveDegree(educationName),
         this.textValue(afterValues, "approval_byyx"),
         this.textValue(afterValues, "approval_xz"),
         this.textValue(afterValues, "approval_bysj"),
         this.textValue(afterValues, "approval_xllb"),
         this.textValue(afterValues, "approval_zzny"),
         this.textValue(afterValues, "approval_cjgzny"),
         this.intValue(afterValues, "approval_gznx"),
         this.textValue(afterValues, "approval_dah"),
         this.textValue(afterValues, "approval_rzny"),
         this.textValue(afterValues, "jsnf") + this.textValue(afterValues, "jsyf"),
         this.textValue(afterValues, "jslb"),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "zwgw2")).orElse(null),
         this.textValue(afterValues, "zwgw2"),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "zwbm2")).orElse(null),
         this.textValue(afterValues, "zwbm2"),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "jbgzjb2")).orElse(null),
         this.textValue(afterValues, "jbgzjb2"),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "zwgzdc2")).orElse(null),
         this.textValue(afterValues, "zwgzdc2"),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "jsnf") + this.textValue((Map<String, Object>)values, "jsyf"))
            .orElse(null),
         beforeValues.<String>map(values -> this.textValue((Map<String, Object>)values, "jslb")).orElse(null),
         this.textValue(afterValues, "xckhndzw"),
         this.textValue(afterValues, "xckhndjb"),
         this.resolveBasisAssessments(afterValues, beforeValues, assessmentsByPerson),
         components
      );
   }

   private Optional<int[]> resolveBasisAssessmentYearRange(Map<String, Object> afterValues, Optional<Map<String, Object>> beforeValues) {
      String organizationCode = this.textValue(afterValues, "dwbm");
      String personCode = this.textValue(afterValues, "grbm");
      if (!organizationCode.isBlank() && !personCode.isBlank()) {
         String changeType = this.textValue(afterValues, "jslb");
         boolean stepOrSalaryChange = changeType.contains("档次") || changeType.contains("晋档") || changeType.contains("薪级") && !changeType.contains("级别");
         boolean levelPromotion = changeType.contains("级别")
            || changeType.contains("晋级")
            || changeType.contains("级别滚动")
            || changeType.contains("级") && !changeType.contains("薪级") && !changeType.contains("档");
         String primaryField;
         if (levelPromotion && !changeType.contains("档")) {
            primaryField = "xckhndjb";
         } else if (!stepOrSalaryChange && !changeType.contains("档")) {
            primaryField = "xckhndjb";
         } else {
            primaryField = "xckhndzw";
         }

         String secondaryField = "xckhndjb".equals(primaryField) ? "xckhndzw" : "xckhndjb";
         String field = primaryField;
         Integer afterStart = this.intValue(afterValues, primaryField);
         if (afterStart == null) {
            afterStart = this.intValue(afterValues, secondaryField);
            field = secondaryField;
         }

         if (afterStart == null) {
            afterStart = this.intValue(afterValues, "jsnf");
         }

         if (afterStart == null) {
            return Optional.empty();
         } else {
            int endYear = afterStart - 1;
            String assessmentField = field;
            Integer beforeStart = beforeValues.<Integer>map(values -> this.intValue((Map<String, Object>)values, assessmentField)).orElse(null);
            int startYear = beforeStart != null && beforeStart <= endYear ? beforeStart : endYear;
            return endYear > 0 && startYear > 0 ? Optional.of(new int[]{startYear, endYear}) : Optional.empty();
         }
      } else {
         return Optional.empty();
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear> resolveBasisAssessments(
      Map<String, Object> afterValues,
      Optional<Map<String, Object>> beforeValues,
      Map<String, List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear>> assessmentsByPerson
   ) {
      Optional<int[]> range = this.resolveBasisAssessmentYearRange(afterValues, beforeValues);
      if (range.isEmpty()) {
         return List.of();
      } else {
         int startYear = range.get()[0];
         int endYear = range.get()[1];
         String organizationCode = this.textValue(afterValues, "dwbm");
         String personCode = this.textValue(afterValues, "grbm");
         if (assessmentsByPerson != null) {
            List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear> loaded = assessmentsByPerson.getOrDefault(
               com.dxsoft.rsgzgl.payroll.PayrollRepository.personAssessmentKey(organizationCode, personCode), List.of()
            );
            return loaded.isEmpty() ? List.of() : loaded.stream().filter(item -> item.year() >= startYear && item.year() <= endYear).toList();
         } else {
            return this.payrollRepository.assessmentResults(organizationCode, personCode, startYear, endYear);
         }
      }
   }

   private Integer intValue(Map<String, Object> values, String fieldName) {
      String text = this.textValue(values, fieldName);
      if (text.isBlank()) {
         return null;
      } else {
         try {
            return Integer.parseInt(text);
         } catch (NumberFormatException var5) {
            return null;
         }
      }
   }

