   private PageResponse<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> normalPromotionPreviews(
      String organizationCode,
      String keyword,
      Boolean includeApply,
      Boolean includeProcessed,
      String year,
      PageRequest pageRequest,
      boolean allPersonnel,
      String laterPeriodMode
   ) {
      int promotionYear = this.resolveNormalPromotionYear(year);
      OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
      boolean showApply = !Boolean.FALSE.equals(includeApply);
      boolean showProcessed = !Boolean.FALSE.equals(includeProcessed);
      if (allPersonnel) {
         List<Integer> pageUids = this.payrollRepository.findPersonnelUidsWithCurrentPayroll(scope, this.emptyToNull(organizationCode), keyword, pageRequest);
         long total = this.payrollRepository.countPersonnelWithCurrentPayroll(scope, this.emptyToNull(organizationCode), keyword);
         if (pageUids.isEmpty()) {
            return PageResponse.of(List.of(), pageRequest, total);
         } else {
            List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> pagePreviews = this.computeNormalPromotionPreviewsForUids(pageUids, promotionYear);
            return PageResponse.of(pagePreviews, pageRequest, total);
         }
      } else if (!showApply && !showProcessed) {
         return PageResponse.of(List.of(), pageRequest, 0L);
      } else {
         String cacheKey = this.normalPromotionListCacheKey(scope, organizationCode, keyword, promotionYear, laterPeriodMode);
         List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> allPreviews = this.cachedNormalPromotionList(cacheKey);
         if (allPreviews == null) {
            allPreviews = this.computeNormalPromotionStatusPreviews(scope, organizationCode, keyword, promotionYear, laterPeriodMode);
            this.normalPromotionListCache
               .put(cacheKey, new com.dxsoft.rsgzgl.payroll.PayrollService.CachedNormalPromotionList(System.currentTimeMillis(), List.copyOf(allPreviews)));
         }

         List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> previews = allPreviews.stream()
            .filter(preview -> this.matchesNormalPromotionStatusFilter(preview, showApply, showProcessed))
            .toList();
         int fromIndex = pageRequest.offset();
         if (fromIndex >= previews.size()) {
            return PageResponse.of(List.of(), pageRequest, (long)previews.size());
         } else {
            int toIndex = Math.min(fromIndex + pageRequest.size(), previews.size());
            List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> page = previews.subList(fromIndex, toIndex);
            return PageResponse.of(this.enrichNormalPromotionListPage(page, promotionYear, laterPeriodMode), pageRequest, (long)previews.size());
         }
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> computeNormalPromotionStatusPreviews(
      OrganizationScope scope, String organizationCode, String keyword, int promotionYear, String laterPeriodMode
   ) {
      long startedAt = System.nanoTime();
      List<Integer> uids = this.payrollRepository.findNormalPromotionCandidateUids(scope, this.emptyToNull(organizationCode), keyword, promotionYear);
      long afterUids = System.nanoTime();
      if (uids.isEmpty()) {
         return List.of();
      } else {
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories = this.payrollRepository.findLatestHistoriesByUids(uids);
         long afterHistories = System.nanoTime();
         com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache = this.loadLevelPromotionAssessmentCache(
            histories, promotionYear
         );
         long afterAssessments = System.nanoTime();
         com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache gradeCache = com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(
            this.payrollRepository
         );
         List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> computed = this.runNormalPromotionListInParallel(
            uids,
            uid -> {
               com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = histories.get(uid);
               return history == null
                  ? null
                  : this.normalPromotionPreview(uid, promotionYear, history, assessmentCache, gradeCache, true, true, Map.of(), laterPeriodMode);
            }
         );
         long afterTrial = System.nanoTime();
         ArrayList<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> visible = new ArrayList<>(computed.size());

         for (com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview : computed) {
            if (preview != null && this.matchesNormalPromotionStatusFilter(preview, true, true)) {
               visible.add(preview);
            }
         }

         visible.sort(this.normalPromotionListOrder());
         log.debug(
            "normal-promotion list cold: uids={} visible={} uidSql={}ms history={}ms assess={}ms trial={}ms total={}ms",
            new Object[]{
               uids.size(),
               visible.size(),
               (afterUids - startedAt) / 1000000L,
               (afterHistories - afterUids) / 1000000L,
               (afterAssessments - afterHistories) / 1000000L,
               (afterTrial - afterAssessments) / 1000000L,
               (System.nanoTime() - startedAt) / 1000000L
            }
         );
         return visible;
      }
   }

   private Comparator<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> normalPromotionListOrder() {
      return Comparator.<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview, String>comparing(preview -> Objects.toString(preview.organizationCode(), ""))
         .thenComparing(preview -> Objects.toString(preview.personCode(), ""));
   }

   private Comparator<com.dxsoft.rsgzgl.payroll.LevelPromotionPreview> levelPromotionListOrder() {
      return Comparator.<com.dxsoft.rsgzgl.payroll.LevelPromotionPreview, String>comparing(preview -> Objects.toString(preview.organizationCode(), ""))
         .thenComparing(preview -> Objects.toString(preview.personCode(), ""));
   }

   private boolean matchesNormalPromotionStatusFilter(com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview, boolean showApply, boolean showProcessed) {
      if (preview == null) {
         return false;
      } else {
         boolean processed = Boolean.TRUE.equals(preview.rollbackEligible());
         return processed ? showProcessed : showApply && this.isNormalPromotionPendingListRow(preview);
      }
   }

   private boolean isNormalPromotionPendingListRow(com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview) {
      if (preview == null || Boolean.TRUE.equals(preview.rollbackEligible())) {
         return false;
      } else if (!Boolean.TRUE.equals(preview.applyEligible())
         && !Boolean.TRUE.equals(preview.overdueFromLastYear())
         && !Boolean.TRUE.equals(preview.levelPromotionRequiredFirst())
         && !Boolean.TRUE.equals(preview.eligible())) {
         int requiredYears = this.nullToZero(preview.requiredYears());
         int stepStartYear = this.payrollRepository.intValue(preview.stepAssessmentStartYear());
         int promotionYear = this.yearOf(preview.calculationPeriod());
         return requiredYears > 0 && stepStartYear > 0 && promotionYear - stepStartYear >= requiredYears;
      } else {
         return true;
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> computeNormalPromotionPreviewsForUids(List<Integer> uids, int promotionYear) {
      Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories = this.payrollRepository.findLatestHistoriesByUids(uids);
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId = this.loadNormalPromotionPredecessors(histories, promotionYear);
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache = this.loadLevelPromotionAssessmentCache(histories, promotionYear);
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache gradeCache = com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(
         this.payrollRepository
      );
      ArrayList<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> previews = new ArrayList<>(uids.size());

      for (Integer uid : uids) {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = histories.get(uid);
         if (history != null) {
            com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview = this.normalPromotionPreview(
               uid, promotionYear, history, assessmentCache, gradeCache, true, false, predecessorsByTipId
            );
            if (preview != null) {
               previews.add(preview);
            }
         }
      }

      return previews;
   }

   private List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> enrichNormalPromotionListPage(
      List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> page, int promotionYear, String laterPeriodMode
   ) {
      if (page != null && !page.isEmpty()) {
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories = this.payrollRepository
            .findLatestHistoriesByUids(page.stream().map(com.dxsoft.rsgzgl.payroll.NormalPromotionPreview::uid).distinct().toList());
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId = this.loadNormalPromotionPredecessors(histories, promotionYear);
         com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache = this.loadLevelPromotionAssessmentCache(
            histories, promotionYear
         );
         com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache gradeCache = com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(
            this.payrollRepository
         );
         ArrayList<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> enriched = new ArrayList<>(page.size());

         for (com.dxsoft.rsgzgl.payroll.NormalPromotionPreview summary : page) {
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = histories.get(summary.uid());
            if (history == null) {
               enriched.add(summary);
            } else {
               com.dxsoft.rsgzgl.payroll.NormalPromotionPreview full = this.normalPromotionPreview(
                  summary.uid(), promotionYear, history, assessmentCache, gradeCache, true, false, predecessorsByTipId, laterPeriodMode
               );
               enriched.add(full != null ? full : summary);
            }
         }

         return enriched;
      } else {
         return List.of();
      }
   }

   private Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> loadNormalPromotionPredecessors(
      Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories, int promotionYear
   ) {
      if (histories != null && !histories.isEmpty()) {
         List<String> processedTipIds = histories.values()
            .stream()
            .filter(history -> this.isNormalPromotionProcessedInYear(history, promotionYear))
            .map(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot::id)
            .filter(id -> id != null && !id.isBlank())
            .map(String::trim)
            .distinct()
            .toList();
         return processedTipIds.isEmpty() ? Map.of() : this.payrollRepository.findPredecessorHistoriesByCurrentIds(processedTipIds);
      } else {
         return Map.of();
      }
   }

   private String normalPromotionListCacheKey(OrganizationScope scope, String organizationCode, String keyword, int promotionYear, String laterPeriodMode) {
      String organizations = scope != null && !scope.all() ? scope.organizationCodes().stream().sorted().collect(Collectors.joining(",")) : "*";
      return organizations
         + "|"
         + Objects.toString(this.emptyToNull(organizationCode), "")
         + "|"
         + Objects.toString(this.emptyToNull(keyword), "")
         + "|"
         + promotionYear
         + "|"
         + Objects.toString(this.emptyToNull(laterPeriodMode), "block");
   }

   private List<com.dxsoft.rsgzgl.payroll.NormalPromotionPreview> cachedNormalPromotionList(String cacheKey) {
      com.dxsoft.rsgzgl.payroll.PayrollService.CachedNormalPromotionList cached = this.normalPromotionListCache.get(cacheKey);
      if (cached == null) {
         return null;
      } else if (System.currentTimeMillis() - cached.createdAtMillis() > 120000L) {
         this.normalPromotionListCache.remove(cacheKey, cached);
         return null;
      } else {
         return cached.previews();
      }
   }

   private void invalidateNormalPromotionListCache() {
      this.normalPromotionListCache.clear();
   }

   private <T> List<T> runNormalPromotionListInParallel(List<Integer> uids, Function<Integer, T> task) {
      if (uids != null && !uids.isEmpty()) {
         if (uids.size() >= 64) {
            T[] results = (T[])(new Object[uids.size()]);
            IntStream.range(0, uids.size()).parallel().forEach(index -> results[index] = task.apply(uids.get(index)));
            return Arrays.asList(results);
         } else {
            ArrayList<T> results = new ArrayList<>(uids.size());

            for (Integer uid : uids) {
               results.add(task.apply(uid));
            }

            return results;
         }
      } else {
         return List.of();
      }
   }

   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyNormalPromotion(String payrollHistoryId, String year) {
      int uid = this.requireCurrentHistoryUid(payrollHistoryId);
      com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview = this.normalPromotionPreview(uid, this.resolveNormalPromotionYear(year));
      if (Boolean.TRUE.equals(preview.overdueFromLastYear())) {
         throw new IllegalArgumentException("上年符合档次/薪级晋升条件，请将晋升年度切换到上年后再办理。");
      } else if (Boolean.TRUE.equals(preview.levelPromotionRequiredFirst())) {
         throw new IllegalArgumentException("同年符合级别晋升条件，请先到级别晋升办理（同年将一并试算档次）。");
      } else if (Boolean.TRUE.equals(preview.applyEligible()) && preview.increaseAmount() != null && preview.increaseAmount() > 0) {
         return this.writeNormalPromotionFromTrial(payrollHistoryId, year, this.toNormalPromotionApplyRequest(preview));
      } else {
         throw new IllegalArgumentException("当前工资记录不满足正常档次/薪级晋升处理条件。");
      }
   }

   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyNormalPromotion(
      String payrollHistoryId, String year, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request
   ) {
      return this.applyNormalPromotion(payrollHistoryId, year, request, null);
   }

   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyNormalPromotion(
      String payrollHistoryId, String year, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request, String laterPeriodMode
   ) {
      return request == null
         ? this.applyNormalPromotion(payrollHistoryId, year, laterPeriodMode)
         : this.writeNormalPromotionFromTrial(payrollHistoryId, year, request, laterPeriodMode);
   }

   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyNormalPromotion(String payrollHistoryId, String year, String laterPeriodMode) {
      int uid = this.requireCurrentHistoryUid(payrollHistoryId);
      int promotionYear = this.resolveNormalPromotionYear(year);
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository
         .findLatestHistory(uid)
         .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview = this.normalPromotionPreview(
         uid,
         promotionYear,
         latest,
         null,
         com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository),
         false,
         false,
         null,
         laterPeriodMode
      );
      if (Boolean.TRUE.equals(preview.overdueFromLastYear())) {
         throw new IllegalArgumentException("上年符合档次/薪级晋升条件，请将晋升年度切换到上年后再办理。");
      } else if (Boolean.TRUE.equals(preview.levelPromotionRequiredFirst())) {
         throw new IllegalArgumentException("同年符合级别晋升条件，请先到级别晋升办理（同年将一并试算档次）。");
      } else if (Boolean.TRUE.equals(preview.applyEligible()) && preview.increaseAmount() != null && preview.increaseAmount() > 0) {
         return this.writeNormalPromotionFromTrial(latest, promotionYear, this.toNormalPromotionApplyRequest(preview), laterPeriodMode);
      } else {
         throw new IllegalArgumentException(this.emptyToNull(preview.note()) == null ? "当前工资记录不满足正常档次/薪级晋升处理条件。" : preview.note());
      }
   }

   public com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyResult batchApplyNormalPromotions(
      String year, com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest request
   ) {
      return this.batchApplyNormalPromotions(year, request, null);
   }

   public com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyResult batchApplyNormalPromotions(
      String year, com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest request, String laterPeriodMode
   ) {
      List<com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest.NormalPromotionBatchApplyItem> items = request != null && request.items() != null
         ? request.items()
         : List.of();
      if (items.isEmpty()) {
         throw new IllegalArgumentException("请选择需要办理的正常档次/薪级晋升记录。");
      } else {
         this.requirePayrollFeatureWrite("NORMAL_PROMOTION_WRITE");
         int promotionYear = this.resolveNormalPromotionYear(year);
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> orgPersonKeys = items.stream()
            .filter(Objects::nonNull)
            .map(item -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(item.organizationCode(), item.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById = this.payrollRepository.findCurrentHistoriesByOrgPersons(orgPersonKeys);
         LinkedHashSet<String> checkedOrganizations = new LinkedHashSet<>();
         int successCount = 0;
         ArrayList<String> failures = new ArrayList<>();
         ArrayList<String> successIds = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyResult.SuccessItem> successes = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest.NormalPromotionBatchApplyItem item : items) {
            String id = item == null ? null : this.emptyToNull(item.payrollHistoryId());
            if (id == null) {
               failures.add("缺少工资记录标识。");
            } else {
               com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = null;

               try {
                  latest = this.resolveCurrentHistoryForNormalApply(id, item, currentById);
                  String organizationCode = this.emptyToNull(latest.organizationCode());
                  if (organizationCode != null && checkedOrganizations.add(organizationCode)) {
                     this.accessControlService.requireOrganization(organizationCode);
                  }

                  com.dxsoft.rsgzgl.payroll.PromotionActionResult applied = this.writeNormalPromotionFromTrial(
                     latest, promotionYear, item.toApplyRequest(), laterPeriodMode
                  );
                  successCount++;
                  successIds.add(id);
                  successes.add(new com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyResult.SuccessItem(id, applied.payrollHistoryId(), applied.changeType()));
               } catch (RuntimeException var19) {
                  failures.add(this.formatNormalPromotionBatchFailure(latest, id, item, var19));
               }
            }
         }

         int failureCount = failures.size();
         String message = failureCount == 0
            ? "批量处理完成：成功 " + successCount + " 条。"
            : "批量处理完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。" + (failures.isEmpty() ? "" : failures.get(0));
         return new com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyResult(successCount, failureCount, failures, successIds, successes, message);
      }
   }

   private String formatNormalPromotionBatchFailure(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      String payrollHistoryId,
      com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest.NormalPromotionBatchApplyItem item,
      RuntimeException ex
   ) {
      String message = ex.getMessage() == null ? "办理失败" : ex.getMessage();
      String personCode = latest != null ? this.emptyToNull(latest.personCode()) : null;
      String name = latest != null ? this.emptyToNull(latest.name()) : null;
      if (personCode == null && item != null) {
         personCode = this.emptyToNull(item.personCode());
      }

      String who;
      if (personCode != null && name != null) {
         who = personCode + name;
      } else if (personCode != null) {
         who = personCode;
      } else if (name != null) {
         who = name;
      } else {
         who = payrollHistoryId;
      }

      return payrollHistoryId != null && !payrollHistoryId.equals(who) ? who + "（" + payrollHistoryId + "）：" + message : who + "：" + message;
   }

   private com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest toNormalPromotionApplyRequest(com.dxsoft.rsgzgl.payroll.NormalPromotionPreview preview) {
      return new com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest(
         preview.organizationCode(),
         preview.personCode(),
         preview.calculationPeriod(),
         preview.promotedGradeOrLevel(),
         preview.gradeSalaryLevel(),
         preview.promotedBaseSalary(),
         preview.increaseAmount(),
         preview.baseSalarySource()
      );
   }

   private com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot resolveCurrentHistoryForNormalApply(
      String payrollHistoryId,
      com.dxsoft.rsgzgl.payroll.NormalPromotionBatchApplyRequest.NormalPromotionBatchApplyItem item,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById
   ) {
      String normalizedId = payrollHistoryId.trim();
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = currentById.get(normalizedId);
      if (latest != null) {
         return latest;
      } else {
         String organizationCode = item == null ? null : this.emptyToNull(item.organizationCode());
         String personCode = item == null ? null : this.emptyToNull(item.personCode());
         return organizationCode != null
               && personCode != null
               && (latest = this.payrollRepository.findCurrentHistoryByOrgPerson(organizationCode, personCode).orElse(null)) != null
               && this.historyIdMatches(latest.id(), normalizedId)
            ? latest
            : this.payrollRepository.findCurrentHistoryById(normalizedId).orElseThrow(() -> new IllegalArgumentException("未找到可办理的当前工资记录。"));
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeNormalPromotionFromTrial(
      String payrollHistoryId, String year, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request
   ) {
      return this.writeNormalPromotionFromTrial(payrollHistoryId, year, request, null);
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeNormalPromotionFromTrial(
      String payrollHistoryId, String year, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request, String laterPeriodMode
   ) {
      if (request == null) {
         throw new IllegalArgumentException("缺少正常档次/薪级晋升办理数据。");
      } else {
         String normalizedId = this.emptyToNull(payrollHistoryId);
         if (normalizedId == null) {
            throw new IllegalArgumentException("缺少工资记录标识。");
         } else {
            this.requirePayrollFeatureWrite("NORMAL_PROMOTION_WRITE");
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.resolveCurrentHistoryForNormalSingleApply(normalizedId, request);
            this.accessControlService.requireOrganization(latest.organizationCode());
            return this.writeNormalPromotionFromTrial(latest, this.resolveNormalPromotionYear(year), request, laterPeriodMode);
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot resolveCurrentHistoryForNormalSingleApply(
      String payrollHistoryId, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request
   ) {
      String organizationCode = request == null ? null : this.emptyToNull(request.organizationCode());
      String personCode = request == null ? null : this.emptyToNull(request.personCode());
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot byOrgPerson;
      return organizationCode != null
            && personCode != null
            && (byOrgPerson = this.payrollRepository.findCurrentHistoryByOrgPerson(organizationCode, personCode).orElse(null)) != null
            && this.historyIdMatches(byOrgPerson.id(), payrollHistoryId)
         ? byOrgPerson
         : this.payrollRepository
            .findCurrentHistoryById(payrollHistoryId)
            .orElseThrow(() -> new NotFoundException("Current payroll history not found: " + payrollHistoryId));
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeNormalPromotionFromTrial(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, int promotionYear, com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request
   ) {
      return this.writeNormalPromotionFromTrial(latest, promotionYear, request, null);
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeNormalPromotionFromTrial(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.NormalPromotionApplyRequest request,
      String laterPeriodMode
   ) {
      if (request == null) {
         throw new IllegalArgumentException("缺少正常档次/薪级晋升办理数据。");
      } else if (latest == null || this.emptyToNull(latest.id()) == null) {
         throw new IllegalArgumentException("缺少工资记录。");
      } else if (this.isNormalPromotionProcessedInYear(latest, promotionYear)) {
         throw new IllegalArgumentException("当前记录已办理正常档次/薪级晋升，只能执行还原，不能再次办理。");
      } else {
         String promotedGradeOrLevel = this.emptyToNull(request.promotedGradeOrLevel());
         if (promotedGradeOrLevel == null) {
            throw new IllegalArgumentException("缺少晋升后档次/薪级，请重新查询试算后再办理。");
         } else {
            Integer increaseAmount = request.increaseAmount();
            if (increaseAmount != null && increaseAmount > 0) {
               Integer promotedBaseSalary = request.promotedBaseSalary();
               if (promotedBaseSalary != null && promotedBaseSalary > 0) {
                  String changeType = this.normalPromotionChangeType(request.baseSalarySource());
                  String calculationYear = this.firstNonBlank(this.yearFromPeriod(request.calculationPeriod()), String.valueOf(promotionYear));
                  String gradeSalaryLevel = this.firstNonBlank(request.gradeSalaryLevel(), latest.gradeSalaryLevel());
                  boolean positionSalaryPromotion = this.isPositionSalaryPromotionSource(request.baseSalarySource())
                     || this.isPositionSalaryPromotionSource(this.baseSalarySource(latest.positionCode()));
                  if (this.isPromotionLaterPeriodCase(latest, promotionYear)) {
                     if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
                        throw new IllegalArgumentException("当前为后变动人员，请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式后再办理。");
                     }

                     if (this.isLaterPeriodInsertRecalcMode(laterPeriodMode)) {
                        return this.writeNormalPromotionMidChain(
                           latest,
                           promotionYear,
                           changeType,
                           promotedGradeOrLevel,
                           gradeSalaryLevel,
                           calculationYear,
                           promotedBaseSalary,
                           increaseAmount,
                           positionSalaryPromotion
                        );
                     }
                  }

                  String calculationMonth = "01";
                  String calculationYearForMutation = calculationYear;
                  if (this.isPromotionLaterPeriodCase(latest, promotionYear) && this.isLaterPeriodSequentialMode(laterPeriodMode)) {
                     String tipPeriod = this.firstNonBlank(this.emptyToNull(request.calculationPeriod()), this.historyCalculationPeriod(latest));
                     if (tipPeriod.length() >= 6) {
                        calculationYearForMutation = tipPeriod.substring(0, 4);
                        calculationMonth = tipPeriod.substring(4, 6);
                     }
                  }

                  com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation mutation = this.buildNormalPromotionMutation(
                     latest,
                     calculationYearForMutation,
                     calculationMonth,
                     changeType,
                     calculationYear,
                     promotedGradeOrLevel,
                     gradeSalaryLevel,
                     promotedBaseSalary,
                     increaseAmount,
                     positionSalaryPromotion
                  );
                  String newId = this.payrollRepository.createPromotionHistoryFromSource(latest, mutation);
                  this.invalidateNormalPromotionListCache();
                  this.invalidateLevelPromotionListCache();
                  this.invalidatePositionChangeListCache();
                  return this.buildAppliedPayrollChange(latest, newId, latest.id(), changeType, "正常档次/薪级晋升处理完成。");
               } else {
                  throw new IllegalArgumentException("缺少晋升后基础工资，请重新查询试算后再办理。");
               }
            } else {
               throw new IllegalArgumentException("增资额无效，请重新查询试算后再办理。");
            }
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeNormalPromotionMidChain(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip,
      int promotionYear,
      String changeType,
      String promotedGradeOrLevel,
      String gradeSalaryLevel,
      String calculationYear,
      Integer promotedBaseSalary,
      Integer increaseAmount,
      boolean positionSalaryPromotion
   ) {
      String organizationCode = this.emptyToNull(tip.organizationCode());
      String personCode = this.emptyToNull(tip.personCode());
      if (organizationCode != null && personCode != null) {
         String executionPeriod = this.promotionExecutionPeriod(promotionYear);
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
         if (anchor == null) {
            throw new IllegalArgumentException("未找到可插入档次/薪级晋升的历史锚点。");
         } else {
            com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation mutation = this.buildNormalPromotionMutation(
               anchor,
               executionPeriod.substring(0, 4),
               executionPeriod.substring(4, 6),
               changeType,
               calculationYear,
               promotedGradeOrLevel,
               gradeSalaryLevel,
               promotedBaseSalary,
               increaseAmount,
               positionSalaryPromotion
            );
            String nextSuccessorId = this.findBasicSalaryMidChainNextSuccessorId(organizationCode, personCode, anchor, chain);
            String newId = this.payrollRepository.insertPromotionMidChain(anchor, nextSuccessorId, mutation);
            this.recalculatePromotionMidChainSuccessors(organizationCode, personCode, nextSuccessorId, anchor.salaryStandardYearMonth());
            this.invalidateNormalPromotionListCache();
            this.invalidateLevelPromotionListCache();
            this.invalidatePositionChangeListCache();
            return this.buildAppliedPayrollChange(tip, newId, tip.id(), changeType, "中段档次/薪级晋升处理完成。");
         }
      } else {
         throw new IllegalArgumentException("缺少人员单位信息。");
      }
   }

