   private com.dxsoft.rsgzgl.payroll.NormalPromotionDetail processedNormalPromotionDetail(
      int uid, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot after, int promotionYear
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = this.payrollRepository
         .findPredecessorHistory(after.organizationCode(), after.personCode(), after.id())
         .orElseThrow(() -> new IllegalArgumentException("未找到档次/薪级晋升前的工资记录。"));
      String baseSalarySource = this.baseSalarySource(after.positionCode(), after.gradeSalaryLevel());
      Integer currentBaseSalary = this.normalPromotionStoredBaseSalary(before, baseSalarySource);
      if (this.nullToZero(currentBaseSalary) <= 0) {
         currentBaseSalary = this.basicCalculation(before).selectedBaseSalary();
      }

      Integer promotedBaseSalary = this.normalPromotionStoredBaseSalary(after, baseSalarySource);
      if (this.nullToZero(promotedBaseSalary) <= 0) {
         promotedBaseSalary = this.basicCalculation(after).selectedBaseSalary();
      }

      String changeType = after.calculationType();
      String assessmentPeriod = this.formatAssessmentPeriod(
         this.assessmentStartYear(before.stepAssessmentStartYear(), before.positionStartYearMonth(), before.positionCode()), promotionYear - 1
      );
      int qualifiedYears = this.payrollRepository
         .countQualifiedAssessmentYears(
            before.organizationCode(),
            before.personCode(),
            this.assessmentStartYear(before.stepAssessmentStartYear(), before.positionStartYearMonth(), before.positionCode()),
            promotionYear - 1
         );
      int requiredYears = this.normalPromotionRequiredYears(before);
      String note = "当前最近工资变动为「" + this.emptyToDash(changeType) + "」，可执行还原。";
      ArrayList<String> lines = new ArrayList<>();
      lines.add("晋升年度 " + promotionYear + "，已办理「" + this.emptyToDash(changeType) + "」，以下为办理前后对照。");
      lines.add("岗位 " + this.positionDisplay(after.positionCode(), after.positionName()) + "，级别 " + this.emptyToDash(after.gradeSalaryLevel()) + "。");
      lines.add("档次/薪级 " + this.emptyToDash(before.positionSalaryGrade()) + " → " + this.emptyToDash(after.positionSalaryGrade()) + "。");
      lines.add("档次考核起算年 " + this.emptyToDash(before.stepAssessmentStartYear()) + " → " + this.emptyToDash(after.stepAssessmentStartYear()) + "。");
      lines.add("考核区间 " + this.emptyToDash(assessmentPeriod) + "，合格年数 " + qualifiedYears + "，要求年数 " + requiredYears + "。");
      lines.add(
         "基础工资 "
            + this.nullToZero(currentBaseSalary)
            + " → "
            + this.nullToZero(promotedBaseSalary)
            + "，增资 "
            + (this.nullToZero(promotedBaseSalary) - this.nullToZero(currentBaseSalary))
            + "。"
      );
      lines.add(note);
      boolean institution = this.isInstitutionPosition(after.positionCode());
      return new com.dxsoft.rsgzgl.payroll.NormalPromotionDetail(
         uid,
         after.id(),
         after.organizationCode(),
         after.personCode(),
         after.name(),
         after.calculationYear() + after.calculationMonth(),
         changeType,
         after.positionCode(),
         after.positionName(),
         after.salaryStandardYearMonth(),
         before.positionSalaryGrade(),
         after.positionSalaryGrade(),
         after.gradeSalaryLevel(),
         before.levelAssessmentStartYear(),
         before.stepAssessmentStartYear(),
         after.stepAssessmentStartYear(),
         assessmentPeriod,
         qualifiedYears,
         requiredYears,
         false,
         false,
         false,
         false,
         true,
         note,
         before.storedPositionSalary(),
         after.storedPositionSalary(),
         currentBaseSalary,
         promotedBaseSalary,
         before.storedPerformanceAllowance(),
         after.storedPerformanceAllowance(),
         institution ? null : before.storedSubsidyAllowance(),
         institution ? null : after.storedSubsidyAllowance(),
         before.storedTotal(),
         after.storedTotal(),
         this.nullToZero(promotedBaseSalary) - this.nullToZero(currentBaseSalary),
         baseSalarySource,
         this.dfbt2CaptionForPosition(after.positionCode(), after.organizationType()),
         institution ? null : this.sdbtCaptionForPosition(after.positionCode(), after.organizationType()),
         !institution,
         lines,
         this.detailSalaryComponentsFromSnapshots(before, after)
      );
   }

