   @Transactional
   public com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult batchApplyLevelPromotions(
      String year, com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyRequest request, String laterPeriodMode
   ) {
      List<com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyRequest.LevelPromotionBatchApplyItem> items = request != null && request.items() != null
         ? request.items()
         : List.of();
      if (items.isEmpty()) {
         throw new IllegalArgumentException("请选择需要办理的级别晋升记录。");
      } else {
         this.requirePayrollFeatureWrite("LEVEL_PROMOTION_WRITE");
         int promotionYear = this.resolveNormalPromotionYear(year);
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> orgPersonKeys = items.stream()
            .filter(Objects::nonNull)
            .map(item -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(item.organizationCode(), item.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById = this.payrollRepository.findCurrentHistoriesByOrgPersons(orgPersonKeys);
         LinkedHashSet<String> checkedOrganizations = new LinkedHashSet<>();
         int successCount = 0;
         ArrayList<String> failures = new ArrayList<>();
         ArrayList<String> successIds = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult.SuccessItem> successes = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyRequest.LevelPromotionBatchApplyItem item2 : items) {
            String id = item2 == null ? null : this.emptyToNull(item2.payrollHistoryId());
            if (id == null) {
               failures.add("缺少工资记录标识。");
            } else {
               try {
                  com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.resolveCurrentHistoryForLevelApply(id, item2, currentById);
                  String organizationCode = this.emptyToNull(latest.organizationCode());
                  if (organizationCode != null && checkedOrganizations.add(organizationCode)) {
                     this.accessControlService.requireOrganization(organizationCode);
                  }

                  com.dxsoft.rsgzgl.payroll.PromotionActionResult applied = this.writeLevelPromotionFromTrial(
                     latest, promotionYear, item2.toApplyRequest(), true, false, laterPeriodMode
                  );
                  successCount++;
                  successIds.add(id);
                  successes.add(new com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult.SuccessItem(id, applied.payrollHistoryId(), applied.changeType()));
               } catch (RuntimeException var21) {
                  failures.add(id + "：" + (var21.getMessage() == null ? "办理失败" : var21.getMessage()));
               }
            }
         }

         if (successCount > 0) {
            this.invalidateLevelPromotionListCache();
            this.invalidateNormalPromotionListCache();
            this.invalidatePositionChangeListCache();
         }

         int failureCount = failures.size();
         String message = failureCount == 0
            ? "批量处理完成：成功 " + successCount + " 条。"
            : "批量处理完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。" + (failures.isEmpty() ? "" : failures.get(0));
         return new com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult(successCount, failureCount, failures, successIds, successes, message);
      }
   }

