   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeLevelPromotionFromTrial(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.LevelPromotionApplyRequest request,
      boolean trustTrialPayload,
      boolean invalidateCache,
      String laterPeriodMode
   ) {
      if (request == null) {
         throw new IllegalArgumentException("缺少级别晋升办理数据。");
      } else if (latest == null || this.emptyToNull(latest.id()) == null) {
         throw new IllegalArgumentException("缺少工资记录。");
      } else if (this.isLevelPromotionProcessedInYear(latest, promotionYear)) {
         throw new IllegalArgumentException("当前记录已办理级别晋升，只能执行还原，不能再次办理。");
      } else {
         String promotedLevel;
         String promotedStep;
         Integer increaseAmount;
         Integer promotedGradeSalary;
         boolean reformRolling;
         String calculationYear;
         String nextLevelYear;
         String nextStepYear;
         if (trustTrialPayload) {
            promotedLevel = this.emptyToNull(request.promotedLevel());
            promotedStep = this.emptyToNull(request.promotedStep());
            increaseAmount = request.increaseAmount();
            promotedGradeSalary = request.promotedGradeSalary();
            reformRolling = Boolean.TRUE.equals(request.reformLevelRollingDue());
            calculationYear = reformRolling
               ? this.firstNonBlank(request.nextLevelAssessmentStartYear(), String.valueOf(promotionYear))
               : this.firstNonBlank(this.yearFromPeriod(request.calculationPeriod()), String.valueOf(promotionYear));
            nextLevelYear = this.firstNonBlank(request.nextLevelAssessmentStartYear(), calculationYear);
            nextStepYear = this.firstNonBlank(request.nextStepAssessmentStartYear(), latest.stepAssessmentStartYear(), calculationYear);
         } else {
            int uid = this.requireCurrentHistoryUid(latest.id());
            com.dxsoft.rsgzgl.payroll.LevelPromotionPreview guard = this.levelPromotionPreview(uid, promotionYear, latest);
            if (Boolean.TRUE.equals(guard.overdueFromLastYear())) {
               throw new IllegalArgumentException("上年符合级别晋升条件，请将晋升年度切换到上年后再办理。");
            }

            if (Boolean.TRUE.equals(guard.earlierStepPromotionPending())) {
               throw new IllegalArgumentException("上年符合档次晋升条件");
            }

            if (!Boolean.TRUE.equals(guard.applyEligible()) || !Boolean.TRUE.equals(guard.levelPromotionDue())) {
               throw new IllegalArgumentException("当前工资记录不满足级别晋升处理条件。");
            }

            promotedLevel = this.firstNonBlank(guard.promotedLevel(), request.promotedLevel());
            promotedStep = this.firstNonBlank(guard.promotedStep(), request.promotedStep());
            increaseAmount = guard.increaseAmount() != null && guard.increaseAmount() > 0 ? guard.increaseAmount() : request.increaseAmount();
            promotedGradeSalary = guard.promotedGradeSalary() != null && guard.promotedGradeSalary() > 0
               ? guard.promotedGradeSalary()
               : request.promotedGradeSalary();
            reformRolling = Boolean.TRUE.equals(guard.reformLevelRollingDue()) || Boolean.TRUE.equals(request.reformLevelRollingDue());
            calculationYear = reformRolling
               ? this.firstNonBlank(guard.nextLevelAssessmentStartYear(), request.nextLevelAssessmentStartYear(), String.valueOf(promotionYear))
               : this.firstNonBlank(
                  this.yearFromPeriod(guard.calculationPeriod()), this.yearFromPeriod(request.calculationPeriod()), String.valueOf(promotionYear)
               );
            nextLevelYear = this.firstNonBlank(guard.nextLevelAssessmentStartYear(), request.nextLevelAssessmentStartYear(), calculationYear);
            nextStepYear = this.firstNonBlank(guard.nextStepAssessmentStartYear(), request.nextStepAssessmentStartYear(), latest.stepAssessmentStartYear());
         }

         if (promotedLevel == null || promotedStep == null) {
            throw new IllegalArgumentException("缺少晋升后级别或档次，请重新查询试算后再办理。");
         } else if (increaseAmount == null || increaseAmount <= 0) {
            throw new IllegalArgumentException("增资额无效，请重新查询试算后再办理。");
         } else if (promotedGradeSalary != null && promotedGradeSalary > 0) {
            if (nextStepYear == null || nextStepYear.isBlank()) {
               nextStepYear = calculationYear;
            }

            String changeType = reformRolling ? "级别滚动" : "正常级别";
            if (this.isPromotionLaterPeriodCase(latest, promotionYear)) {
               if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
                  throw new IllegalArgumentException("当前为后变动人员，请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式后再办理。");
               }

               if (this.isLaterPeriodInsertRecalcMode(laterPeriodMode)) {
                  return this.writeLevelPromotionMidChain(
                     latest,
                     promotionYear,
                     changeType,
                     promotedLevel,
                     promotedStep,
                     nextLevelYear,
                     nextStepYear,
                     promotedGradeSalary,
                     increaseAmount,
                     invalidateCache
                  );
               }
            }

            String calculationMonth = "01";
            String calculationYearForMutation = calculationYear;
            if (this.isPromotionLaterPeriodCase(latest, promotionYear) && this.isLaterPeriodSequentialMode(laterPeriodMode)) {
               String tipPeriod = this.firstNonBlank(this.emptyToNull(request.calculationPeriod()), this.historyCalculationPeriod(latest));
               if (tipPeriod.length() >= 6) {
                  calculationYearForMutation = tipPeriod.substring(0, 4);
                  calculationMonth = tipPeriod.substring(4, 6);
               }
            }

            com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation mutation = this.buildLevelPromotionMutation(
               latest,
               calculationYearForMutation,
               calculationMonth,
               changeType,
               nextStepYear,
               nextLevelYear,
               promotedStep,
               promotedLevel,
               promotedGradeSalary,
               increaseAmount
            );
            String newId = this.payrollRepository.createPromotionHistoryFromSource(latest, mutation);
            if (invalidateCache) {
               this.invalidateLevelPromotionListCache();
               this.invalidateNormalPromotionListCache();
               this.invalidatePositionChangeListCache();
            }

            return this.buildAppliedPayrollChange(latest, newId, latest.id(), changeType, "级别晋升处理完成。");
         } else {
            throw new IllegalArgumentException("缺少晋升后级别工资，请重新查询试算后再办理。");
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeLevelPromotionMidChain(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip,
      int promotionYear,
      String changeType,
      String promotedLevel,
      String promotedStep,
      String nextLevelYear,
      String nextStepYear,
      Integer promotedGradeSalary,
      Integer increaseAmount,
      boolean invalidateCache
   ) {
      String organizationCode = this.emptyToNull(tip.organizationCode());
      String personCode = this.emptyToNull(tip.personCode());
      if (organizationCode != null && personCode != null) {
         String executionPeriod = this.promotionExecutionPeriod(promotionYear);
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
         if (anchor == null) {
            throw new IllegalArgumentException("未找到可插入级别晋升的历史锚点。");
         } else {
            com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation mutation = this.buildLevelPromotionMutation(
               anchor,
               executionPeriod.substring(0, 4),
               executionPeriod.substring(4, 6),
               changeType,
               nextStepYear,
               nextLevelYear,
               promotedStep,
               promotedLevel,
               promotedGradeSalary,
               increaseAmount
            );
            String nextSuccessorId = this.findBasicSalaryMidChainNextSuccessorId(organizationCode, personCode, anchor, chain);
            String newId = this.payrollRepository.insertPromotionMidChain(anchor, nextSuccessorId, mutation);
            this.recalculatePromotionMidChainSuccessors(organizationCode, personCode, nextSuccessorId, anchor.salaryStandardYearMonth());
            if (invalidateCache) {
               this.invalidateLevelPromotionListCache();
               this.invalidateNormalPromotionListCache();
               this.invalidatePositionChangeListCache();
            }

            return this.buildAppliedPayrollChange(tip, newId, tip.id(), changeType, "中段级别晋升处理完成。");
         }
      } else {
         throw new IllegalArgumentException("缺少人员单位信息。");
      }
   }

