   private com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot resolveCurrentHistoryForLevelRollback(
      String payrollHistoryId,
      com.dxsoft.rsgzgl.payroll.LevelPromotionBatchRollbackRequest.LevelPromotionBatchRollbackItem item,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById
   ) {
      String normalizedId = payrollHistoryId.trim();
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current = currentById.get(normalizedId);
      if (current != null) {
         return current;
      } else {
         String organizationCode = item == null ? null : this.emptyToNull(item.organizationCode());
         String personCode = item == null ? null : this.emptyToNull(item.personCode());
         return organizationCode != null
               && personCode != null
               && (current = this.payrollRepository.findCurrentHistoryByOrgPerson(organizationCode, personCode).orElse(null)) != null
               && this.historyIdMatches(current.id(), normalizedId)
            ? current
            : this.payrollRepository.findCurrentHistoryById(normalizedId).orElseThrow(() -> new IllegalArgumentException("未找到可还原的当前工资记录。"));
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeLevelPromotionRollback(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current) {
      return this.writeLevelPromotionRollback(current, true);
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeLevelPromotionRollback(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current, boolean invalidateCache
   ) {
      if (current != null && this.emptyToNull(current.id()) != null) {
         String organizationCode = this.emptyToNull(current.organizationCode());
         String personCode = this.emptyToNull(current.personCode());
         String previousId;
         if (organizationCode != null && personCode != null) {
            previousId = this.payrollRepository
               .findPredecessorHistoryId(organizationCode, personCode, current.id())
               .orElseThrow(() -> new IllegalArgumentException("未找到可恢复为当前工资的上一条记录。"));
            this.payrollRepository.rollbackCurrentHistory(organizationCode, personCode, current.id(), previousId);
         } else {
            previousId = this.payrollRepository.findPredecessorHistoryId(current.id()).orElseThrow(() -> new IllegalArgumentException("未找到可恢复为当前工资的上一条记录。"));
            this.payrollRepository.rollbackCurrentHistory(current.id(), previousId);
         }

         if (invalidateCache) {
            this.invalidateLevelPromotionListCache();
            this.invalidateNormalPromotionListCache();
            this.invalidatePositionChangeListCache();
         }

         return this.buildRolledBackPayrollChange(current, previousId, "级别晋升已还原。");
      } else {
         throw new IllegalArgumentException("缺少工资记录。");
      }
   }

