   public PageResponse<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> positionChangePromotionPreviews(
      String organizationCode, String keyword, Boolean includeApply, Boolean includeProcessed, PageRequest pageRequest
   ) {
      OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
      String scopedOrganizationCode = this.emptyToNull(organizationCode);
      boolean showApply = !Boolean.FALSE.equals(includeApply);
      boolean showProcessed = !Boolean.FALSE.equals(includeProcessed);
      if (!showApply && !showProcessed) {
         return PageResponse.of(List.of(), pageRequest, 0L);
      } else {
         String cacheKey = this.positionChangeListCacheKey(scope, organizationCode, keyword);
         List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> allItems = this.cachedPositionChangeList(cacheKey);
         if (allItems == null) {
            allItems = this.computePositionChangeDueOnlyItems(scope, scopedOrganizationCode, keyword);
            this.positionChangeListCache
               .put(cacheKey, new com.dxsoft.rsgzgl.payroll.PayrollService.CachedPositionChangeList(System.currentTimeMillis(), List.copyOf(allItems)));
         }

         List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> items = allItems.stream()
            .filter(item -> this.matchesPositionChangeStatusFilter(item, null, showApply, showProcessed))
            .toList();
         int fromIndex = pageRequest.offset();
         if (fromIndex >= items.size()) {
            return PageResponse.of(List.of(), pageRequest, (long)items.size());
         } else {
            int toIndex = Math.min(fromIndex + pageRequest.size(), items.size());
            return PageResponse.of(items.subList(fromIndex, toIndex), pageRequest, (long)items.size());
         }
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> computePositionChangeDueOnlyItems(
      OrganizationScope scope, String organizationCode, String keyword
   ) {
      long startedAt = System.nanoTime();
      List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows = this.payrollRepository
         .findPositionChangePromotionCandidateRows(scope, organizationCode, keyword);
      long afterCandidates = System.nanoTime();
      if (candidateRows.isEmpty()) {
         return List.of();
      } else {
         LinkedHashMap<Integer, com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> uniqueByUid = new LinkedHashMap<>();

         for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : candidateRows) {
            uniqueByUid.putIfAbsent(Integer.valueOf(row.uid()), row);
         }

         List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> var30 = new ArrayList<>(uniqueByUid.values());
         com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache = this.loadPositionChangePreviewCache(var30, false);
         long afterCache = System.nanoTime();
         LinkedHashSet<Integer> selectedUids = new LinkedHashSet<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> rowsNeedingSummary = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : var30) {
            if (!row.processed() && !row.pendingAppointmentChange()) {
               rowsNeedingSummary.add(row);
            } else {
               selectedUids.add(Integer.valueOf(row.uid()));
            }
         }

         List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> summaries = rowsNeedingSummary.isEmpty()
            ? List.of()
            : this.runPositionChangeListInParallel(
               rowsNeedingSummary,
               rowx -> this.positionChangePromotionListItem(
                     rowx.uid(), cache, com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache.empty(), true, true
                  )
            );

         for (int i = 0; i < rowsNeedingSummary.size(); i++) {
            com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow rowx = rowsNeedingSummary.get(i);
            com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem summary = summaries.get(i);
            if (summary != null && this.matchesPositionChangeStatusFilter(summary, rowx, true, true)) {
               selectedUids.add(Integer.valueOf(rowx.uid()));
            }
         }

         long afterFilter = System.nanoTime();
         if (selectedUids.isEmpty()) {
            return List.of();
         } else {
            List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> selectedRows = var30.stream()
               .filter(rowx -> selectedUids.contains(Integer.valueOf(rowx.uid())))
               .toList();
            this.fillPositionChangeSalaries(cache, selectedRows);
            long afterSalary = System.nanoTime();
            LinkedHashMap<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> pendingHistories = new LinkedHashMap<>();

            for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow rowx : selectedRows) {
               if (!rowx.processed()) {
                  com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = cache.histories().get(rowx.uid());
                  if (history != null) {
                     pendingHistories.put(Integer.valueOf(rowx.uid()), history);
                  }
               }
            }

            com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessments = pendingHistories.isEmpty()
               ? com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache.empty()
               : this.loadLevelPromotionAssessmentCache(pendingHistories, LocalDate.now().getYear());
            long afterAssess = System.nanoTime();
            List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> fullItems = this.runPositionChangeListInParallel(
               selectedRows, rowxx -> this.positionChangePromotionListItem(rowxx.uid(), cache, assessments, false, false)
            );
            LinkedHashMap<String, com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> byHistoryId = new LinkedHashMap<>();

            for (int ix = 0; ix < fullItems.size(); ix++) {
               com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem item = fullItems.get(ix);
               com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow rowxx = ix < selectedRows.size() ? selectedRows.get(ix) : null;
               if (item != null && this.matchesPositionChangeStatusFilter(item, rowxx, true, true) && this.emptyToNull(item.payrollHistoryId()) != null) {
                  byHistoryId.putIfAbsent(item.payrollHistoryId(), item);
               }
            }

            ArrayList<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> filtered = new ArrayList<>(byHistoryId.values());
            log.info(
               "position-change list cold: candidates={} selected={} visible={} sql={}ms cache={}ms filter={}ms salary={}ms assess={}ms full={}ms total={}ms",
               new Object[]{
                  uniqueByUid.size(),
                  selectedUids.size(),
                  filtered.size(),
                  (afterCandidates - startedAt) / 1000000L,
                  (afterCache - afterCandidates) / 1000000L,
                  (afterFilter - afterCache) / 1000000L,
                  (afterSalary - afterFilter) / 1000000L,
                  (afterAssess - afterSalary) / 1000000L,
                  (System.nanoTime() - afterAssess) / 1000000L,
                  (System.nanoTime() - startedAt) / 1000000L
               }
            );
            return filtered;
         }
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> enrichPositionChangeListPage(
      List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> page
   ) {
      if (page != null && !page.isEmpty()) {
         LinkedHashMap<String, Integer> uidByHistoryId = new LinkedHashMap<>();

         for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem item : page) {
            if (item != null && this.emptyToNull(item.payrollHistoryId()) != null) {
               try {
                  uidByHistoryId.putIfAbsent(item.payrollHistoryId(), Integer.valueOf(this.requireCurrentHistoryUid(item.payrollHistoryId())));
               } catch (RuntimeException var10) {
               }
            }
         }

         if (uidByHistoryId.isEmpty()) {
            return page;
         } else {
            com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache = this.loadPositionChangePreviewCacheForUids(
               uidByHistoryId.values().stream().distinct().toList()
            );
            com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache = this.loadLevelPromotionAssessmentCache(
               cache.histories(), LocalDate.now().getYear()
            );
            ArrayList<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> enriched = new ArrayList<>(page.size());

            for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem summary : page) {
               Integer uid = summary == null ? null : uidByHistoryId.get(summary.payrollHistoryId());
               if (uid == null) {
                  enriched.add(summary);
               } else {
                  com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem full = this.positionChangePromotionListItem(
                     uid, cache, assessmentCache, false, true
                  );
                  if (full == null) {
                     enriched.add(summary);
                  } else {
                     enriched.add(
                        new com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem(
                           full.payrollHistoryId(),
                           full.organizationCode(),
                           full.personCode(),
                           full.name(),
                           full.currentPositionCode(),
                           full.currentPositionName(),
                           full.newPositionCode(),
                           full.newPositionName(),
                           full.changeType(),
                           full.positionStartYearMonth(),
                           full.effectivePeriod(),
                           full.currentLevel(),
                           full.currentStep(),
                           full.promotedLevel(),
                           full.promotedStep(),
                           full.positionSalaryIncrease(),
                           full.netPositionSalaryIncrease(),
                           full.gradeSalaryIncrease(),
                           full.totalIncrease(),
                           summary.note(),
                           summary.rollbackEligible(),
                           summary.applyEligible(),
                           full.sequenceConversion()
                        )
                     );
                  }
               }
            }

            return enriched;
         }
      } else {
         return List.of();
      }
   }

   private String positionChangeListCacheKey(OrganizationScope scope, String organizationCode, String keyword) {
      String organizations = scope != null && !scope.all() ? scope.organizationCodes().stream().sorted().collect(Collectors.joining(",")) : "*";
      return organizations + "|" + Objects.toString(this.emptyToNull(organizationCode), "") + "|" + Objects.toString(this.emptyToNull(keyword), "");
   }

   private List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem> cachedPositionChangeList(String cacheKey) {
      com.dxsoft.rsgzgl.payroll.PayrollService.CachedPositionChangeList cached = this.positionChangeListCache.get(cacheKey);
      if (cached == null) {
         return null;
      } else if (System.currentTimeMillis() - cached.createdAtMillis() > 120000L) {
         this.positionChangeListCache.remove(cacheKey, cached);
         return null;
      } else {
         return cached.items();
      }
   }

   private void invalidatePositionChangeListCache() {
      this.positionChangeListCache.clear();
   }

   private <T> List<T> runPositionChangeListInParallel(
      List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> rows, Function<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow, T> task
   ) {
      if (rows != null && !rows.isEmpty()) {
         if (rows.size() >= 16) {
            T[] results = (T[])(new Object[rows.size()]);
            IntStream.range(0, rows.size()).parallel().forEach(index -> results[index] = task.apply(rows.get(index)));
            return Arrays.asList(results);
         } else {
            ArrayList<T> results = new ArrayList<>(rows.size());

            for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : rows) {
               results.add(task.apply(row));
            }

            return results;
         }
      } else {
         return List.of();
      }
   }

   private boolean matchesPositionChangeStatusFilter(
      com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem item,
      com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow candidateRow,
      boolean showApply,
      boolean showProcessed
   ) {
      if (item == null) {
         return false;
      } else {
         boolean processed = Boolean.TRUE.equals(item.rollbackEligible());
         if (processed) {
            return showProcessed;
         } else if (!showApply) {
            return false;
         } else {
            return candidateRow != null && candidateRow.pendingAppointmentChange()
               ? true
               : Boolean.TRUE.equals(item.applyEligible())
                  || this.isPositionChangePriorPromotionRequiredNote(item.note())
                  || this.hasVisiblePendingPositionChange(item);
         }
      }
   }

   private boolean hasVisiblePendingPositionChange(com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem item) {
      if (Boolean.TRUE.equals(item.rollbackEligible())) {
         return false;
      } else {
         String note = this.emptyToNull(item.note());
         if (note != null && note.contains("待处理职务变化")) {
            return true;
         } else {
            return !Objects.equals(this.emptyToNull(item.currentPositionCode()), this.emptyToNull(item.newPositionCode()))
               ? true
               : !Objects.equals(this.emptyToNull(item.currentPositionName()), this.emptyToNull(item.newPositionName()));
         }
      }
   }

   private boolean isPositionChangePriorPromotionRequiredNote(String note) {
      String text = this.emptyToNull(note);
      return text != null && text.contains("请先办理");
   }

