   @Transactional(
      readOnly = true
   )
   public PageResponse<com.dxsoft.rsgzgl.payroll.RegularizationPreview> regularizationPreviews(
      String organizationCode, String keyword, Boolean includeApply, Boolean includeProcessed, PageRequest pageRequest
   ) {
      boolean showApply = !Boolean.FALSE.equals(includeApply);
      boolean showProcessed = !Boolean.FALSE.equals(includeProcessed);
      if (!showApply && !showProcessed) {
         return PageResponse.of(List.of(), pageRequest, 0L);
      } else {
         OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
         com.dxsoft.rsgzgl.payroll.ProbationPersonnelPage page = this.payrollRepository
            .findProbationPersonnelPage(scope, this.emptyToNull(organizationCode), keyword, PageRequest.of(0, 100000));
         List<Integer> uids = page.uids();
         if (uids.isEmpty()) {
            return PageResponse.of(List.of(), pageRequest, 0L);
         } else {
            com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationBatchContext context = this.buildRegularizationBatchContext(uids);
            List<com.dxsoft.rsgzgl.payroll.RegularizationPreview> previews = uids.stream()
               .map(uid -> this.regularizationPreview(uid, context))
               .filter(preview -> this.matchesApplyRollbackStatusFilter(preview, showApply, showProcessed))
               .toList();
            int fromIndex = pageRequest.offset();
            if (fromIndex >= previews.size()) {
               return PageResponse.of(List.of(), pageRequest, (long)previews.size());
            } else {
               int toIndex = Math.min(fromIndex + pageRequest.size(), previews.size());
               return PageResponse.of(previews.subList(fromIndex, toIndex), pageRequest, (long)previews.size());
            }
         }
      }
   }

