   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyRegularizationHighGrade(String payrollHistoryId) {
      int uid = this.requireCurrentHistoryUid(payrollHistoryId);
      com.dxsoft.rsgzgl.payroll.RegularizationHighGradePreview preview = this.regularizationHighGradePreview(uid);
      if (Boolean.TRUE.equals(preview.rollbackEligible())) {
         throw new IllegalArgumentException("当前记录已办理转正高定，只能执行还原，不能再次办理。");
      } else if (Boolean.TRUE.equals(preview.applyEligible())) {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository
            .findLatestHistory(uid)
            .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
         String period = this.historyCalculationPeriod(latest);
         boolean institution = this.isInstitutionPosition(latest.positionCode());
         com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation mutation = this.buildGradeSalaryPromotionMutation(
            latest,
            period.substring(0, 4),
            period.substring(4, 6),
            "转正高定",
            latest.stepAssessmentStartYear(),
            latest.levelAssessmentStartYear(),
            preview.targetStep(),
            institution ? preview.targetStep() : latest.gradeSalaryLevel(),
            this.gradeStepDifferenceForWrite(latest.gradeSalaryStep()),
            preview.targetGradeSalary(),
            preview.increaseAmount()
         );
         String newId = this.payrollRepository.createPromotionHistoryFromLatest(uid, mutation);
         return this.buildAppliedPayrollChange(latest, newId, payrollHistoryId, "转正高定", "转正高定档次薪级处理完成。");
      } else {
         throw new IllegalArgumentException(preview.note() != null && !preview.note().isBlank() ? preview.note() : "当前工资记录不满足转正高定档次薪级处理条件。");
      }
   }

