   private String normalizeBasicSalaryTarget(String targetStandardYearMonth) {
      String target = this.emptyToNull(targetStandardYearMonth);
      if (target == null) {
         throw new IllegalArgumentException("请选择调标标准年月。");
      } else {
         target = target.replace(".", "");
         if (target.length() < 6) {
            throw new IllegalArgumentException("调标标准年月不完整。");
         } else {
            return target;
         }
      }
   }

