   @Transactional
   public com.dxsoft.rsgzgl.payroll.PromotionActionResult applyEducationPromotion(String payrollHistoryId) {
      int uid = this.requireCurrentHistoryUid(payrollHistoryId);
      com.dxsoft.rsgzgl.payroll.PayrollService.EducationPromotionPreviewBuild build = this.buildEducationPromotionPreview(uid);
      com.dxsoft.rsgzgl.payroll.EducationPromotionPreview preview = build.preview();
      if (Boolean.TRUE.equals(preview.rollbackEligible())) {
         throw new IllegalArgumentException("当前记录已办理学历变化，只能执行还原，不能再次办理。");
      } else if (!Boolean.TRUE.equals(preview.applyEligible())) {
         throw new IllegalArgumentException(this.emptyToNull(preview.note()) == null ? "当前工资记录不满足学历晋升处理条件。" : preview.note());
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository
            .findLatestHistory(uid)
            .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
         String applyPeriod = this.educationPromotionApplyPeriod(preview.graduationDate(), this.historyCalculationPeriod(latest));
         String promotedPositionCode = this.firstNonBlank(preview.promotedPositionCode(), latest.positionCode());
         String promotedPositionName = this.firstNonBlank(
            preview.promotedPositionName(),
            Objects.equals(this.emptyToNull(promotedPositionCode), this.emptyToNull(latest.positionCode()))
               ? latest.positionName()
               : this.firstNonBlank(preview.standardPositionName(), latest.positionName())
         );
         Integer promotedPositionSalary = preview.promotedPositionSalary() == null ? latest.storedPositionSalary() : preview.promotedPositionSalary();
         Integer promotedGradeSalary = preview.promotedGradeSalary() == null ? latest.storedGradeSalary() : preview.promotedGradeSalary();
         com.dxsoft.rsgzgl.payroll.PositionChangeHistoryMutation mutation = this.buildPositionChangeMutationWithTeachingIncrease(
            latest,
            applyPeriod.substring(0, 4),
            applyPeriod.substring(4, 6),
            "学历变化",
            preview.nextStepAssessmentStartYear(),
            preview.nextLevelAssessmentStartYear(),
            promotedPositionCode,
            promotedPositionName,
            promotedPositionSalary,
            preview.promotedStep(),
            preview.promotedLevel(),
            this.gradeStepDifferenceForWrite(preview.promotedGradeStepDifference()),
            promotedGradeSalary,
            latest.storedTechnicalGradeSalary(),
            null,
            null,
            null,
            latest.storedPgbc(),
            this.nullToZero(preview.totalIncrease()),
            "学历变化"
         );
         String newId = this.payrollRepository.createPositionChangeHistoryFromSource(latest, mutation);
         return this.buildAppliedPayrollChange(latest, newId, payrollHistoryId, "学历变化", "学历晋升处理完成。");
      }
   }

   private String educationPromotionApplyPeriod(String graduationDate, String fallbackPeriod) {
      String effect = this.educationPromotionEffectPeriod(graduationDate);
      if (effect.length() >= 6) {
         return effect.substring(0, 6);
      } else {
         String tipPeriod = this.normalizeYearMonth(fallbackPeriod);
         if (tipPeriod.length() >= 6) {
            return tipPeriod.substring(0, 6);
         } else {
            throw new IllegalArgumentException("学历晋升执行年月不完整。");
         }
      }
   }

   private String educationPromotionEffectPeriod(String graduationDate) {
      String normalized = this.normalizeYearMonth(graduationDate);
      return normalized.length() < 6 ? "" : this.nextMonth(normalized);
   }

   private String educationPromotionChangeYear(String graduationDate, String fallbackYear) {
      int year = this.yearOf(this.educationPromotionEffectPeriod(graduationDate));
      return year > 0 ? String.valueOf(year) : fallbackYear;
   }

