   public com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyResult batchApplyRegularizations(com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyRequest request) {
      List<com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyRequest.RegularizationBatchApplyItem> items = request != null && request.items() != null
         ? request.items()
         : List.of();
      if (items.isEmpty()) {
         throw new IllegalArgumentException("请选择需要办理的转正定级记录。");
      } else {
         this.requirePayrollFeatureWrite("REGULARIZATION_WRITE");
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> orgPersonKeys = items.stream()
            .filter(Objects::nonNull)
            .map(item -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(item.organizationCode(), item.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById = this.payrollRepository.findCurrentHistoriesByOrgPersons(orgPersonKeys);
         LinkedHashSet<String> checkedOrganizations = new LinkedHashSet<>();
         int successCount = 0;
         ArrayList<String> failures = new ArrayList<>();
         ArrayList<String> successIds = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyResult.SuccessItem> successes = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyRequest.RegularizationBatchApplyItem item : items) {
            String id = item == null ? null : this.emptyToNull(item.payrollHistoryId());
            if (id == null) {
               failures.add("缺少工资记录标识。");
            } else {
               try {
                  com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.resolveCurrentHistoryForRegularizationApply(id, item, currentById);
                  String organizationCode = this.emptyToNull(latest.organizationCode());
                  if (organizationCode != null && checkedOrganizations.add(organizationCode)) {
                     this.accessControlService.requireOrganization(organizationCode);
                  }

                  com.dxsoft.rsgzgl.payroll.PromotionActionResult applied = this.writeRegularizationFromTrial(latest, item.toApplyRequest());
                  successCount++;
                  successIds.add(id);
                  successes.add(new com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyResult.SuccessItem(id, applied.payrollHistoryId(), applied.changeType()));
               } catch (RuntimeException var16) {
                  failures.add(id + "：" + (var16.getMessage() == null ? "办理失败" : var16.getMessage()));
               }
            }
         }

         int failureCount = failures.size();
         String message = failureCount == 0
            ? "批量处理完成：成功 " + successCount + " 条。"
            : "批量处理完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。" + (failures.isEmpty() ? "" : failures.get(0));
         return new com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyResult(successCount, failureCount, failures, successIds, successes, message);
      }
   }

