   private com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot resolveCurrentHistoryForRegularizationApply(
      String payrollHistoryId,
      com.dxsoft.rsgzgl.payroll.RegularizationBatchApplyRequest.RegularizationBatchApplyItem item,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById
   ) {
      String normalizedId = payrollHistoryId.trim();
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = currentById == null ? null : currentById.get(normalizedId);
      if (latest != null) {
         return latest;
      } else {
         String organizationCode = item == null ? null : this.emptyToNull(item.organizationCode());
         String personCode = item == null ? null : this.emptyToNull(item.personCode());
         return organizationCode != null
               && personCode != null
               && (latest = this.payrollRepository.findCurrentHistoryByOrgPerson(organizationCode, personCode).orElse(null)) != null
               && this.historyIdMatches(latest.id(), normalizedId)
            ? latest
            : this.payrollRepository.findCurrentHistoryById(normalizedId).orElseThrow(() -> new IllegalArgumentException("未找到可办理的当前工资记录。"));
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeRegularizationFromTrial(
      String payrollHistoryId, com.dxsoft.rsgzgl.payroll.RegularizationApplyRequest request
   ) {
      if (request == null) {
         throw new IllegalArgumentException("缺少转正定级办理数据。");
      } else {
         String normalizedId = this.emptyToNull(payrollHistoryId);
         if (normalizedId == null) {
            throw new IllegalArgumentException("缺少工资记录标识。");
         } else {
            this.requirePayrollFeatureWrite("REGULARIZATION_WRITE");
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.resolveCurrentHistoryForRegularizationSingleApply(normalizedId, request);
            this.accessControlService.requireOrganization(latest.organizationCode());
            return this.writeRegularizationFromTrial(latest, request);
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot resolveCurrentHistoryForRegularizationSingleApply(
      String payrollHistoryId, com.dxsoft.rsgzgl.payroll.RegularizationApplyRequest request
   ) {
      String organizationCode = request == null ? null : this.emptyToNull(request.organizationCode());
      String personCode = request == null ? null : this.emptyToNull(request.personCode());
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot byOrgPerson;
      return organizationCode != null
            && personCode != null
            && (byOrgPerson = this.payrollRepository.findCurrentHistoryByOrgPerson(organizationCode, personCode).orElse(null)) != null
            && this.historyIdMatches(byOrgPerson.id(), payrollHistoryId)
         ? byOrgPerson
         : this.payrollRepository
            .findCurrentHistoryById(payrollHistoryId)
            .orElseThrow(() -> new NotFoundException("Current payroll history not found: " + payrollHistoryId));
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult writeRegularizationFromTrial(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, com.dxsoft.rsgzgl.payroll.RegularizationApplyRequest request
   ) {
      if (request == null) {
         throw new IllegalArgumentException("缺少转正定级办理数据。");
      } else if (latest == null || this.emptyToNull(latest.id()) == null) {
         throw new IllegalArgumentException("缺少工资记录。");
      } else if ("转正定级".equals(this.emptyToNull(latest.calculationType()))) {
         throw new IllegalArgumentException("当前记录已办理转正定级，只能执行还原，不能再次办理。");
      } else {
         String regularPositionCode = this.emptyToNull(request.regularPositionCode());
         String regularStep = this.emptyToNull(request.regularStep());
         if (regularPositionCode == null) {
            throw new IllegalArgumentException("缺少定级岗位，请重新查询试算后再办理。");
         } else if (regularStep == null) {
            throw new IllegalArgumentException("缺少定级档次，请重新查询试算后再办理。");
         } else {
            Integer increaseAmount = request.increaseAmount() == null ? 0 : request.increaseAmount();
            com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates dates = this.payrollRepository
               .findPersonnelRegularizationDates(latest.organizationCode(), latest.personCode())
               .orElse(new com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates(latest.workStartYearMonth(), "", "", ""));
            boolean nonInternPath = this.isNonInternProbationRegularization(latest.positionCode(), latest.calculationType(), dates.classificationTag());
            String preferredPeriod = this.normalizeYearMonth(request.calculationPeriod());
            String applyPeriod = preferredPeriod.length() == 6 ? preferredPeriod : this.resolveRegularizationApplyPeriod(dates, latest, nonInternPath);
            String year = applyPeriod.substring(0, 4);
            String month = applyPeriod.substring(4, 6);
            String nextAssessmentYear = nonInternPath ? this.emptyToNull(latest.stepAssessmentStartYear()) : year;
            String nextLevelAssessmentYear = nonInternPath ? this.emptyToNull(latest.levelAssessmentStartYear()) : year;
            com.dxsoft.rsgzgl.payroll.PositionChangeHistoryMutation mutation = this.buildPositionChangeMutationWithTeachingIncrease(
               latest,
               year,
               month,
               "转正定级",
               nextAssessmentYear,
               nextLevelAssessmentYear,
               regularPositionCode,
               request.regularPositionName(),
               request.regularPositionSalary(),
               regularStep,
               request.regularLevel() == null ? "" : request.regularLevel(),
               "",
               request.regularBaseSalary(),
               latest.storedTechnicalGradeSalary(),
               null,
               null,
               null,
               latest.storedPgbc(),
               increaseAmount,
               null
            );
            String newId = this.payrollRepository.createPositionChangeHistoryFromSource(latest, mutation);
            this.payrollRepository.updatePersonnelClassificationTag(latest.organizationCode(), latest.personCode(), "已定级人员");
            return this.buildAppliedPayrollChange(latest, newId, latest.id(), "转正定级", "转正定级处理完成。");
         }
      }
   }

