   @Transactional(
      readOnly = true
   )
   public PageResponse<com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryPreview> newPersonnelSalaryDeterminations(
      String organizationCode, String keyword, Boolean includeApply, Boolean includeProcessed, PageRequest pageRequest
   ) {
      boolean showApply = !Boolean.FALSE.equals(includeApply);
      boolean showProcessed = !Boolean.FALSE.equals(includeProcessed);
      if (!showApply && !showProcessed) {
         return PageResponse.of(List.of(), pageRequest, 0L);
      } else {
         OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
         boolean filterBoth = showApply && showProcessed;
         if (filterBoth) {
            com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryCandidatePage page = this.payrollRepository
               .findNewPersonnelSalaryCandidates(scope, this.emptyToNull(organizationCode), keyword, pageRequest);
            List<com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryPreview> content = page.rows()
               .stream()
               .map(this::toNewPersonnelSalaryPreview)
               .filter(preview -> this.matchesApplyRollbackStatusFilter(preview, true, true))
               .toList();
            if (content.size() == page.rows().size()) {
               return PageResponse.of(content, pageRequest, page.total());
            }
         }

         com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryCandidatePage all = this.payrollRepository
            .findNewPersonnelSalaryCandidates(scope, this.emptyToNull(organizationCode), keyword, PageRequest.of(0, 100000));
         List<com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryPreview> filtered = all.rows()
            .stream()
            .map(this::toNewPersonnelSalaryPreview)
            .filter(preview -> this.matchesApplyRollbackStatusFilter(preview, showApply, showProcessed))
            .toList();
         int fromIndex = pageRequest.offset();
         if (fromIndex >= filtered.size()) {
            return PageResponse.of(List.of(), pageRequest, (long)filtered.size());
         } else {
            int toIndex = Math.min(fromIndex + pageRequest.size(), filtered.size());
            return PageResponse.of(filtered.subList(fromIndex, toIndex), pageRequest, (long)filtered.size());
         }
      }
   }

   private boolean matchesApplyRollbackStatusFilter(Object preview, boolean showApply, boolean showProcessed) {
      if (preview == null) {
         return false;
      } else {
         Boolean rollbackEligible = null;
         Boolean applyEligible = null;
         if (preview instanceof com.dxsoft.rsgzgl.payroll.EducationPromotionPreview item) {
            rollbackEligible = item.rollbackEligible();
            applyEligible = item.applyEligible();
         } else if (preview instanceof com.dxsoft.rsgzgl.payroll.RegularizationPreview item) {
            rollbackEligible = item.rollbackEligible();
            applyEligible = item.applyEligible();
         } else if (preview instanceof com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryPreview item) {
            rollbackEligible = item.rollbackEligible();
            applyEligible = item.applyEligible();
         } else {
            if (!(preview instanceof com.dxsoft.rsgzgl.payroll.SalaryStandardAdjustmentPreview item)) {
               return false;
            }

            rollbackEligible = item.rollbackEligible();
            applyEligible = item.applyEligible();
         }

         boolean processed = Boolean.TRUE.equals(rollbackEligible);
         return processed ? showProcessed : Boolean.TRUE.equals(applyEligible) && showApply;
      }
   }

   @Transactional(
      readOnly = true
   )
   public com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryDetail newPersonnelSalaryDeterminationDetail(int uid) {
      com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryCandidate candidate = this.payrollRepository
         .findNewPersonnelSalaryCandidate(uid)
         .orElseThrow(() -> new NotFoundException("未找到可办理新增人员确定工资的人员：" + uid));
      this.accessControlService.requireOrganization(candidate.organizationCode());
      com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryPreview preview = this.toNewPersonnelSalaryPreview(candidate);
      String changeType = Boolean.TRUE.equals(preview.rollbackEligible()) && this.emptyToNull(candidate.currentChangeType()) != null
         ? candidate.currentChangeType()
         : this.resolveNewPersonnelChangeType(candidate);
      String applyPeriod = this.resolveNewPersonnelApplyPeriod(candidate, changeType);
      ArrayList<String> lines = new ArrayList<>();
      lines.add(
         "进入方式："
            + this.emptyToDash(candidate.joinType())
            + "，参加工作 "
            + this.formatYearMonth(candidate.workStartYearMonth())
            + "，进入本单位 "
            + this.formatYearMonth(candidate.joinYearMonth())
            + "。"
      );
      lines.add("拟办变动类别：" + this.emptyToDash(changeType) + "，起薪年月 " + this.formatYearMonth(applyPeriod) + "。");
      String positionCode = this.emptyToNull(candidate.positionCode());
      String positionName = this.emptyToNull(candidate.positionName());
      String projectedLevel = "";
      String projectedStep = "";
      String executeLevel = "";
      String executeStep = "";
      String levelStart = this.valueOrEmpty(candidate.tipLevelAssessmentStartYear());
      String stepStart = this.valueOrEmpty(candidate.tipStepAssessmentStartYear());
      Integer positionSalary = null;
      Integer gradeSalary = null;
      Integer performanceAllowance = null;
      Integer subsidyAllowance = null;
      Integer calculatedTotal = preview.calculatedTotal();
      String tipLevel = this.valueOrEmpty(candidate.tipGradeSalaryLevel());
      String tipStep = this.valueOrEmpty(candidate.tipPositionSalaryGrade());
      String tipLevelStart = this.valueOrEmpty(candidate.tipLevelAssessmentStartYear());
      String tipStepStart = this.valueOrEmpty(candidate.tipStepAssessmentStartYear());
      String tipPositionCode = "";
      String tipPositionName = "";
      Integer tipPositionSalary = null;
      Integer tipGradeSalary = null;
      Integer tipPerformanceAllowance = null;
      Integer tipSubsidyAllowance = null;
      Integer tipTotal = candidate.storedTotal();
      boolean tipBaseCleared = false;
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip = null;
      Object pathNote;
      if (Boolean.TRUE.equals(preview.rollbackEligible()) && this.emptyToNull(candidate.payrollHistoryId()) != null) {
         tip = this.payrollRepository.findPayrollHistoryById(candidate.payrollHistoryId()).orElse(null);
         pathNote = "已办理" + this.emptyToDash(changeType) + "，以下为当前工资记录。";
         if (tip != null) {
            positionCode = tip.positionCode();
            positionName = tip.positionName();
            executeLevel = this.valueOrEmpty(tip.gradeSalaryLevel());
            executeStep = this.valueOrEmpty(tip.positionSalaryGrade());
            levelStart = this.valueOrEmpty(tip.levelAssessmentStartYear());
            stepStart = this.valueOrEmpty(tip.stepAssessmentStartYear());
            positionSalary = tip.storedPositionSalary();
            gradeSalary = tip.storedGradeSalary();
            performanceAllowance = tip.storedPerformanceAllowance();
            subsidyAllowance = tip.storedSubsidyAllowance();
            calculatedTotal = tip.storedTotal();
            projectedLevel = executeLevel;
            projectedStep = executeStep;
            Optional<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessor = this.payrollRepository
               .findPredecessorHistory(tip.organizationCode(), tip.personCode(), tip.id());
            if (predecessor.isPresent()) {
               com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = predecessor.get();
               tipLevel = this.valueOrEmpty(before.gradeSalaryLevel());
               tipStep = this.valueOrEmpty(before.positionSalaryGrade());
               if (this.emptyToNull(tipLevel) == null && this.emptyToNull(tipStep) == null) {
                  tipBaseCleared = true;
                  tipPositionCode = "";
                  tipPositionName = "";
                  tipLevelStart = "";
                  tipStepStart = "";
                  tipPositionSalary = null;
                  tipGradeSalary = null;
                  tipPerformanceAllowance = null;
                  tipSubsidyAllowance = null;
                  tipTotal = null;
                  pathNote = "已办理" + this.emptyToDash(changeType) + "，办理前无有效级别/档次，左侧为空，右侧为当前执行工资。";
                  lines.add("办理前无有效级别/档次（空种子记录），基础/原值（含职务）已清空。");
               } else {
                  tipPositionCode = this.valueOrEmpty(before.positionCode());
                  tipPositionName = this.valueOrEmpty(before.positionName());
                  tipLevelStart = this.valueOrEmpty(before.levelAssessmentStartYear());
                  tipStepStart = this.valueOrEmpty(before.stepAssessmentStartYear());
                  tipPositionSalary = this.positiveOrNull(before.storedPositionSalary());
                  tipGradeSalary = this.positiveOrNull(before.storedGradeSalary());
                  tipPerformanceAllowance = this.positiveOrNull(before.storedPerformanceAllowance());
                  tipSubsidyAllowance = this.positiveOrNull(before.storedSubsidyAllowance());
                  tipTotal = this.positiveOrNull(before.storedTotal());
                  pathNote = "已办理" + this.emptyToDash(changeType) + "，左侧为办理前工资，右侧为当前执行工资。";
                  lines.add(
                     "办理前职务 "
                        + this.positionDisplay(before.positionCode(), before.positionName())
                        + "，级别/档次 "
                        + this.emptyToDash(tipLevel)
                        + "/"
                        + this.emptyToDash(tipStep)
                        + "，起算年 "
                        + this.emptyToDash(tipLevelStart)
                        + "/"
                        + this.emptyToDash(tipStepStart)
                        + "，合计 "
                        + this.nullToZero(tipTotal)
                        + "。"
                  );
               }
            } else {
               tipBaseCleared = true;
               tipPositionCode = "";
               tipPositionName = "";
               tipLevel = "";
               tipStep = "";
               tipLevelStart = "";
               tipStepStart = "";
               tipPositionSalary = null;
               tipGradeSalary = null;
               tipPerformanceAllowance = null;
               tipSubsidyAllowance = null;
               tipTotal = null;
               pathNote = "已办理" + this.emptyToDash(changeType) + "，无办理前工资史（首条建档），以下为当前执行工资。";
            }

            if ("见习工资".equals(this.emptyToNull(changeType)) || "见习工资".equals(this.emptyToNull(tip.calculationType()))) {
               int includedSubsidy = this.nullToZero(subsidyAllowance);
               if (includedSubsidy != 0) {
                  calculatedTotal = this.nullToZero(calculatedTotal) - includedSubsidy;
                  subsidyAllowance = 0;
                  lines.add("见习期不发工作性津贴。");
               } else {
                  subsidyAllowance = 0;
                  lines.add("见习期不发工作性津贴。");
               }
            }

            lines.add(
               "当前职务 "
                  + this.positionDisplay(positionCode, positionName)
                  + "，级别/档次 "
                  + this.emptyToDash(executeLevel)
                  + "/"
                  + this.emptyToDash(executeStep)
                  + "，起算年 "
                  + this.emptyToDash(levelStart)
                  + "/"
                  + this.emptyToDash(stepStart)
                  + "。"
            );
            lines.add(
               this.newPersonnelSalaryAmountExplanation(positionCode, positionSalary, gradeSalary, performanceAllowance, subsidyAllowance, calculatedTotal)
            );
         }
      } else if (this.usesPeerProjectionForNewPersonnel(candidate)) {
         boolean transferInPath = this.isTransferInJoinType(candidate);
         pathNote = transferInPath
            ? "有工作经历调入（" + this.emptyToDash(changeType) + "）：同等条件推算后执行" + this.emptyToDash(changeType) + "。"
            : (this.isInstitutionPosition(positionCode) ? "有工作经历新招（事业）：同等条件推算后按推算结果执行新进工资。" : "有工作经历新招（公务员）：同等条件推算后低一档执行见习工资；满一年转正定级恢复推算档次。");
         lines.add((String)pathNote);
         if (applyPeriod.length() == 6 && this.emptyToNull(positionCode) != null) {
            try {
               tip = this.payrollRepository.findLatestHistory(uid).orElse(null);
               if (tip == null) {
                  tipLevel = "";
                  tipStep = "";
                  tipLevelStart = "";
                  tipStepStart = "";
                  tipTotal = null;
                  lines.add("当前无工资史，详情暂不做同等条件推算试算；办理时会自动建档并推算。");
               } else {
                  tipLevel = this.valueOrEmpty(tip.gradeSalaryLevel());
                  tipStep = this.valueOrEmpty(tip.positionSalaryGrade());
                  if (this.emptyToNull(tipLevel) == null && this.emptyToNull(tipStep) == null) {
                     tipBaseCleared = true;
                     tipPositionCode = "";
                     tipPositionName = "";
                     tipLevelStart = "";
                     tipStepStart = "";
                     tipPositionSalary = null;
                     tipGradeSalary = null;
                     tipPerformanceAllowance = null;
                     tipSubsidyAllowance = null;
                     tipTotal = null;
                  } else {
                     tipPositionCode = this.valueOrEmpty(tip.positionCode());
                     tipPositionName = this.valueOrEmpty(tip.positionName());
                     tipLevelStart = this.valueOrEmpty(tip.levelAssessmentStartYear());
                     tipStepStart = this.valueOrEmpty(tip.stepAssessmentStartYear());
                     tipPositionSalary = this.positiveOrNull(tip.storedPositionSalary());
                     tipGradeSalary = this.positiveOrNull(tip.storedGradeSalary());
                     tipPerformanceAllowance = this.positiveOrNull(tip.storedPerformanceAllowance());
                     tipSubsidyAllowance = this.positiveOrNull(tip.storedSubsidyAllowance());
                     tipTotal = this.positiveOrNull(tip.storedTotal());
                  }

                  com.dxsoft.rsgzgl.payroll.WageProjectionPreview projected = this.wageProjection(uid, applyPeriod);
                  if (this.emptyToNull(projected.level()) == null && this.emptyToNull(projected.stepOrSalaryLevel()) == null) {
                     lines.add(
                        "同等条件推算未得到级别/档次："
                           + (
                              projected.explanationLines() != null && !projected.explanationLines().isEmpty()
                                 ? projected.explanationLines().get(Math.min(1, projected.explanationLines().size() - 1))
                                 : "请检查转正年月、学历、任职与考核信息。"
                           )
                     );
                  } else {
                     boolean institutionHire = this.isInstitutionPosition(this.firstNonBlank(projected.positionCode(), positionCode));
                     if (!transferInPath) {
                        changeType = institutionHire ? "新进工资" : "见习工资";
                     }

                     positionCode = this.firstNonBlank(projected.positionCode(), positionCode);
                     positionName = this.firstNonBlank(projected.positionName(), positionName);
                     projectedLevel = this.valueOrEmpty(projected.level());
                     projectedStep = this.valueOrEmpty(projected.stepOrSalaryLevel());
                     levelStart = this.valueOrEmpty(projected.levelAssessmentStartYear());
                     stepStart = this.valueOrEmpty(projected.stepAssessmentStartYear());
                     String salaryStandard = this.firstNonBlank(this.payrollRepository.latestPositionSalaryStandardAtOrBefore(applyPeriod), applyPeriod);
                     if (!institutionHire && !transferInPath) {
                        executeLevel = projectedLevel;
                        int projectedStepValue = this.payrollRepository.intValue(projectedStep);
                        int probationStepValue = Math.max(1, projectedStepValue - 1);
                        executeStep = String.valueOf(probationStepValue);
                        String salarySource = this.baseSalarySource(positionCode, projectedLevel);
                        String gradeLookupStep = "POLICE_GRADE".equals(salarySource) ? this.policeGradeStep(executeStep, "0") : executeStep;
                        positionSalary = this.nullToZero(this.payrollRepository.positionSalary(positionCode, salaryStandard));
                        gradeSalary = this.nullToZero(
                           this.regularizedBaseSalary(candidate.organizationCode(), positionCode, projectedLevel, gradeLookupStep, salaryStandard)
                        );
                        lines.add(
                           "同等条件推算级别/档次 "
                              + this.emptyToDash(projectedLevel)
                              + "/"
                              + this.emptyToDash(projectedStep)
                              + "；见习期拟执行低一档 "
                              + this.emptyToDash(projectedLevel)
                              + "/"
                              + this.emptyToDash(executeStep)
                              + "。"
                        );
                     } else {
                        executeLevel = projectedLevel;
                        executeStep = projectedStep;
                        positionSalary = this.nullToZero(projected.positionSalary());
                        gradeSalary = this.nullToZero(projected.gradeSalary());
                        lines.add(
                           transferInPath
                              ? "同等条件推算并拟执行"
                                 + this.emptyToDash(changeType)
                                 + "：级别/档次 "
                                 + this.emptyToDash(projectedLevel)
                                 + "/"
                                 + this.emptyToDash(projectedStep)
                                 + "。"
                              : "推算并拟执行级别/档次（薪级） " + this.emptyToDash(projectedLevel) + "/" + this.emptyToDash(projectedStep) + "。"
                        );
                     }

                     calculatedTotal = this.nullToZero(positionSalary) + this.nullToZero(gradeSalary);
                     Integer[] executeAllowances = this.resolveNewPersonnelExecuteAllowances(
                        tip, candidate.organizationCode(), positionCode, applyPeriod, lines, null, null, calculatedTotal, changeType
                     );
                     performanceAllowance = executeAllowances[0];
                     subsidyAllowance = executeAllowances[1];
                     calculatedTotal = executeAllowances[2];
                     if (projected.explanationLines() != null) {
                        lines.addAll(projected.explanationLines().stream().limit(6L).toList());
                     }
                  }
               }
            } catch (RuntimeException var43) {
               lines.add("试算推算失败：" + (var43.getMessage() == null ? var43.getClass().getSimpleName() : var43.getMessage()));
            }
         } else {
            lines.add("缺少进入年月或职务，暂无法推算明细。");
         }
      } else {
         pathNote = "按进入方式办理" + this.emptyToDash(changeType) + "。";
         lines.add((String)pathNote);
         if ("见习工资".equals(changeType)) {
            lines.add("院校直招/无工作经历见习：一般按见习岗位标准确定见习工资。");
         }

         if ((tip = this.payrollRepository.findLatestHistory(uid).orElse(null)) != null) {
            tipLevel = this.valueOrEmpty(tip.gradeSalaryLevel());
            tipStep = this.valueOrEmpty(tip.positionSalaryGrade());
            if (this.emptyToNull(tipLevel) == null && this.emptyToNull(tipStep) == null) {
               tipLevelStart = "";
               tipStepStart = "";
               tipPositionSalary = null;
               tipGradeSalary = null;
               tipPerformanceAllowance = null;
               tipSubsidyAllowance = null;
               tipTotal = null;
            } else {
               tipLevelStart = this.valueOrEmpty(tip.levelAssessmentStartYear());
               tipStepStart = this.valueOrEmpty(tip.stepAssessmentStartYear());
               tipPositionSalary = this.positiveOrNull(tip.storedPositionSalary());
               tipGradeSalary = this.positiveOrNull(tip.storedGradeSalary());
               tipPerformanceAllowance = this.positiveOrNull(tip.storedPerformanceAllowance());
               tipSubsidyAllowance = this.positiveOrNull(tip.storedSubsidyAllowance());
               tipTotal = this.positiveOrNull(tip.storedTotal());
            }
         } else {
            tipLevel = "";
            tipStep = "";
            tipLevelStart = "";
            tipStepStart = "";
            tipTotal = null;
         }
      }

      if (Boolean.TRUE.equals(preview.rollbackEligible())
         && this.isTransferInSalaryChangeType(changeType)
         && this.emptyToNull(candidate.payrollHistoryId()) != null) {
         List<com.dxsoft.rsgzgl.payroll.TransferProjectionAuditStep> auditSteps = this.payrollRepository
            .findTransferProjectionAuditByTipId(candidate.payrollHistoryId());
         if (!auditSteps.isEmpty()) {
            lines.add("推算过程备查：");
            int stepNo = 1;

            for (com.dxsoft.rsgzgl.payroll.TransferProjectionAuditStep auditStep : auditSteps) {
               if (auditStep != null) {
                  String desc = this.emptyToNull(auditStep.description());
                  lines.add(
                     stepNo++
                        + ". "
                        + this.formatYearMonth(auditStep.changePeriod())
                        + " "
                        + this.emptyToDash(auditStep.changeType())
                        + " "
                        + this.positionDisplay(auditStep.positionCode(), auditStep.positionName())
                        + "，级别/档次 "
                        + this.emptyToDash(auditStep.gradeLevel())
                        + "/"
                        + this.emptyToDash(auditStep.gradeStep())
                        + "，起算年 "
                        + this.emptyToDash(auditStep.levelStartYear())
                        + "/"
                        + this.emptyToDash(auditStep.stepStartYear())
                        + (desc == null ? "" : "；" + desc)
                  );
               }
            }
         }
      }

      if (this.emptyToNull(preview.standardNote()) != null) {
         lines.add("列表说明：" + preview.standardNote());
      }

      boolean institutionPayroll;
      String performanceCaption = (institutionPayroll = this.isInstitutionPosition(positionCode)) ? "基础性绩效" : this.dfbt2CaptionForPosition(positionCode);
      String subsidyCaption = institutionPayroll ? null : this.sdbtCaptionForPosition(positionCode);
      return new com.dxsoft.rsgzgl.payroll.NewPersonnelSalaryDetail(
         candidate.uid(),
         candidate.payrollHistoryId(),
         candidate.organizationCode(),
         candidate.organizationName(),
         candidate.personCode(),
         candidate.name(),
         candidate.joinYearMonth(),
         candidate.joinType(),
         candidate.workStartYearMonth(),
         changeType,
         this.formatYearMonth(applyPeriod),
         (String)pathNote,
         positionCode,
         positionName,
         projectedLevel,
         projectedStep,
         executeLevel,
         executeStep,
         levelStart,
         stepStart,
         positionSalary,
         gradeSalary,
         performanceAllowance,
         institutionPayroll ? null : subsidyAllowance,
         calculatedTotal,
         tipLevel,
         tipStep,
         tipLevelStart,
         tipStepStart,
         tipPositionCode,
         tipPositionName,
         tipBaseCleared,
         tipPositionSalary,
         tipGradeSalary,
         tipPerformanceAllowance,
         institutionPayroll ? null : tipSubsidyAllowance,
         tipTotal,
         performanceCaption,
         subsidyCaption,
         !institutionPayroll,
         preview.standardNote(),
         preview.applyEligible(),
         preview.rollbackEligible(),
         List.copyOf(lines)
      );
   }

   private Integer[] resolveNewPersonnelExecuteAllowances(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip,
      String organizationCode,
      String positionCode,
      String applyPeriod,
      List<String> lines,
      Integer storedPerformance,
      Integer storedSubsidy,
      Integer storedTotal,
      String changeType
   ) {
      boolean institution = this.isInstitutionPosition(positionCode);
      boolean zeroWorkSubsidy = institution || this.shouldZeroCivilInternWorkSubsidy(tip, changeType);
      String allowanceStandard = this.resolveAllowanceStandardYearMonth(
         applyPeriod, organizationCode, positionCode, tip == null ? null : tip.allowanceStandardYearMonth()
      );
      int calculatedSubsidy;
      int calculatedPerformance;
      if (tip != null) {
         com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowances = this.allowanceCalculation(tip, positionCode, allowanceStandard);
         calculatedPerformance = this.nullToZero(allowances.performanceAllowance()).intValue();
         calculatedSubsidy = zeroWorkSubsidy ? 0 : this.nullToZero(allowances.subsidyAllowance());
      } else {
         calculatedPerformance = this.nullToZero(this.payrollRepository.performanceAllowance(organizationCode, positionCode, allowanceStandard)).intValue();
         calculatedSubsidy = zeroWorkSubsidy ? 0 : this.nullToZero(this.payrollRepository.subsidyAllowance(organizationCode, positionCode, allowanceStandard));
      }

      int basePerformance = this.nullToZero(storedPerformance);
      int baseSubsidy = this.nullToZero(storedSubsidy);
      int total = this.nullToZero(storedTotal);
      if (zeroWorkSubsidy && baseSubsidy != 0) {
         total -= baseSubsidy;
         baseSubsidy = 0;
         if (lines != null && !institution) {
            lines.add("见习期不发工作性津贴。");
         }
      }

      if (basePerformance == calculatedPerformance && baseSubsidy == calculatedSubsidy) {
         if (zeroWorkSubsidy && !institution && lines != null && lines.stream().noneMatch(line -> line != null && line.contains("见习期不发工作性津贴"))) {
            lines.add("见习期不发工作性津贴。");
         }
      } else {
         String caption = institution ? "基础性绩效" : this.dfbt2CaptionForPosition(positionCode);
         if (basePerformance == 0 && calculatedPerformance > 0) {
            lines.add("当前记录" + caption + "为 0（办理时未按津补贴标准写入）；按标准 " + this.emptyToDash(allowanceStandard) + " 应计 " + calculatedPerformance + "。还原后重新办理可写入。");
         } else if (basePerformance != calculatedPerformance) {
            lines.add(caption + "按标准 " + this.emptyToDash(allowanceStandard) + " 试算为 " + calculatedPerformance + "（记录值 " + basePerformance + "）。");
         }

         total = total - basePerformance - baseSubsidy + calculatedPerformance + calculatedSubsidy;
      }

      return new Integer[]{calculatedPerformance, calculatedSubsidy, total};
   }

   private boolean shouldZeroCivilInternWorkSubsidy(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String changeType) {
      if ("见习工资".equals(this.emptyToNull(changeType))) {
         return true;
      } else {
         return history != null && "见习工资".equals(this.emptyToNull(history.calculationType()))
            ? true
            : history != null && this.isWithinCivilInternPeriod(history);
      }
   }

   private Integer positiveOrNull(Integer value) {
      return value != null && value != 0 ? value : null;
   }

   private String newPersonnelSalaryAmountExplanation(
      String positionCode, Integer positionSalary, Integer gradeSalary, Integer performanceAllowance, Integer subsidyAllowance, Integer calculatedTotal
   ) {
      StringBuilder text = new StringBuilder().append("职务工资 ").append(this.nullToZero(positionSalary)).append("，级别/薪级工资 ").append(this.nullToZero(gradeSalary));
      if (this.isInstitutionPosition(positionCode)) {
         text.append("，基础性绩效 ").append(this.nullToZero(performanceAllowance));
      } else {
         text.append("，")
            .append(this.dfbt2CaptionForPosition(positionCode))
            .append(" ")
            .append(this.nullToZero(performanceAllowance))
            .append("，")
            .append(this.sdbtCaptionForPosition(positionCode))
            .append(" ")
            .append(this.nullToZero(subsidyAllowance));
      }

      return text.append("，合计 ").append(this.nullToZero(calculatedTotal)).append("。").toString();
   }

