   private com.dxsoft.rsgzgl.payroll.OtherPayrollChangeCalcResult calculateOtherPayrollChange(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip, com.dxsoft.rsgzgl.payroll.OtherPayrollChangeCalcRequest request
   ) {
      String year = request.calculationYear().trim();
      Object month = request.calculationMonth().trim();
      if (((String)month).length() == 1) {
         month = "0" + (String)month;
      } else if (((String)month).length() > 2) {
         month = ((String)month).substring(0, 2);
      }

      String period = year + (String)month;
      String changeType = request.changeType().trim();
      String positionCode = this.firstNonBlank(request.positionCode(), tip.positionCode());
      String positionName = this.firstNonBlank(request.positionName(), tip.positionName());
      String level = this.firstNonBlank(request.gradeSalaryLevel(), tip.gradeSalaryLevel());
      String step = this.firstNonBlank(request.positionSalaryGrade(), tip.positionSalaryGrade());
      Object salaryStandard = this.firstNonBlank(request.salaryStandardYearMonth(), tip.salaryStandardYearMonth());
      if (this.emptyToNull((String)salaryStandard) == null) {
         salaryStandard = period;
      }

      String allowanceStandard = this.firstNonBlank(
         request.allowanceStandardYearMonth(),
         this.resolveAllowanceStandardYearMonth(period, tip.organizationCode(), positionCode, tip.allowanceStandardYearMonth())
      );
      boolean institution = this.isInstitutionPosition(positionCode);
      String mappedPosition = this.salaryStandardPositionCode(tip.organizationCode(), positionCode, (String)salaryStandard);
      int positionSalary = this.nullToZero(this.payrollRepository.positionSalary(mappedPosition, (String)salaryStandard))
         + this.nullToZero(this.payrollRepository.positionGradeSalary(positionCode, step, "0", (String)salaryStandard));
      Integer gradeSalary = this.regularizedBaseSalary(tip.organizationCode(), positionCode, level, step, (String)salaryStandard);
      Integer technicalGradeSalary = this.payrollRepository.technicalGradeSalary(positionCode, (String)salaryStandard);
      com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowances = this.allowanceCalculation(tip, positionCode, allowanceStandard);
      int performanceAllowance = this.nullToZero(allowances.performanceAllowance()).intValue();
      int subsidyAllowance = institution ? 0 : this.nullToZero(allowances.subsidyAllowance());
      int retainedAllowance = this.nullToZero(allowances.retainedAllowance());
      int teachingAllowance = this.teachingAllowanceForOtherChange(tip, positionCode, year);
      Integer salaryIncrease = this.teachingIncreaseAfterWrite(tip, positionCode, positionSalary, gradeSalary, (String)salaryStandard);
      int teachingIncreaseDelta = this.teachingIncreaseDelta(tip, positionCode, positionSalary, gradeSalary, (String)salaryStandard);
      int totalAmount = this.nullToZero(tip.storedTotal())
         - this.nullToZero(tip.storedPositionSalary())
         + positionSalary
         - this.nullToZero(tip.storedGradeSalary())
         + this.nullToZero(gradeSalary)
         - this.nullToZero(tip.storedTechnicalGradeSalary())
         + this.nullToZero(technicalGradeSalary)
         - this.nullToZero(tip.storedPerformanceAllowance())
         + performanceAllowance
         - this.nullToZero(tip.storedSubsidyAllowance())
         + subsidyAllowance
         - this.nullToZero(tip.storedRetainedAllowance())
         + retainedAllowance
         - this.nullToZero(tip.storedTeachingAllowance())
         + teachingAllowance
         + teachingIncreaseDelta;
      String note = "职务/级别/津补贴等自动计算项已按所选结构与标准带出，不可手工改数。";
      return new com.dxsoft.rsgzgl.payroll.OtherPayrollChangeCalcResult(
         period,
         changeType,
         positionCode,
         positionName,
         level,
         step,
         (String)salaryStandard,
         allowanceStandard,
         positionSalary,
         this.nullToZero(gradeSalary),
         this.nullToZero(technicalGradeSalary),
         performanceAllowance,
         institution ? null : subsidyAllowance,
         retainedAllowance,
         teachingAllowance,
         salaryIncrease,
         totalAmount,
         institution ? "基础性绩效" : this.dfbt2CaptionForPosition(positionCode),
         institution ? null : this.sdbtCaptionForPosition(positionCode),
         !institution,
         note
      );
   }

   private int teachingAllowanceForOtherChange(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip, String positionCode, String calculationYear) {
      return this.teachingAllowanceForPeriod(tip, positionCode, calculationYear);
   }

   private void validateOtherPayrollChangeRequest(com.dxsoft.rsgzgl.payroll.OtherPayrollChangeCalcRequest request) {
      if (request == null) {
         throw new IllegalArgumentException("变动内容不能为空。");
      } else if (this.emptyToNull(request.calculationYear()) == null || this.emptyToNull(request.calculationMonth()) == null) {
         throw new IllegalArgumentException("变动年月不能为空。");
      } else if (this.emptyToNull(request.changeType()) == null) {
         throw new IllegalArgumentException("变动类别不能为空。");
      }
   }

   private boolean isAutomatedPayrollChangeType(String changeType) {
      if (this.emptyToNull(changeType) == null) {
         return false;
      } else {
         String trimmed = changeType.trim();
         return AUTOMATED_PAYROLL_CHANGE_EXACT_TYPES.contains(trimmed) ? true : AUTOMATED_PAYROLL_CHANGE_KEYWORDS.stream().anyMatch(trimmed::contains);
      }
   }

   private boolean isBlockedForOtherPayrollChange(String changeType) {
      if (this.emptyToNull(changeType) == null) {
         return false;
      } else {
         String trimmed = changeType.trim();
         return OTHER_PAYROLL_CHANGE_TYPE_OPTIONS.contains(trimmed) ? false : this.isAutomatedPayrollChangeType(trimmed);
      }
   }

