   private boolean isNormalPromotionProcessedInYear(int uid, int promotionYear) {
      if (this.payrollRepository.hasNormalPromotionInYear(uid, promotionYear)) {
         return true;
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository.findLatestHistory(uid).orElse(null);
         return this.isNormalPromotionProcessedInYear(latest, promotionYear);
      }
   }

   private boolean isNormalPromotionProcessedInYear(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, int promotionYear) {
      if (latest == null) {
         return false;
      } else {
         String period = latest.calculationYear() + latest.calculationMonth();
         return period.startsWith(String.valueOf(promotionYear)) && ("正常档次".equals(latest.calculationType()) || "正常薪级".equals(latest.calculationType()));
      }
   }

   private com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basicCalculation(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest
   ) {
      return this.basicCalculation(state, latest, state.salaryStandardYearMonth());
   }

   private String salaryStandardPositionCode(String organizationCode, String positionCode, String standardYearMonth) {
      if (positionCode != null && positionCode.startsWith("11")) {
         return positionCode;
      } else {
         return this.mapCompulsoryEducation10To11
               && positionCode != null
               && positionCode.startsWith("10")
               && standardYearMonth != null
               && standardYearMonth.compareTo("201807") >= 0
               && this.payrollRepository.isCompulsoryEducationOrganization(organizationCode)
            ? "11" + positionCode.substring(2)
            : positionCode;
      }
   }

   private com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basicCalculation(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, String lookupPeriod
   ) {
      String standardYearMonth = state.salaryStandardYearMonth();
      String positionCode = state.positionCode();
      String salarySource = this.resolvedBaseSalarySource(state);
      int probationSalary = this.internSalaryAmount(state, latest, lookupPeriod);
      Integer n;
      if (probationSalary > 0) {
         n = probationSalary;
      } else {
         switch (salarySource) {
            case "GRADE":
               n = this.payrollRepository
                  .civilServantGradeSalary(state.level(), state.stepOrSalaryLevel(), state.gradeStepDifferenceCount(), standardYearMonth);
               break;
            case "POLICE_GRADE":
               n = this.payrollRepository
                  .policeOfficerGradeSalary(state.level(), this.policeGradeStep(state.stepOrSalaryLevel(), state.gradeStepDifferenceCount()), standardYearMonth);
               break;
            default:
               n = null;
         }
      }

      String salaryStandardPositionCode = this.salaryStandardPositionCode(latest.organizationCode(), positionCode, standardYearMonth);
      Integer salaryLevelSalary = "SALARY_LEVEL".equals(salarySource)
         ? this.payrollRepository.salaryLevelSalary(state.stepOrSalaryLevel(), "0", standardYearMonth, salaryStandardPositionCode)
         : (
            "WORKER_GRADE".equals(salarySource)
               ? 0
               : this.payrollRepository
                  .salaryLevelSalary(latest.positionSalaryGrade(), latest.gradeSalaryStep(), standardYearMonth, salaryStandardPositionCode)
         );
      Integer technicalGradeSalary = this.payrollRepository.technicalGradeSalary(positionCode, standardYearMonth);
      int var10000;
      if (probationSalary > 0) {
         var10000 = 0;
      } else {
         switch (salarySource) {
            case "WORKER_GRADE":
            case "JUDICIAL_GRADE":
               var10000 = this.workerPositionSalary(positionCode, state.stepOrSalaryLevel(), standardYearMonth);
               break;
            default:
               var10000 = this.nullToZero(this.payrollRepository.positionSalary(this.payrollRepository.mapPositionSalaryCode(positionCode), standardYearMonth));
         }
      }

      int positionSalary = var10000;

      Integer selectedBaseSalary = switch (salarySource) {
         case "GRADE" -> n;
         case "POLICE_GRADE" -> n;
         case "JUDICIAL_GRADE" -> this.payrollRepository.positionGradeSalary(positionCode, state.stepOrSalaryLevel(), "0", standardYearMonth);
         case "WORKER_GRADE" -> 0;
         default -> salaryLevelSalary;
      };
      return new com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation(
         standardYearMonth,
         positionCode,
         this.payrollRepository.mapPositionSalaryCode(positionCode),
         latest.positionSalaryGrade(),
         state.level(),
         state.stepOrSalaryLevel(),
         positionSalary,
         n,
         salaryLevelSalary,
         technicalGradeSalary,
         salarySource,
         selectedBaseSalary,
         latest.storedPositionSalary(),
         latest.storedGradeSalary(),
         latest.storedTechnicalGradeSalary(),
         latest.storedTotal()
      );
   }

   private com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation additionalCalculation(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest
   ) {
      return new com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation(
         state.rankAllowanceStandardYearMonth(),
         state.rankName(),
         this.nullToZero(state.rankAllowance()),
         latest.floatingStep(),
         this.payrollRepository.floatingSalary(state.salaryStandardYearMonth(), state.positionCode(), latest.positionSalaryGrade(), latest.floatingStep()),
         this.selectedBonusBalance(latest),
         latest.postAllowanceStandardYearMonth(),
         latest.postAllowanceCategory(),
         latest.storedPostAllowance(),
         this.retainedSpecialPostAllowance(latest),
         latest.storedRankAllowance(),
         latest.storedFloatingSalary(),
         latest.storedBonusBalance(),
         latest.storedPostAllowance(),
         latest.storedRetainedSpecialPostAllowance()
      );
   }

   private com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basicCalculation(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      String standardYearMonth = history.salaryStandardYearMonth();
      String positionCode = history.positionCode();
      Integer gradeSalary = this.payrollRepository
         .civilServantGradeSalary(history.gradeSalaryLevel(), history.positionSalaryGrade(), history.gradeSalaryStep(), standardYearMonth);
      Integer salaryLevelSalary = this.payrollRepository
         .salaryLevelSalary(
            history.positionSalaryGrade(),
            history.gradeSalaryStep(),
            standardYearMonth,
            this.salaryStandardPositionCode(history.organizationCode(), positionCode, standardYearMonth)
         );
      Integer technicalGradeSalary = this.payrollRepository.technicalGradeSalary(positionCode, standardYearMonth);
      Integer policeGradeSalary = this.payrollRepository.policeOfficerGradeSalary(history.gradeSalaryLevel(), this.policeGradeStep(history), standardYearMonth);
      Integer positionSalary = this.payrollRepository
            .positionSalary(this.salaryStandardPositionCode(history.organizationCode(), positionCode, standardYearMonth), standardYearMonth)
         + this.payrollRepository.positionGradeSalary(positionCode, history.positionSalaryGrade(), history.gradeSalaryStep(), standardYearMonth);
      String baseSalarySource = this.baseSalarySource(positionCode, history.gradeSalaryLevel());
      if ("WORKER_GRADE".equals(baseSalarySource)) {
         salaryLevelSalary = 0;
      }
      Integer selectedBaseSalary = switch (baseSalarySource) {
         case "GRADE" -> gradeSalary;
         case "POLICE_GRADE" -> policeGradeSalary;
         case "JUDICIAL_GRADE" -> this.payrollRepository.positionGradeSalary(positionCode, history.positionSalaryGrade(), "0", standardYearMonth);
         case "WORKER_GRADE" -> 0;
         default -> salaryLevelSalary;
      };
      return new com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation(
         standardYearMonth,
         positionCode,
         this.payrollRepository.mapPositionSalaryCode(positionCode),
         history.positionSalaryGrade(),
         history.gradeSalaryLevel(),
         history.gradeSalaryStep(),
         positionSalary,
         gradeSalary,
         salaryLevelSalary,
         technicalGradeSalary,
         baseSalarySource,
         selectedBaseSalary,
         history.storedPositionSalary(),
         history.storedGradeSalary(),
         history.storedTechnicalGradeSalary(),
         history.storedTotal()
      );
   }

