   private List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> cachedCalculationFields() {
      List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> cache = this.calculationFieldsCache;
      if (cache == null) {
         this.calculationFieldsCache = cache = this.payrollRepository.findCalculationFields();
      }

      return cache;
   }

   private List<com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent> configuredSalaryItems(
      List<com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent> computed, Map<String, BigDecimal> preservedByField
   ) {
      LinkedHashMap<String, com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent> computedByField = new LinkedHashMap<>();

      for (com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent component : computed) {
         computedByField.put(component.fieldName(), component);
      }

      List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> fields = this.cachedCalculationFields();
      BigDecimal statTotal = BigDecimal.ZERO;

      for (com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata field : fields) {
         if (!this.isSalaryTotalField(field) && Boolean.TRUE.equals(field.counted())) {
            statTotal = statTotal.add(this.configuredFieldAmount(field, computedByField, preservedByField));
         }
      }

      ArrayList<com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent> items = new ArrayList<>();
      HashSet<String> rendered = new HashSet<>();

      for (com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata fieldx : fields) {
         String fieldName = fieldx.fieldName();
         if (this.isSalaryTotalField(fieldx)) {
            com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent existing = computedByField.get(fieldName);
            items.add(
               new com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent(fieldName, existing != null ? existing.caption() : fieldx.caption(), statTotal, "TOTAL")
            );
         } else {
            com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent component = computedByField.get(fieldName);
            items.add(
               component != null
                  ? component
                  : new com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent(
                     fieldName, fieldx.caption(), this.configuredFieldAmount(fieldx, computedByField, preservedByField), "PRESERVE"
                  )
            );
         }

         rendered.add(fieldName);
      }

      for (com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent component : computed) {
         if (!rendered.contains(component.fieldName())) {
            items.add(component);
         }
      }

      return items;
   }

   private boolean isSalaryTotalField(com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata field) {
      return field.caption() != null && field.caption().contains("合计");
   }

   private BigDecimal configuredFieldAmount(
      com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata field,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent> computedByField,
      Map<String, BigDecimal> preservedByField
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent component = computedByField.get(field.fieldName());
      return component != null ? this.nullToZero(component.amount()) : this.nullToZero(preservedByField.getOrDefault(field.fieldName(), BigDecimal.ZERO));
   }

   private com.dxsoft.rsgzgl.payroll.PayrollPreviewComponent preview(String fieldName, String caption, Integer amount, String source) {
      return this.preview(fieldName, caption, BigDecimal.valueOf((long)this.nullToZero(amount)), source);
   }

