   private com.dxsoft.rsgzgl.payroll.PayrollCalculationAudit calculationAudit(int uid, List<com.dxsoft.rsgzgl.payroll.PayrollFieldMetadata> calculationFields) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = this.payrollRepository
         .findLatestHistory(uid)
         .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      this.accessControlService.requireOrganization(history.organizationCode());
      Map<String, Object> historyValues = this.payrollRepository.findLatestHistoryValues(uid);
      List<com.dxsoft.rsgzgl.payroll.PayrollComponentValue> components = calculationFields.stream()
         .map(
            field -> new com.dxsoft.rsgzgl.payroll.PayrollComponentValue(
                  field.fieldName(),
                  field.caption(),
                  field.inputMode(),
                  field.allowance(),
                  this.payrollRepository.decimalValue(historyValues, field.fieldName())
               )
         )
         .toList();
      com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basicCalculation = this.basicCalculation(history);
      com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowanceCalculation = this.allowanceCalculation(history);
      com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation additionalCalculation = this.additionalCalculation(history);
      com.dxsoft.rsgzgl.payroll.PayrollTotalComparison total = this.totalComparison(
         history, components, basicCalculation, allowanceCalculation, additionalCalculation
      );
      BigDecimal difference = this.nullToZero(total.totalDifference());
      return new com.dxsoft.rsgzgl.payroll.PayrollCalculationAudit(
         uid,
         history.organizationCode(),
         history.personCode(),
         history.name(),
         history.calculationYear() + history.calculationMonth(),
         history.storedTotal(),
         total.recalculatedKnownTotal(),
         difference,
         difference.compareTo(BigDecimal.ZERO) == 0,
         total.componentDifferences()
      );
   }

