   private com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit projectionPersonAudit(
      int uid, boolean includeStepDetails, com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext batchContext
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = batchContext != null ? batchContext.latestByUid().get(uid) : null;
      if (latest == null) {
         latest = this.payrollRepository
            .findLatestHistory(uid)
            .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      }

      this.accessControlService.requireOrganization(latest.organizationCode());
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain = batchContext != null
         ? batchContext.historyChain(latest)
         : this.payrollRepository.findHistoryChain(latest.organizationCode(), latest.personCode());
      List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> historyAudits = this.auditHistoryChainWithProjection(
         uid, latest, historyChain, includeStepDetails, batchContext
      );
      return this.buildProjectionPersonAudit(uid, latest, historyAudits, includeStepDetails);
   }

   private List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> auditHistoryChainWithProjection(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain,
      boolean includeStepDetails
   ) {
      return this.auditHistoryChainWithProjection(uid, latest, historyChain, includeStepDetails, null);
   }

   private List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> auditHistoryChainWithProjection(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain,
      boolean includeStepDetails,
      com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext batchContext
   ) {
      if (historyChain != null && !historyChain.isEmpty()) {
         String maxPeriod = historyChain.stream()
            .map(this::historyCalculationPeriod)
            .filter(period -> period != null && !period.isBlank())
            .max(Comparator.naturalOrder())
            .orElseGet(() -> this.historyCalculationPeriod(latest));
         com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext auditContext = this.createProjectionAuditContext(
            uid, latest, historyChain, maxPeriod, batchContext
         );
         boolean lightweightStepCapture = !includeStepDetails;
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionRun sharedProjection = null;

         try {
            sharedProjection = this.runWageProjection(uid, maxPeriod, null, latest, true, auditContext, lightweightStepCapture);
         } catch (RuntimeException var13) {
            log.debug("Shared projection failed for uid {}, falling back per record: {}", uid, var13.getMessage());
         }

         ArrayList<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> audits = new ArrayList<>(historyChain.size());

         for (com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record : historyChain) {
            if (this.canUseSharedProjectionForRecord(sharedProjection, record)) {
               audits.add(this.buildHistoryProjectionAudit(record, latest, sharedProjection, includeStepDetails, auditContext));
            } else {
               audits.add(this.auditHistoryWithProjection(uid, record, latest, includeStepDetails, auditContext, lightweightStepCapture));
            }
         }

         return audits;
      } else {
         return List.of();
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext buildProjectionAuditBatchContext(List<Integer> uids) {
      if (uids != null && !uids.isEmpty()) {
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> latestByUid = this.payrollRepository.findLatestHistoriesByUids(uids);
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> keys = latestByUid.values()
            .stream()
            .map(history -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(history.organizationCode(), history.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot>> chainsByOrgPerson = keys.isEmpty()
            ? Map.of()
            : this.payrollRepository.findHistoryChainsByOrgPersons(keys);
         List<String> historyIds = chainsByOrgPerson.values()
            .stream()
            .flatMap(Collection::stream)
            .map(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot::id)
            .map(this::emptyToNull)
            .filter(Objects::nonNull)
            .distinct()
            .toList();
         int endYear = Math.max(2006, LocalDate.now().getYear());
         Map<Integer, List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear>> assessmentsByUid = this.payrollRepository
            .findAssessmentYearsByUids(uids, 1993, endYear);
         Map<String, Map<String, Object>> historyValuesById = historyIds.isEmpty() ? Map.of() : this.payrollRepository.findHistoryValuesByIds(historyIds);
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext(latestByUid, chainsByOrgPerson, assessmentsByUid, historyValuesById);
      } else {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext(Map.of(), Map.of(), Map.of(), Map.of());
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext createProjectionAuditContext(
      int uid, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain, String maxPeriod
   ) {
      return this.createProjectionAuditContext(uid, latest, historyChain, maxPeriod, null);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext createProjectionAuditContext(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> historyChain,
      String maxPeriod,
      com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditBatchContext batchContext
   ) {
      if (batchContext != null) {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext(
            uid,
            latest,
            new com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache(batchContext.assessmentsByUid()),
            batchContext.historyValuesById()
         );
      } else {
         int endYear = Math.max(2006, this.yearOf(maxPeriod));
         com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache = new com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache(
            this.payrollRepository.findAssessmentYearsByUids(List.of(uid), 1993, endYear)
         );
         List<String> historyIds = historyChain.stream()
            .map(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot::id)
            .map(this::emptyToNull)
            .filter(Objects::nonNull)
            .distinct()
            .toList();
         Map<String, Map<String, Object>> historyValuesById = this.payrollRepository.findHistoryValuesByIds(historyIds);
         return new com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext(uid, latest, assessmentCache, historyValuesById);
      }
   }

