   private void appendMissingAssessmentPrompt(
      List<String> lines,
      int uid,
      String organizationCode,
      String personCode,
      int startYear,
      int endYear,
      Set<Integer> promptedYears,
      com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext auditContext
   ) {
      List<Integer> missingYears = this.missingAssessmentYears(uid, organizationCode, personCode, startYear, endYear, auditContext)
         .stream()
         .filter(promptedYears::add)
         .toList();
      if (!missingYears.isEmpty()) {
         lines.add("缺少 " + missingYears.stream().map(String::valueOf).collect(Collectors.joining("、")) + " 年度考核结果，请先补录后再推算正常晋升。");
      }
   }

   private List<Integer> missingAssessmentYears(
      int uid,
      String organizationCode,
      String personCode,
      int startYear,
      int endYear,
      com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext auditContext
   ) {
      if (startYear <= 0 || endYear < startYear) {
         return List.of();
      } else {
         return auditContext != null && auditContext.assessmentCache() != null
            ? auditContext.assessmentCache().missingYears(uid, startYear, endYear)
            : this.missingAssessmentYears(organizationCode, personCode, startYear, endYear);
      }
   }

   private boolean canUseSharedProjectionForRecord(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionRun sharedProjection, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record
   ) {
      if (sharedProjection != null && sharedProjection.eligible()) {
         String period = this.historyCalculationPeriod(record);
         return this.findAuditStepDetailForRecord(sharedProjection.stepDetails(), record, period).isPresent()
            || this.findProjectionStepAtPeriod(sharedProjection.stepDetails(), period).isPresent();
      } else {
         return false;
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit buildProjectionPersonAudit(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> historyAudits,
      boolean includeStepDetails
   ) {
      String latestPeriod = this.historyCalculationPeriod(latest);
      com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit latestAudit = historyAudits.stream()
         .filter(audit -> latest.id().equals(audit.historyId()))
         .findFirst()
         .orElseGet(() -> this.auditHistoryWithProjection(uid, latest, latest, includeStepDetails));
      List<com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit> historyMismatches = historyAudits.stream()
         .filter(audit -> !Boolean.TRUE.equals(audit.matched()))
         .map(audit -> (com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit)(includeStepDetails ? audit : this.withoutStepDetails(audit)))
         .toList();
      com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit latestForSummary = includeStepDetails ? latestAudit : this.withoutStepDetails(latestAudit);
      return new com.dxsoft.rsgzgl.payroll.PayrollProjectionPersonAudit(
         uid,
         latest.organizationCode(),
         latest.personCode(),
         latest.name(),
         latestPeriod,
         latestForSummary.projectionEligible(),
         latestForSummary.note(),
         latestForSummary.storedTotal(),
         latestForSummary.projectedTotal(),
         latestForSummary.totalDifference(),
         latestForSummary.matched(),
         historyAudits.size(),
         historyMismatches.size(),
         historyMismatches
      );
   }

   private com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit withoutStepDetails(com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit audit) {
      if (audit == null) {
         return null;
      } else {
         return audit.stepDetails() != null && !audit.stepDetails().isEmpty()
            ? new com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit(
               audit.historyId(),
               audit.calculationPeriod(),
               audit.changeType(),
               audit.projectionEligible(),
               audit.note(),
               audit.matched(),
               audit.storedTotal(),
               audit.projectedTotal(),
               audit.totalDifference(),
               audit.structureMismatches(),
               audit.componentDifferences(),
               List.of()
            )
            : audit;
      }
   }

