   private com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit buildHistoryProjectionAudit(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionRun projection,
      boolean includeStepDetails
   ) {
      return this.buildHistoryProjectionAudit(record, latest, projection, includeStepDetails, null);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit buildHistoryProjectionAudit(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionRun projection,
      boolean includeStepDetails,
      com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext auditContext
   ) {
      String period = this.historyCalculationPeriod(record);
      List<com.dxsoft.rsgzgl.payroll.WageProjectionStepDetail> stepDetails = includeStepDetails && projection.stepDetails() != null
         ? projection.stepDetails()
         : List.of();
      if (!projection.eligible()) {
         String note = projection.start() != null && !projection.start().eligible()
            ? projection.start().note()
            : projection.lines().stream().filter(line -> line != null && !line.isBlank()).reduce((first, second) -> second).orElse("当前年月无法完成工资推算。");
         return new com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit(
            record.id(), period, record.calculationType(), false, note, false, record.storedTotal(), null, null, List.of(), List.of(), stepDetails
         );
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState amountState = this.bindAmountStateForHistoryAudit(projection, record, latest, period);
         Map<String, Object> historyValues = this.resolveHistoryValuesForAudit(record, auditContext);
         if (historyValues != null && !historyValues.isEmpty()) {
            List<String> structureMismatches = this.projectionStructureMismatches(amountState, record);
            BigDecimal projectedTotal = this.resolveProjectedTotalForHistoryAudit(projection, record, period, amountState, latest);
            BigDecimal totalDifference = projectedTotal.subtract(BigDecimal.valueOf((long)this.nullToZero(record.storedTotal())));
            boolean matched = totalDifference.compareTo(BigDecimal.ZERO) == 0 && structureMismatches.isEmpty();
            if (!includeStepDetails) {
               return new com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit(
                  record.id(),
                  period,
                  record.calculationType(),
                  true,
                  "",
                  matched,
                  record.storedTotal(),
                  projectedTotal,
                  totalDifference,
                  structureMismatches,
                  List.of(),
                  stepDetails
               );
            } else {
               List<com.dxsoft.rsgzgl.payroll.PayrollComponentValue> components = this.cachedCalculationFields()
                  .stream()
                  .map(
                     field -> new com.dxsoft.rsgzgl.payroll.PayrollComponentValue(
                           field.fieldName(),
                           field.caption(),
                           field.inputMode(),
                           field.allowance(),
                           this.payrollRepository.decimalValue(historyValues, field.fieldName())
                        )
                  )
                  .toList();
               com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basicCalculation = this.basicCalculation(amountState, latest, period);
               com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowanceCalculation = this.allowanceCalculation(amountState, latest);
               com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation additionalCalculation = this.additionalCalculation(amountState, latest);
               com.dxsoft.rsgzgl.payroll.PayrollTotalComparison total = this.totalComparison(
                  record, latest, components, basicCalculation, allowanceCalculation, additionalCalculation, period
               );
               List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> componentDifferences = total.componentDifferences()
                  .stream()
                  .filter(component -> component.difference().compareTo(BigDecimal.ZERO) != 0)
                  .toList();
               return new com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit(
                  record.id(),
                  period,
                  record.calculationType(),
                  true,
                  "",
                  matched,
                  record.storedTotal(),
                  projectedTotal,
                  totalDifference,
                  structureMismatches,
                  componentDifferences,
                  stepDetails
               );
            }
         } else {
            return new com.dxsoft.rsgzgl.payroll.PayrollHistoryProjectionAudit(
               record.id(),
               period,
               record.calculationType(),
               true,
               "调资记录数据无法加载（id=" + record.id() + "）",
               false,
               record.storedTotal(),
               null,
               null,
               List.of(),
               List.of(),
               stepDetails
            );
         }
      }
   }

   private Map<String, Object> resolveHistoryValuesForAudit(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record, com.dxsoft.rsgzgl.payroll.PayrollService.ProjectionAuditContext auditContext
   ) {
      String historyId = this.emptyToNull(record.id());
      if (historyId == null) {
         return Map.of();
      } else {
         if (auditContext != null && auditContext.historyValuesById() != null) {
            Map<String, Object> cached = auditContext.historyValuesById().get(historyId);
            if (cached != null && !cached.isEmpty()) {
               return cached;
            }
         }

         return this.payrollRepository
            .findHistoryValuesById(record.id(), record.organizationCode(), record.personCode(), record.calculationYear(), record.calculationMonth())
            .orElse(Map.of());
      }
   }

   private BigDecimal resolveProjectedTotalForHistoryAudit(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionRun projection,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record,
      String period,
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState amountState,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest
   ) {
      Optional<com.dxsoft.rsgzgl.payroll.WageProjectionStepDetail> auditStep = this.findAuditStepDetailForRecord(projection.stepDetails(), record, period);
      if (auditStep.isPresent()) {
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState stepState = this.amountStateFromAuditStep(projection.state(), auditStep.get(), latest);
         return this.projectionStepTotal(this.projectionStepComponents(latest, stepState, period));
      } else {
         return this.projectionStepTotal(this.projectionStepComponents(latest, amountState, period));
      }
   }

   private List<String> projectionStructureMismatches(
      com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record
   ) {
      ArrayList<String> mismatches = new ArrayList<>();
      this.addStructureMismatch(mismatches, "岗位编码", state.positionCode(), record.positionCode());
      this.addStructureMismatch(mismatches, "岗位名称", state.positionName(), record.positionName());
      String baseSalarySource = this.resolvedBaseSalarySource(state);
      if (!"GRADE".equals(baseSalarySource) && !"POLICE_GRADE".equals(baseSalarySource)) {
         this.addStructureMismatch(mismatches, "薪级", state.stepOrSalaryLevel(), record.positionSalaryGrade());
         this.addStructureMismatch(mismatches, "薪级考核起年", state.stepStartYear(), record.stepAssessmentStartYear());
      } else {
         this.addStructureMismatch(mismatches, "级别/薪级", state.level(), record.gradeSalaryLevel());
         this.addStructureMismatch(mismatches, "档次", state.stepOrSalaryLevel(), record.positionSalaryGrade());
         this.addStructureMismatch(mismatches, "级差", state.gradeStepDifferenceCount(), record.gradeSalaryStep());
         this.addStructureMismatch(mismatches, "级别考核起年", state.levelStartYear(), record.levelAssessmentStartYear());
         this.addStructureMismatch(mismatches, "档次考核起年", state.stepStartYear(), record.stepAssessmentStartYear());
      }

      return mismatches;
   }

   private void addStructureMismatch(List<String> mismatches, String label, String projected, String stored) {
      if (!this.structureValuesEqual(label, projected, stored)) {
         mismatches.add(label + "：推算=" + this.displayText(projected) + "，调资=" + this.displayText(stored));
      }
   }

   private boolean structureValuesEqual(String label, String projected, String stored) {
      return "级差".equals(label)
         ? this.payrollRepository.intValue(projected) == this.payrollRepository.intValue(stored)
         : this.normalizedEquals(projected, stored);
   }

   private String displayText(String value) {
      return value != null && !value.isBlank() ? value.trim() : "-";
   }

   private String historyCalculationPeriod(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      return this.projectionPeriod(history.calculationYear() + history.calculationMonth());
   }

   private String baseSalarySource(String positionCode) {
      return this.baseSalarySource(positionCode, null);
   }

   private String baseSalarySource(String positionCode, String gradeLevel) {
      if (positionCode != null && positionCode.length() >= 2) {
         String var3 = positionCode.substring(0, 2);

         return switch (var3) {
            case "01", "02", "23", "24", "25", "26", "27", "28" -> "GRADE";
            case "03" -> "JUDICIAL_GRADE";
            case "04", "21", "22" -> "POLICE_GRADE";
            case "05", "06" -> "WORKER_GRADE";
            default -> "SALARY_LEVEL";
         };
      } else {
         return "SALARY_LEVEL";
      }
   }

   private String policeGradeStep(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      int combined = this.payrollRepository.intValue(history.positionSalaryGrade()) + this.payrollRepository.intValue(history.gradeSalaryStep());
      if (combined > 0) {
         return String.valueOf(combined);
      } else {
         return this.emptyToNull(history.gradeSalaryStep()) != null ? history.gradeSalaryStep() : history.positionSalaryGrade();
      }
   }

   private String policeGradeStep(String positionSalaryGrade, String gradeSalaryStep) {
      int combined = this.payrollRepository.intValue(positionSalaryGrade) + this.payrollRepository.intValue(gradeSalaryStep);
      return combined > 0 ? String.valueOf(combined) : "0";
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.RankAllowanceState initialRankAllowanceState(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, String startPeriod
   ) {
      com.dxsoft.rsgzgl.payroll.RankAllowanceChange rank = this.payrollRepository
         .findRankAllowanceAtOrBefore(latest.organizationCode(), latest.personCode(), startPeriod)
         .orElse(new com.dxsoft.rsgzgl.payroll.RankAllowanceChange(latest.rankName(), "", ""));
      String standardYearMonth = this.payrollRepository.latestRankAllowanceStandardAtOrBefore(startPeriod);
      if (this.emptyToNull(standardYearMonth) == null) {
         standardYearMonth = latest.rankAllowanceStandardYearMonth();
      }

      String category = this.rankAllowanceCategory(rank.rankName());
      String standardLb = this.payrollRepository.resolveRankAllowanceStandardLb(rank.rankName(), rank.category());
      int amount = this.payrollRepository.rankAllowanceByRank(standardYearMonth, rank.rankName(), standardLb);
      if (amount == 0
         && this.normalizedEquals(rank.rankName(), latest.rankName())
         && this.normalizedEquals(standardYearMonth, latest.rankAllowanceStandardYearMonth())) {
         amount = this.nullToZero(latest.storedRankAllowance());
      }

      return new com.dxsoft.rsgzgl.payroll.PayrollService.RankAllowanceState(rank.rankName(), standardYearMonth, amount, category);
   }

   private String rankAllowanceCategory(String rankName) {
      String normalized = rankName == null ? "" : rankName.trim();
      if (normalized.contains("警")) {
         return "警";
      } else if (normalized.contains("法")) {
         return "法";
      } else if (normalized.contains("检")) {
         return "检";
      } else {
         return normalized.contains("监") ? "监" : "";
      }
   }

   private String rankAllowanceTypeName(String rankName) {
      String var2 = this.rankAllowanceCategory(rankName);

      return switch (var2) {
         case "警" -> "警衔";
         case "法" -> "审判";
         case "检" -> "检察";
         case "监" -> "监察";
         default -> "等级";
      };
   }

   private String rankAllowanceTitle(String rankName) {
      return this.rankAllowanceTypeName(rankName) + "津贴";
   }

   private String rankAllowanceChangeTitle(String rankName) {
      return this.rankAllowanceTypeName(rankName) + "变化";
   }

   private String rankAllowanceStandardTitle(String rankName) {
      return "调整" + this.rankAllowanceTitle(rankName);
   }

   private PageResponse<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion> rankAllowanceChangePromotions(
      String organizationCode, String keyword, String laterPeriodMode, PageRequest pageRequest, String category, String changeTypePrefix
   ) {
      OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
      String cacheKey = this.rankAllowanceChangeListCacheKey(scope, organizationCode, keyword, category, laterPeriodMode);
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion> allPreviews = this.cachedRankAllowanceChangeList(cacheKey);
      if (allPreviews == null) {
         allPreviews = this.computeRankAllowanceChangePromotions(scope, organizationCode, keyword, category, changeTypePrefix, laterPeriodMode);
         this.rankAllowanceChangeListCache
            .put(cacheKey, new com.dxsoft.rsgzgl.payroll.PayrollService.CachedRankAllowanceChangeList(System.currentTimeMillis(), List.copyOf(allPreviews)));
      }

      int fromIndex = pageRequest.offset();
      if (fromIndex >= allPreviews.size()) {
         return PageResponse.of(List.of(), pageRequest, (long)allPreviews.size());
      } else {
         int toIndex = Math.min(fromIndex + pageRequest.size(), allPreviews.size());
         return PageResponse.of(allPreviews.subList(fromIndex, toIndex), pageRequest, (long)allPreviews.size());
      }
   }

   private List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion> computeRankAllowanceChangePromotions(
      OrganizationScope scope, String organizationCode, String keyword, String category, String changeTypePrefix, String laterPeriodMode
   ) {
      long startedAt = System.nanoTime();
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext> contexts = this.payrollRepository
         .findRankAllowanceChangePromotionContexts(scope, this.emptyToNull(organizationCode), keyword, category);
      long afterContexts = System.nanoTime();
      if (contexts.isEmpty()) {
         return List.of();
      } else {
         List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext> processedContexts = new ArrayList<>();
         List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext> pendingContexts = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context : contexts) {
            if (this.isRankAllowanceChangeProcessed(context.calculationType(), changeTypePrefix)) {
               processedContexts.add(context);
            } else {
               pendingContexts.add(context);
            }
         }

         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessors = processedContexts.isEmpty()
            ? Map.of()
            : this.payrollRepository
               .findPredecessorHistoriesByCurrentIds(
                  processedContexts.stream().map(com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext::payrollHistoryId).toList()
               );
         long afterPredecessors = System.nanoTime();
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> orgPersonKeys = pendingContexts.stream()
            .map(contextx -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(contextx.organizationCode(), contextx.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange>> rankChangesByPerson = orgPersonKeys.isEmpty()
            ? Map.of()
            : this.payrollRepository.findRankAllowanceChangesByOrgPersons(orgPersonKeys, category);
         long afterRankChanges = System.nanoTime();
         LinkedHashSet<String> standardPeriods = new LinkedHashSet<>();

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext contextx : pendingContexts) {
            this.collectRankAllowanceStandardPeriods(contextx, category, standardPeriods);
         }

         Map<String, Integer> rankAllowanceAmounts = standardPeriods.isEmpty()
            ? Map.of()
            : this.payrollRepository.findRankAllowanceAmountsByPeriods(standardPeriods);
         long afterAmounts = System.nanoTime();
         ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion> previews = new ArrayList<>(contexts.size());

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext contextx : processedContexts) {
            com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview = this.previewProcessedRankAllowanceChangePromotion(contextx, predecessors);
            if (preview != null) {
               previews.add(preview);
            }
         }

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext contextxx : pendingContexts) {
            String personKey = contextxx.organizationCode() + "|" + contextxx.personCode();
            List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChanges = rankChangesByPerson.getOrDefault(personKey, List.of());
            com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview = this.previewPendingRankAllowanceChangePromotion(
               contextxx, category, rankChanges, rankAllowanceAmounts, laterPeriodMode
            );
            if (preview != null) {
               previews.add(preview);
            }
         }

         previews.sort(
            Comparator.<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion, String>comparing(previewx -> Objects.toString(previewx.organizationCode(), ""))
               .thenComparing(previewx -> Objects.toString(previewx.personCode(), ""))
         );
         log.debug(
            "rank-allowance-change list cold: contexts={} visible={} ctxSql={}ms pred={}ms jx={}ms amt={}ms total={}ms",
            new Object[]{
               contexts.size(),
               previews.size(),
               (afterContexts - startedAt) / 1000000L,
               (afterPredecessors - afterContexts) / 1000000L,
               (afterRankChanges - afterPredecessors) / 1000000L,
               (afterAmounts - afterRankChanges) / 1000000L,
               (System.nanoTime() - startedAt) / 1000000L
            }
         );
         return previews;
      }
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion previewProcessedRankAllowanceChangePromotion(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context, Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessors
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = predecessors.get(context.payrollHistoryId());
      String storedRankName = before == null ? "" : this.emptyToNull(before.rankName());
      String targetRankName = this.emptyToNull(context.rankName());
      Integer storedRankAllowance = before == null ? 0 : before.storedRankAllowance();
      Integer calculatedRankAllowance = context.storedRankAllowance();
      int difference = this.nullToZero(calculatedRankAllowance) - this.nullToZero(storedRankAllowance);
      String organizationName = this.emptyToNull(context.organizationName()) == null ? context.organizationCode() : context.organizationName();
      return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion(
         context.payrollHistoryId(),
         context.organizationCode(),
         organizationName,
         context.personCode(),
         context.name(),
         context.calculationPeriod(),
         context.positionCode(),
         context.positionName(),
         this.emptyToDash(storedRankName),
         this.emptyToDash(targetRankName),
         this.emptyToNull(context.positionStartYearMonth()),
         storedRankAllowance,
         calculatedRankAllowance,
         difference,
         true,
         false,
         true,
         null,
         false,
         null
      );
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion previewPendingRankAllowanceChangePromotion(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context,
      String category,
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChanges,
      Map<String, Integer> rankAllowanceAmounts,
      String laterPeriodMode
   ) {
      String calculationPeriod = context.calculationPeriod();
      Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChangeOptional = this.findPendingRankAllowanceChangeFromBatch(
         rankChanges, context, category, calculationPeriod
      );
      if (rankChangeOptional.isEmpty()) {
         return null;
      } else {
         com.dxsoft.rsgzgl.payroll.RankAllowanceChange rankChange = rankChangeOptional.get();
         String targetRankName = this.emptyToNull(rankChange.rankName());
         if (targetRankName == null) {
            return null;
         } else {
            String storedRankName = this.storedRankNameForCategory(context.rankName(), category);
            int storedRankAllowance = this.nullToZero(context.storedRankAllowance());
            int calculatedRankAllowance = this.calculatedRankAllowanceForChange(category, context, targetRankName, rankAllowanceAmounts);
            int difference = calculatedRankAllowance - storedRankAllowance;
            boolean rankChanged = !this.normalizedEquals(storedRankName, targetRankName);
            if (!rankChanged && difference == 0) {
               return null;
            } else {
               String rankChangeYearMonth = this.emptyToNull(rankChange.startYearMonth());
               String trialPeriod = rankChangeYearMonth != null && !rankChangeYearMonth.isBlank()
                  ? this.nextMonth(this.normalizeYearMonth(rankChangeYearMonth))
                  : this.nextMonth(calculationPeriod);
               boolean positionEligible = this.payrollRepository.isRankAllowanceEligiblePosition(context.positionCode());
               boolean allowanceChanged = calculatedRankAllowance > 0 || difference != 0;
               boolean eligible = rankChanged || allowanceChanged;
               boolean applyEligible = eligible && allowanceChanged && positionEligible;
               if (!eligible) {
                  return null;
               } else {
                  String organizationName = this.emptyToNull(context.organizationName()) == null ? context.organizationCode() : context.organizationName();
                  com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview = new com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion(
                     context.payrollHistoryId(),
                     context.organizationCode(),
                     organizationName,
                     context.personCode(),
                     context.name(),
                     trialPeriod,
                     context.positionCode(),
                     context.positionName(),
                     this.emptyToDash(storedRankName),
                     targetRankName,
                     rankChangeYearMonth,
                     storedRankAllowance,
                     calculatedRankAllowance,
                     difference,
                     eligible,
                     applyEligible,
                     false,
                     null,
                     false,
                     null
                  );
                  return !this.isRankAllowanceLaterPeriodCase(context, trialPeriod, category, storedRankName, targetRankName)
                     ? preview
                     : this.enrichRankAllowanceLaterPeriodPreview(
                        preview, context, category, trialPeriod, targetRankName, laterPeriodMode, rankAllowanceAmounts
                     );
               }
            }
         }
      }
   }

   private String rankAllowanceChangeModuleLabel(String category) {
      String var2 = this.emptyToNull(category);

      return switch (var2) {
         case "jc" -> "检察等级变化晋升";
         case "sp" -> "法官等级变化晋升";
         case "mt" -> "监察等级变化晋升";
         default -> "警衔变化晋升";
      };
   }

   private Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> findPendingRankAllowanceChangeFromBatch(
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChanges,
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context,
      String category,
      String calculationPeriod
   ) {
      String storedRankName = this.storedRankNameForCategory(context.rankName(), category);
      String executingRankStart = this.executingRankStartYearMonthFromBatch(rankChanges, storedRankName, calculationPeriod);
      String normalizedAfter = executingRankStart == null ? "" : executingRankStart.replace(".", "").trim();
      return rankChanges.stream().filter(change -> {
         String period = change.startYearMonth() == null ? "" : change.startYearMonth().replace(".", "").trim();
         return period.compareTo(normalizedAfter) > 0;
      }).findFirst();
   }

   private String executingRankStartYearMonthFromBatch(
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChanges, String storedRankName, String calculationPeriod
   ) {
      if (this.emptyToNull(storedRankName) != null) {
         Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> executingRank = rankChanges.stream()
            .filter(change -> this.normalizedEquals(change.rankName(), storedRankName))
            .findFirst();
         if (executingRank.isPresent()) {
            return this.emptyToNull(executingRank.get().startYearMonth());
         }

         String normalizedPeriod = calculationPeriod == null ? "" : calculationPeriod.replace(".", "");
         Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankAtPeriod = rankChanges.stream().filter(change -> {
            String period = change.startYearMonth() == null ? "" : change.startYearMonth().replace(".", "");
            return !period.isEmpty() && period.compareTo(normalizedPeriod) <= 0;
         }).filter(change -> this.normalizedEquals(change.rankName(), storedRankName)).findFirst();
         if (rankAtPeriod.isPresent()) {
            return this.emptyToNull(rankAtPeriod.get().startYearMonth());
         }
      }

      return "";
   }

   private void collectRankAllowanceStandardPeriods(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context, String category, Set<String> standardPeriods
   ) {
      if (this.emptyToNull(context.policeStandardYearMonth()) != null) {
         standardPeriods.add(context.policeStandardYearMonth());
      }

      if (this.emptyToNull(context.prosecutionStandardYearMonth()) != null) {
         standardPeriods.add(context.prosecutionStandardYearMonth());
      }

      if (this.emptyToNull(context.judicialStandardYearMonth()) != null) {
         standardPeriods.add(context.judicialStandardYearMonth());
      }
   }

   private int calculatedRankAllowanceForChange(
      String category, com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context, String rankName, Map<String, Integer> rankAllowanceAmounts
   ) {
      if (!this.payrollRepository.isRankAllowanceEligiblePosition(context.positionCode())) {
         return 0;
      } else {
         String policeStandard = context.policeStandardYearMonth();
         String prosecutionStandard = context.prosecutionStandardYearMonth();
         String judicialStandard = context.judicialStandardYearMonth();
         String normalizedRank = rankName == null ? "" : rankName.trim();

         return switch (category) {
            case "jx" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isPoliceRankName(normalizedRank) && this.emptyToNull(policeStandard) != null
            ? this.payrollRepository.rankAllowanceFromAmounts(rankAllowanceAmounts, policeStandard, normalizedRank, "jx")
            : 0;
            case "jc" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isProsecutionRankName(normalizedRank) && this.emptyToNull(prosecutionStandard) != null
            ? this.payrollRepository.rankAllowanceFromAmounts(rankAllowanceAmounts, prosecutionStandard, normalizedRank, "jc")
            : 0;
            case "sp" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isJudicialRankName(normalizedRank) && this.emptyToNull(judicialStandard) != null
            ? this.payrollRepository.rankAllowanceFromAmounts(rankAllowanceAmounts, judicialStandard, normalizedRank, "sp")
            : 0;
            case "mt" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isSupervisionRankName(normalizedRank) && this.emptyToNull(policeStandard) != null
            ? this.payrollRepository.rankAllowanceFromAmounts(rankAllowanceAmounts, policeStandard, normalizedRank, "mt")
            : 0;
            default -> this.payrollRepository
            .compositeRankAllowance(policeStandard, prosecutionStandard, judicialStandard, normalizedRank, context.positionCode());
         };
      }
   }

   private boolean isRankAllowanceLaterPeriodCase(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context,
      String executionPeriod,
      String category,
      String storedRankName,
      String targetRankName
   ) {
      if (context != null && this.emptyToNull(executionPeriod) != null) {
         String execution = executionPeriod.replace(".", "");
         String tipPeriod = context.calculationPeriod();
         if (tipPeriod.length() < 6 || execution.length() < 6) {
            return false;
         } else if (tipPeriod.compareTo(execution) <= 0) {
            return false;
         } else {
            String tipStoredRank = this.storedRankNameForCategory(context.rankName(), category);
            return this.normalizedEquals(tipStoredRank, storedRankName) && !this.normalizedEquals(tipStoredRank, targetRankName);
         }
      } else {
         return false;
      }
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion enrichRankAllowanceLaterPeriodPreview(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion base,
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context,
      String category,
      String executionPeriod,
      String targetRankName,
      String laterPeriodMode,
      Map<String, Integer> rankAllowanceAmounts
   ) {
      String organizationCode = this.emptyToNull(context.organizationCode());
      String personCode = this.emptyToNull(context.personCode());
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
      String execution = executionPeriod.replace(".", "");
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
      int successorCount = this.countBasicSalaryMidChainSuccessors(chain, anchor);
      if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
         return this.copyRankAllowanceChangePromotion(
            base,
            base.storedRankAllowance(),
            base.calculatedRankAllowance(),
            base.differenceAmount(),
            false,
            "当前为后变动人员（后继 " + successorCount + " 条），请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式。",
            false,
            successorCount
         );
      } else if (this.isLaterPeriodSequentialMode(laterPeriodMode)) {
         String tipPeriod = context.calculationPeriod();
         int tipStoredAllowance = this.nullToZero(context.storedRankAllowance());
         int tipCalculatedAllowance = this.calculatedRankAllowanceForChange(category, context, targetRankName, rankAllowanceAmounts);
         int tipDifference = tipCalculatedAllowance - tipStoredAllowance;
         boolean tipPositionEligible = this.payrollRepository.isRankAllowanceEligiblePosition(context.positionCode());
         boolean tipApplyEligible = tipDifference != 0 && tipPositionEligible;
         String moduleLabel = this.rankAllowanceChangeModuleLabel(category);
         String note = tipApplyEligible
            ? "后变动人员：顺延办理，" + moduleLabel + "执行年月为 " + this.formatYearMonth(tipPeriod) + "（当前变动年月）。"
            : "当前记录不满足" + moduleLabel + "办理条件。";
         return this.copyRankAllowanceChangePromotionWithPeriod(
            base, tipPeriod, tipStoredAllowance, tipCalculatedAllowance, tipDifference, tipApplyEligible, note, false, null
         );
      } else if (anchor == null) {
         return this.copyRankAllowanceChangePromotion(
            base,
            base.storedRankAllowance(),
            base.calculatedRankAllowance(),
            base.differenceAmount(),
            false,
            "未找到可插入" + this.rankAllowanceChangeModuleLabel(category) + "的历史锚点。",
            false,
            successorCount
         );
      } else {
         com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext anchorContext = this.rankAllowanceChangeContextFromSnapshot(
            anchor, context.organizationName()
         );
         int anchorStoredAllowance = this.nullToZero(anchor.storedRankAllowance());
         int anchorCalculatedAllowance = this.calculatedRankAllowanceForChange(category, anchorContext, targetRankName, rankAllowanceAmounts);
         int anchorDifference = anchorCalculatedAllowance - anchorStoredAllowance;
         boolean anchorPositionEligible = this.payrollRepository.isRankAllowanceEligiblePosition(anchor.positionCode());
         boolean anchorApplyEligible = anchorDifference != 0 && anchorPositionEligible;
         String moduleLabel = this.rankAllowanceChangeModuleLabel(category);
         String note = anchorApplyEligible
            ? "后变动人员：将在 " + executionPeriod + " 中段插入" + moduleLabel + "，并重算后继 " + successorCount + " 条记录。锚点试算差额 " + anchorDifference + "。"
            : "锚点记录不满足" + moduleLabel + "办理条件。";
         return this.copyRankAllowanceChangePromotion(
            base, anchorStoredAllowance, anchorCalculatedAllowance, anchorDifference, anchorApplyEligible, note, true, successorCount
         );
      }
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion copyRankAllowanceChangePromotion(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion base,
      Integer storedRankAllowance,
      Integer calculatedRankAllowance,
      Integer differenceAmount,
      Boolean applyEligible,
      String standardNote,
      Boolean midChainApply,
      Integer laterPeriodSuccessorCount
   ) {
      return this.copyRankAllowanceChangePromotionWithPeriod(
         base,
         base.calculationPeriod(),
         storedRankAllowance,
         calculatedRankAllowance,
         differenceAmount,
         applyEligible,
         standardNote,
         midChainApply,
         laterPeriodSuccessorCount
      );
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion copyRankAllowanceChangePromotionWithPeriod(
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion base,
      String calculationPeriod,
      Integer storedRankAllowance,
      Integer calculatedRankAllowance,
      Integer differenceAmount,
      Boolean applyEligible,
      String standardNote,
      Boolean midChainApply,
      Integer laterPeriodSuccessorCount
   ) {
      return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion(
         base.payrollHistoryId(),
         base.organizationCode(),
         base.organizationName(),
         base.personCode(),
         base.name(),
         calculationPeriod,
         base.positionCode(),
         base.positionName(),
         base.storedRankName(),
         base.targetRankName(),
         base.rankChangeYearMonth(),
         storedRankAllowance,
         calculatedRankAllowance,
         differenceAmount,
         base.eligible(),
         applyEligible,
         base.rollbackEligible(),
         standardNote,
         midChainApply,
         laterPeriodSuccessorCount
      );
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext rankAllowanceChangeContextFromSnapshot(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String organizationName
   ) {
      com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext standardContext = this.payrollRepository
         .findRankAllowanceStandardContext(history.id())
         .orElse(null);
      return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext(
         history.id(),
         history.organizationCode(),
         organizationName,
         history.personCode(),
         history.name(),
         history.calculationYear(),
         history.calculationMonth(),
         history.calculationType(),
         history.positionCode(),
         history.positionName(),
         history.rankName(),
         history.storedRankAllowance(),
         standardContext == null ? history.rankAllowanceStandardYearMonth() : standardContext.policeStandardYearMonth(),
         standardContext == null ? null : standardContext.prosecutionStandardYearMonth(),
         standardContext == null ? null : standardContext.judicialStandardYearMonth(),
         history.positionStartYearMonth()
      );
   }

   private String rankAllowanceChangeListCacheKey(OrganizationScope scope, String organizationCode, String keyword, String category, String laterPeriodMode) {
      String organizations = scope != null && !scope.all() ? scope.organizationCodes().stream().sorted().collect(Collectors.joining(",")) : "*";
      return organizations
         + "|"
         + Objects.toString(this.emptyToNull(organizationCode), "")
         + "|"
         + Objects.toString(this.emptyToNull(keyword), "")
         + "|"
         + Objects.toString(this.emptyToNull(category), "")
         + "|"
         + Objects.toString(this.emptyToNull(laterPeriodMode), "block");
   }

   private List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion> cachedRankAllowanceChangeList(String cacheKey) {
      com.dxsoft.rsgzgl.payroll.PayrollService.CachedRankAllowanceChangeList cached = this.rankAllowanceChangeListCache.get(cacheKey);
      if (cached == null) {
         return null;
      } else if (System.currentTimeMillis() - cached.createdAtMillis() > 120000L) {
         this.rankAllowanceChangeListCache.remove(cacheKey, cached);
         return null;
      } else {
         return cached.previews();
      }
   }

   private void invalidateRankAllowanceChangeListCache() {
      this.rankAllowanceChangeListCache.clear();
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion previewRankAllowanceChangePromotion(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String category, String changeTypePrefix
   ) {
      return this.previewRankAllowanceChangePromotion(history, category, changeTypePrefix, null);
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion previewRankAllowanceChangePromotion(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String category, String changeTypePrefix, String laterPeriodMode
   ) {
      com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext context = this.payrollRepository.findRankAllowanceStandardContext(history.id()).orElse(null);
      String organizationName = context == null
         ? this.payrollRepository.findOrganizationName(history.organizationCode()).orElse(history.organizationCode())
         : context.organizationName();
      String calculationPeriod = history.calculationYear() + history.calculationMonth();
      if (this.isRankAllowanceChangeProcessed(history.calculationType(), changeTypePrefix)) {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = this.payrollRepository
            .findPredecessorHistory(history.organizationCode(), history.personCode(), history.id())
            .orElse(null);
         String storedRankName = before == null ? "" : this.emptyToNull(before.rankName());
         String targetRankName = this.emptyToNull(history.rankName());
         Integer storedRankAllowance = before == null ? 0 : before.storedRankAllowance();
         Integer calculatedRankAllowance = history.storedRankAllowance();
         int difference = this.nullToZero(calculatedRankAllowance) - this.nullToZero(storedRankAllowance);
         return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion(
            history.id(),
            history.organizationCode(),
            organizationName,
            history.personCode(),
            history.name(),
            calculationPeriod,
            history.positionCode(),
            history.positionName(),
            this.emptyToDash(storedRankName),
            this.emptyToDash(targetRankName),
            this.emptyToNull(history.positionStartYearMonth()),
            storedRankAllowance,
            calculatedRankAllowance,
            difference,
            true,
            false,
            true,
            null,
            false,
            null
         );
      } else {
         com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext promotionContext = this.rankAllowanceChangeContextFromSnapshot(history, organizationName);
         List<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankChanges = this.payrollRepository
            .findRankAllowanceChangesByOrgPersons(
               List.of(new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(history.organizationCode(), history.personCode())), category
            )
            .getOrDefault(history.organizationCode() + "|" + history.personCode(), List.of());
         LinkedHashSet<String> standardPeriods = new LinkedHashSet<>();
         this.collectRankAllowanceStandardPeriods(promotionContext, category, standardPeriods);
         Map<String, Integer> rankAllowanceAmounts = standardPeriods.isEmpty()
            ? Map.of()
            : this.payrollRepository.findRankAllowanceAmountsByPeriods(standardPeriods);
         return this.previewPendingRankAllowanceChangePromotion(promotionContext, category, rankChanges, rankAllowanceAmounts, laterPeriodMode);
      }
   }

   private Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> findPendingRankAllowanceChange(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String category, String calculationPeriod
   ) {
      String storedRankName = this.storedRankNameForCategory(history.rankName(), category);
      String executingRankStart = this.executingRankStartYearMonth(
         history.organizationCode(), history.personCode(), category, storedRankName, calculationPeriod
      );
      return this.payrollRepository.findRankAllowanceChangeAfterForCategory(history.organizationCode(), history.personCode(), category, executingRankStart);
   }

   private String executingRankStartYearMonth(String organizationCode, String personCode, String category, String storedRankName, String calculationPeriod) {
      if (this.emptyToNull(storedRankName) != null) {
         Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> executingRank = this.payrollRepository
            .findExecutingRankAllowanceChange(organizationCode, personCode, category, storedRankName);
         if (executingRank.isPresent()) {
            return this.emptyToNull(executingRank.get().startYearMonth());
         }

         Optional<com.dxsoft.rsgzgl.payroll.RankAllowanceChange> rankAtPeriod = this.payrollRepository
            .findRankAllowanceAtOrBefore(organizationCode, personCode, calculationPeriod);
         if (rankAtPeriod.isPresent() && this.normalizedEquals(rankAtPeriod.get().rankName(), storedRankName)) {
            return this.emptyToNull(rankAtPeriod.get().startYearMonth());
         }
      }

      return "";
   }

   private int calculatedRankAllowanceForChange(
      String category,
      com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext context,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      String rankName
   ) {
      if (!this.payrollRepository.isRankAllowanceEligiblePosition(history.positionCode())) {
         return 0;
      } else {
         String policeStandard = context == null ? history.rankAllowanceStandardYearMonth() : context.policeStandardYearMonth();
         String prosecutionStandard = context == null ? null : context.prosecutionStandardYearMonth();
         String judicialStandard = context == null ? null : context.judicialStandardYearMonth();
         String normalizedRank = rankName == null ? "" : rankName.trim();

         return switch (category) {
            case "jx" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isPoliceRankName(normalizedRank) && this.emptyToNull(policeStandard) != null
            ? this.payrollRepository.rankAllowanceByRank(policeStandard, normalizedRank, "jx")
            : 0;
            case "jc" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isProsecutionRankName(normalizedRank) && this.emptyToNull(prosecutionStandard) != null
            ? this.payrollRepository.rankAllowanceByRank(prosecutionStandard, normalizedRank, "jc")
            : 0;
            case "sp" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isJudicialRankName(normalizedRank) && this.emptyToNull(judicialStandard) != null
            ? this.payrollRepository.rankAllowanceByRank(judicialStandard, normalizedRank, "sp")
            : 0;
            case "mt" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isSupervisionRankName(normalizedRank) && this.emptyToNull(policeStandard) != null
            ? this.payrollRepository.rankAllowanceByRank(policeStandard, normalizedRank, "mt")
            : 0;
            default -> this.payrollRepository
            .compositeRankAllowance(policeStandard, prosecutionStandard, judicialStandard, normalizedRank, history.positionCode());
         };
      }
   }

   private int compositeRankAllowanceForRank(
      com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext context, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String rankName
   ) {
      String policeStandard = context == null ? history.rankAllowanceStandardYearMonth() : context.policeStandardYearMonth();
      String prosecutionStandard = context == null ? null : context.prosecutionStandardYearMonth();
      String judicialStandard = context == null ? null : context.judicialStandardYearMonth();
      return this.payrollRepository.compositeRankAllowance(policeStandard, prosecutionStandard, judicialStandard, rankName, history.positionCode());
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangeApplyResult applyRankAllowanceChangePromotion(
      String payrollHistoryId, String category, String changeTypePrefix, String successMessage, String laterPeriodMode
   ) {
      this.requireRankAllowanceChangeWrite(category);
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current = this.payrollRepository
         .findCurrentHistoryById(payrollHistoryId)
         .orElseThrow(() -> new NotFoundException("Current payroll history not found: " + payrollHistoryId));
      this.accessControlService.requireOrganization(current.organizationCode());
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview = this.previewRankAllowanceChangePromotion(
         current, category, changeTypePrefix, laterPeriodMode
      );
      if (preview != null && Boolean.TRUE.equals(preview.applyEligible())) {
         String period = preview.calculationPeriod();
         if (period == null || period.length() != 6) {
            throw new IllegalArgumentException("试算执行年月无效。");
         } else if (!Boolean.TRUE.equals(preview.midChainApply())) {
            com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext context = this.payrollRepository.findRankAllowanceStandardContext(current.id()).orElse(null);
            int totalAmount = this.nullToZero(current.storedTotal()) + this.nullToZero(preview.differenceAmount());
            com.dxsoft.rsgzgl.payroll.RankAllowanceChangeHistoryMutation mutation = new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeHistoryMutation(
               period.substring(0, 4),
               period.substring(4, 6),
               changeTypePrefix,
               preview.targetRankName(),
               context == null ? current.rankAllowanceStandardYearMonth() : context.policeStandardYearMonth(),
               context == null ? null : context.prosecutionStandardYearMonth(),
               context == null ? null : context.judicialStandardYearMonth(),
               preview.calculatedRankAllowance(),
               totalAmount
            );
            int uid = this.requireCurrentHistoryUid(payrollHistoryId);
            String newId = this.payrollRepository.createRankAllowanceChangeHistoryFromLatest(uid, mutation);
            this.invalidateRankAllowanceChangeListCache();
            return com.dxsoft.rsgzgl.payroll.RankAllowanceChangeApplyResult.from(
               this.buildAppliedPayrollChange(current, newId, payrollHistoryId, changeTypePrefix, successMessage)
            );
         } else if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
            throw new IllegalArgumentException("当前为后变动人员，请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式后再办理。");
         } else {
            com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport export = this.writeRankAllowanceChangeMidChain(
               current, preview, category, changeTypePrefix
            );
            this.invalidateRankAllowanceChangeListCache();
            return com.dxsoft.rsgzgl.payroll.RankAllowanceChangeApplyResult.from(
               this.buildAppliedPayrollChange(
                  current,
                  export.adjustmentHistoryId(),
                  current.id(),
                  changeTypePrefix,
                  "中段" + this.rankAllowanceChangeModuleLabel(category) + "处理完成，已重算 " + export.successors().size() + " 条后继记录。"
               ),
               export
            );
         }
      } else {
         String note = preview == null ? null : this.emptyToNull(preview.standardNote());
         throw new IllegalArgumentException(note == null ? "当前人员不符合" + changeTypePrefix + "晋升办理条件。" : note);
      }
   }

   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport writeRankAllowanceChangeMidChain(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip,
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview,
      String category,
      String changeTypePrefix
   ) {
      String organizationCode = this.emptyToNull(tip.organizationCode());
      String personCode = this.emptyToNull(tip.personCode());
      if (organizationCode != null && personCode != null) {
         String executionPeriod = preview.calculationPeriod().replace(".", "");
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
         if (anchor == null) {
            throw new IllegalArgumentException("未找到可插入" + this.rankAllowanceChangeModuleLabel(category) + "的历史锚点。");
         } else {
            com.dxsoft.rsgzgl.payroll.RankAllowanceStandardContext context = this.payrollRepository.findRankAllowanceStandardContext(anchor.id()).orElse(null);
            int totalAmount = this.nullToZero(anchor.storedTotal()) + this.nullToZero(preview.differenceAmount());
            com.dxsoft.rsgzgl.payroll.RankAllowanceChangeHistoryMutation mutation = new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeHistoryMutation(
               executionPeriod.substring(0, 4),
               executionPeriod.substring(4, 6),
               changeTypePrefix,
               preview.targetRankName(),
               context == null ? anchor.rankAllowanceStandardYearMonth() : context.policeStandardYearMonth(),
               context == null ? null : context.prosecutionStandardYearMonth(),
               context == null ? null : context.judicialStandardYearMonth(),
               preview.calculatedRankAllowance(),
               totalAmount
            );
            String nextSuccessorId = this.findBasicSalaryMidChainNextSuccessorId(organizationCode, personCode, anchor, chain);
            String adjustmentHistoryId = this.payrollRepository.insertRankAllowanceChangeMidChain(anchor, nextSuccessorId, mutation);
            String policeStandard = context == null ? anchor.rankAllowanceStandardYearMonth() : context.policeStandardYearMonth();
            String prosecutionStandard = context == null ? null : context.prosecutionStandardYearMonth();
            String judicialStandard = context == null ? null : context.judicialStandardYearMonth();
            ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport.SuccessorRecalc> successors = new ArrayList<>();

            for (com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record : this.findBasicSalaryMidChainSuccessors(organizationCode, personCode, nextSuccessorId)) {
               String period = this.historyCalculationPeriod(record);
               int oldAllowance = this.nullToZero(record.storedRankAllowance());
               int newAllowance = this.nullToZero(preview.calculatedRankAllowance());
               int oldTotal = this.nullToZero(record.storedTotal());
               int newTotal = oldTotal + (newAllowance - oldAllowance);
               String oldRankName = this.emptyToNull(record.rankName());
               this.payrollRepository
                  .updateHistoryRankAllowanceAmounts(
                     organizationCode,
                     personCode,
                     record.id(),
                     preview.targetRankName(),
                     policeStandard,
                     prosecutionStandard,
                     judicialStandard,
                     newAllowance,
                     newTotal
                  );
               successors.add(
                  new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport.SuccessorRecalc(
                     period,
                     record.calculationType(),
                     oldRankName,
                     preview.targetRankName(),
                     oldAllowance,
                     newAllowance,
                     oldTotal,
                     newTotal,
                     newTotal - oldTotal
                  )
               );
            }

            String organizationName = this.payrollRepository.findOrganizationName(organizationCode).orElse(organizationCode);
            return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport(
               organizationCode, organizationName, personCode, tip.name(), executionPeriod, adjustmentHistoryId, successors
            );
         }
      } else {
         throw new IllegalArgumentException("缺少人员单位信息。");
      }
   }

