   private byte[] exportRankAllowanceChangeMidChainCsv(String organizationCode, String keyword, String category, String changeTypePrefix) {
      OrganizationScope scope = this.accessControlService.organizationScope(Optional.ofNullable(this.emptyToNull(organizationCode)));
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext> contexts = this.payrollRepository
         .findRankAllowanceChangePromotionContexts(scope, this.emptyToNull(organizationCode), keyword, category);
      ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport> exports = new ArrayList<>();

      for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotionContext context : contexts) {
         String org = this.emptyToNull(context.organizationCode());
         String person = this.emptyToNull(context.personCode());
         if (org != null && person != null) {
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip = this.payrollRepository.findCurrentHistoryByOrgPerson(org, person).orElse(null);
            if (tip != null) {
               com.dxsoft.rsgzgl.payroll.RankAllowanceChangePromotion preview = this.previewRankAllowanceChangePromotion(
                  tip, category, changeTypePrefix, "insertRecalc"
               );
               if (preview != null && Boolean.TRUE.equals(preview.midChainApply())) {
                  List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(org, person);
                  String executionPeriod = preview.calculationPeriod().replace(".", "");
                  boolean hasMidChainAdjustment = chain.stream()
                     .anyMatch(
                        recordx -> this.isRankAllowanceChangeProcessed(recordx.calculationType(), changeTypePrefix)
                              && executionPeriod.equals(this.historyCalculationPeriod(recordx))
                     );
                  if (hasMidChainAdjustment) {
                     String adjustmentHistoryId = chain.stream()
                        .filter(
                           recordx -> this.isRankAllowanceChangeProcessed(recordx.calculationType(), changeTypePrefix)
                                 && executionPeriod.equals(this.historyCalculationPeriod(recordx))
                        )
                        .map(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot::id)
                        .findFirst()
                        .orElse("");
                     String firstSuccessorId = this.payrollRepository.findSuccessorHistoryId(org, person, adjustmentHistoryId).orElse("");
                     ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport.SuccessorRecalc> successors = new ArrayList<>();

                     for (com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot record : this.findBasicSalaryMidChainSuccessors(org, person, firstSuccessorId)) {
                        String period = this.historyCalculationPeriod(record);
                        int oldAllowance = this.nullToZero(record.storedRankAllowance());
                        int newAllowance = this.nullToZero(preview.calculatedRankAllowance());
                        int oldTotal = this.nullToZero(record.storedTotal());
                        int newTotal = oldTotal + (newAllowance - oldAllowance);
                        successors.add(
                           new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport.SuccessorRecalc(
                              period,
                              record.calculationType(),
                              this.emptyToNull(record.rankName()),
                              preview.targetRankName(),
                              oldAllowance,
                              newAllowance,
                              oldTotal,
                              newTotal,
                              newTotal - oldTotal
                           )
                        );
                     }

                     if (!successors.isEmpty()) {
                        exports.add(
                           new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport(
                              org, context.organizationName(), person, context.name(), executionPeriod, adjustmentHistoryId, successors
                           )
                        );
                     }
                  }
               }
            }
         }
      }

      return this.buildRankAllowanceChangeMidChainExportCsv(exports);
   }

   private byte[] buildRankAllowanceChangeMidChainExportCsv(List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport> exports) {
      StringBuilder csv = new StringBuilder();
      csv.append("单位编码,单位名称,人员编码,姓名,执行年月,变动记录ID,后继变动年月,后继变动类别,原等级,新等级,原jxjt,新jxjt,原合计,新合计,差额\n");

      for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport export : exports) {
         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport.SuccessorRecalc successor : export.successors()) {
            csv.append(this.csvCell(export.organizationCode()))
               .append(',')
               .append(this.csvCell(export.organizationName()))
               .append(',')
               .append(this.csvCell(export.personCode()))
               .append(',')
               .append(this.csvCell(export.name()))
               .append(',')
               .append(this.csvCell(export.executionPeriod()))
               .append(',')
               .append(this.csvCell(export.adjustmentHistoryId()))
               .append(',')
               .append(this.csvCell(successor.period()))
               .append(',')
               .append(this.csvCell(successor.changeType()))
               .append(',')
               .append(this.csvCell(successor.oldRankName()))
               .append(',')
               .append(this.csvCell(successor.newRankName()))
               .append(',')
               .append(this.csvCell(successor.oldRankAllowance()))
               .append(',')
               .append(this.csvCell(successor.newRankAllowance()))
               .append(',')
               .append(this.csvCell(successor.oldTotal()))
               .append(',')
               .append(this.csvCell(successor.newTotal()))
               .append(',')
               .append(this.csvCell(successor.difference()))
               .append('\n');
         }
      }

      return csv.toString().getBytes(StandardCharsets.UTF_8);
   }

