   private com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyResult batchApplyRankAllowanceChangePromotions(
      String category,
      String changeTypePrefix,
      String successMessage,
      com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyRequest request,
      String laterPeriodMode
   ) {
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyRequest.RankAllowanceChangeBatchApplyItem> items = request != null && request.items() != null
         ? request.items()
         : List.of();
      if (items.isEmpty()) {
         throw new IllegalArgumentException("请选择需要办理的" + this.rankAllowanceChangeModuleLabel(category) + "记录。");
      } else {
         this.requireRankAllowanceChangeWrite(category);
         int successCount = 0;
         ArrayList<String> failures = new ArrayList<>();
         ArrayList<String> successIds = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyResult.SuccessItem> successes = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeMidChainExport> midChainExports = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyRequest.RankAllowanceChangeBatchApplyItem item : items) {
            String id = item == null ? null : this.emptyToNull(item.payrollHistoryId());
            if (id == null) {
               failures.add("缺少工资记录标识。");
            } else {
               try {
                  com.dxsoft.rsgzgl.payroll.RankAllowanceChangeApplyResult applied = this.applyRankAllowanceChangePromotion(
                     id, category, changeTypePrefix, successMessage, laterPeriodMode
                  );
                  successCount++;
                  successIds.add(id);
                  successes.add(
                     new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyResult.SuccessItem(id, applied.payrollHistoryId(), applied.changeType())
                  );
                  if (applied.midChainExport() != null) {
                     midChainExports.add(applied.midChainExport());
                  }
               } catch (RuntimeException var16) {
                  failures.add(id + "：" + (var16.getMessage() == null ? "办理失败" : var16.getMessage()));
               }
            }
         }

         int failureCount = failures.size();
         String message = failureCount == 0
            ? "批量处理完成：成功 " + successCount + " 条。"
            : "批量处理完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。" + (failures.isEmpty() ? "" : failures.get(0));
         return new com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchApplyResult(
            successCount, failureCount, failures, successIds, successes, message, midChainExports
         );
      }
   }

   private com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult batchRollbackRankAllowanceChangePromotions(
      String changeTypePrefix, com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchRollbackRequest request
   ) {
      List<com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchRollbackRequest.RankAllowanceChangeBatchRollbackItem> items = request != null
            && request.items() != null
         ? request.items()
         : List.of();
      if (items.isEmpty()) {
         throw new IllegalArgumentException("请选择需要还原的等级变化晋升记录。");
      } else {
         this.requireRankAllowanceChangeWriteByChangeType(changeTypePrefix);
         List<com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey> orgPersonKeys = items.stream()
            .filter(Objects::nonNull)
            .map(item -> new com.dxsoft.rsgzgl.payroll.PayrollRepository.OrgPersonKey(item.organizationCode(), item.personCode()))
            .filter(key -> this.emptyToNull(key.organizationCode()) != null && this.emptyToNull(key.personCode()) != null)
            .distinct()
            .toList();
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> currentById = this.payrollRepository.findCurrentHistoriesByOrgPersons(orgPersonKeys);
         LinkedHashSet<String> checkedOrganizations = new LinkedHashSet<>();
         int successCount = 0;
         ArrayList<String> failures = new ArrayList<>();
         ArrayList<String> successIds = new ArrayList<>();
         ArrayList<com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult.SuccessItem> successes = new ArrayList<>();

         for (com.dxsoft.rsgzgl.payroll.RankAllowanceChangeBatchRollbackRequest.RankAllowanceChangeBatchRollbackItem item : items) {
            String id = item == null ? null : this.emptyToNull(item.payrollHistoryId());
            if (id == null) {
               failures.add("缺少工资记录标识。");
            } else {
               try {
                  com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current = this.resolveCurrentHistoryForRankChangeRollback(id, item, currentById);
                  String organizationCode = this.emptyToNull(current.organizationCode());
                  if (organizationCode != null && checkedOrganizations.add(organizationCode)) {
                     this.accessControlService.requireOrganization(organizationCode);
                  }

                  com.dxsoft.rsgzgl.payroll.PromotionActionResult rolledBack = this.rollbackRankAllowanceChangePromotion(
                     current.id(), changeTypePrefix, "等级变化晋升已还原。"
                  );
                  successCount++;
                  successIds.add(id);
                  successes.add(
                     new com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult.SuccessItem(id, rolledBack.payrollHistoryId(), rolledBack.changeType())
                  );
               } catch (RuntimeException var17) {
                  failures.add(id + "：" + (var17.getMessage() == null ? "还原失败" : var17.getMessage()));
               }
            }
         }

         int failureCount = failures.size();
         String message = failureCount == 0
            ? "批量还原完成：成功 " + successCount + " 条。"
            : "批量还原完成：成功 " + successCount + " 条，失败 " + failureCount + " 条。" + (failures.isEmpty() ? "" : failures.get(0));
         return new com.dxsoft.rsgzgl.payroll.LevelPromotionBatchApplyResult(successCount, failureCount, failures, successIds, successes, message);
      }
   }

