   private String rankNameForCategory(String rankName, String category) {
      String normalized = this.emptyToNull(rankName);
      if (normalized == null) {
         return "";
      } else {
         return switch (category) {
            case "jx" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isPoliceRankName(normalized) ? normalized : "";
            case "jc" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isProsecutionRankName(normalized) ? normalized : "";
            case "sp" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isJudicialRankName(normalized) ? normalized : "";
            case "mt" -> com.dxsoft.rsgzgl.payroll.PayrollRepository.isSupervisionRankName(normalized) ? normalized : "";
            default -> normalized;
         };
      }
   }

