   private com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowanceCalculation(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String positionCode, String allowanceStandardYearMonth
   ) {
      int subsidyAllowance;
      BigDecimal performanceAllowance;
      if (this.performanceAndSubsidyDisabled(history)) {
         performanceAllowance = BigDecimal.ZERO;
         subsidyAllowance = 0;
      } else {
         performanceAllowance = this.payrollRepository.performanceAllowance(history.organizationCode(), positionCode, allowanceStandardYearMonth);
         subsidyAllowance = this.payrollRepository.subsidyAllowance(history.organizationCode(), positionCode, allowanceStandardYearMonth);
      }

      int retainedAllowance = this.payrollRepository.retainedAllowance(positionCode);
      BigDecimal yearAllowance = this.supportsRuralTeacherYearAllowance(positionCode)
         ? this.payrollRepository.yearAllowance(history.organizationCode(), allowanceStandardYearMonth)
         : BigDecimal.ZERO;
      return new com.dxsoft.rsgzgl.payroll.AllowanceCalculation(
         allowanceStandardYearMonth,
         positionCode,
         this.payrollRepository.performancePositionCode(positionCode, allowanceStandardYearMonth),
         this.payrollRepository.subsidyPositionCode(positionCode),
         this.payrollRepository.organizationPerformanceCategory(history.organizationCode()),
         this.payrollRepository.organizationPerformanceRatio(history.organizationCode()),
         performanceAllowance,
         subsidyAllowance,
         retainedAllowance,
         yearAllowance,
         history.storedPerformanceAllowance(),
         history.storedSubsidyAllowance(),
         history.storedRetainedAllowance(),
         history.storedYearAllowance()
      );
   }

   private boolean performanceAndSubsidyDisabled(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      String approved = history.individualPerformanceApproved();
      boolean organizationDisabled = history.organizationPerformanceEnabled() == null || history.organizationPerformanceEnabled() == 0;
      boolean individualNotApproved = !"是".equals(approved);
      boolean individualExplicitlyRejected = approved != null && !approved.isBlank() && "否".equals(approved);
      return organizationDisabled && individualNotApproved || individualExplicitlyRejected;
   }

