   private com.dxsoft.rsgzgl.payroll.PayrollTotalComparison totalComparison(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot calculationContext,
      List<com.dxsoft.rsgzgl.payroll.PayrollComponentValue> components,
      com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basic,
      com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowance,
      com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation additional,
      String teachingAllowancePeriod
   ) {
      Integer teachingAllowance = teachingAllowancePeriod != null && !teachingAllowancePeriod.isBlank()
         ? this.teachingAllowanceForPeriod(
            calculationContext,
            calculationContext.positionCode() != null && !calculationContext.positionCode().isBlank()
               ? calculationContext.positionCode()
               : history.positionCode(),
            teachingAllowancePeriod
         )
         : this.teachingAllowance(calculationContext);
      Integer salaryIncrease;
      if (teachingAllowancePeriod != null && !teachingAllowancePeriod.isBlank()) {
         String positionForIncrease = history.positionCode() != null && !history.positionCode().isBlank()
            ? history.positionCode()
            : calculationContext.positionCode();
         String salaryIncreasePeriod = this.emptyToNull(history.salaryStandardYearMonth()) != null
            ? history.salaryStandardYearMonth()
            : this.projectionPeriod(teachingAllowancePeriod);
         salaryIncrease = this.teachingIncreaseForPosition(
            calculationContext, positionForIncrease, basic.positionSalary(), basic.selectedBaseSalary(), salaryIncreasePeriod
         );
      } else {
         salaryIncrease = this.salaryIncrease(calculationContext, basic);
      }

      List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> componentDifferences = this.componentDifferences(
         history, basic, allowance, additional, teachingAllowance, salaryIncrease
      );
      BigDecimal storedComponentTotal = components.stream()
         .filter(component -> !"HJ2".equalsIgnoreCase(component.fieldName()))
         .map(com.dxsoft.rsgzgl.payroll.PayrollComponentValue::storedAmount)
         .reduce(BigDecimal.ZERO, BigDecimal::add);
      BigDecimal recalculatedKnownTotal = storedComponentTotal.subtract(BigDecimal.valueOf((long)history.storedPositionSalary().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(basic.positionSalary())))
         .subtract(BigDecimal.valueOf((long)history.storedGradeSalary().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(basic.selectedBaseSalary())))
         .subtract(BigDecimal.valueOf((long)history.storedTechnicalGradeSalary().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(basic.technicalGradeSalary())))
         .subtract(BigDecimal.valueOf((long)history.storedPerformanceAllowance().intValue()))
         .add(this.nullToZero(allowance.performanceAllowance()))
         .subtract(BigDecimal.valueOf((long)history.storedSubsidyAllowance().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(allowance.subsidyAllowance())))
         .subtract(BigDecimal.valueOf((long)history.storedRetainedAllowance().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(allowance.retainedAllowance())))
         .subtract(BigDecimal.valueOf((long)history.storedTeachingAllowance().intValue()))
         .add(BigDecimal.valueOf((long)teachingAllowance.intValue()))
         .subtract(BigDecimal.valueOf((long)history.storedSalaryIncrease().intValue()))
         .add(BigDecimal.valueOf((long)salaryIncrease.intValue()))
         .subtract(this.nullToZero(history.storedYearAllowance()))
         .add(this.nullToZero(allowance.yearAllowance()));
      recalculatedKnownTotal = recalculatedKnownTotal.subtract(BigDecimal.valueOf((long)history.storedRankAllowance().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(additional.rankAllowance())))
         .subtract(BigDecimal.valueOf((long)history.storedFloatingSalary().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(additional.floatingSalary())))
         .subtract(BigDecimal.valueOf((long)history.storedBonusBalance().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(additional.bonusBalance())))
         .subtract(BigDecimal.valueOf((long)history.storedRetainedSpecialPostAllowance().intValue()))
         .add(BigDecimal.valueOf((long)this.nullToZero(additional.retainedSpecialPostAllowance())));
      return new com.dxsoft.rsgzgl.payroll.PayrollTotalComparison(
         history.teachingStartYearMonth(),
         history.teachingInterruptedYears(),
         teachingAllowance,
         salaryIncrease,
         history.storedTeachingAllowance(),
         history.storedSalaryIncrease(),
         storedComponentTotal,
         recalculatedKnownTotal,
         history.storedTotal(),
         recalculatedKnownTotal.subtract(BigDecimal.valueOf((long)history.storedTotal().intValue())),
         componentDifferences
      );
   }

   private List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> componentDifferences(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.BasicPayrollCalculation basic,
      com.dxsoft.rsgzgl.payroll.AllowanceCalculation allowance,
      com.dxsoft.rsgzgl.payroll.AdditionalPayrollCalculation additional,
      Integer teachingAllowance,
      Integer salaryIncrease
   ) {
      ArrayList<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> differences = new ArrayList<>();
      this.addDifference(differences, "ZWGZSE2", "职务工资", history.storedPositionSalary(), basic.positionSalary());
      this.addDifference(differences, "JBGZSE2", "级别/薪级工资", history.storedGradeSalary(), basic.selectedBaseSalary());
      this.addDifference(differences, "JSDJGZ2", "技术等级工资", history.storedTechnicalGradeSalary(), basic.technicalGradeSalary());
      this.addDifference(differences, "DFBT2", this.dfbt2Caption(history), history.storedPerformanceAllowance(), allowance.performanceAllowance());
      this.addDifference(differences, "SDBT", this.sdbtCaption(history), history.storedSubsidyAllowance(), allowance.subsidyAllowance());
      this.addDifference(differences, "BLFB2", "保留福补", history.storedRetainedAllowance(), allowance.retainedAllowance());
      this.addDifference(differences, "NJBT", "农教补贴", history.storedYearAllowance(), allowance.yearAllowance());
      this.addDifference(differences, "JXJT", "警衔/检察/审判/监察津贴", history.storedRankAllowance(), additional.rankAllowance());
      this.addDifference(differences, "FDGZ2", "浮动工资", history.storedFloatingSalary(), additional.floatingSalary());
      this.addDifference(differences, "JJJY2", "奖金结余", history.storedBonusBalance(), additional.bonusBalance());
      this.addDifference(differences, "TGBLBF", "套改/特岗保留", history.storedRetainedSpecialPostAllowance(), additional.retainedSpecialPostAllowance());
      this.addDifference(differences, "JHLJT", "教护龄津贴", history.storedTeachingAllowance(), teachingAllowance);
      this.addDifference(differences, "JSFSZWTG2", "提高工资", history.storedSalaryIncrease(), salaryIncrease);
      return differences;
   }

