   private void addDifference(
      List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> differences,
      String fieldName,
      String caption,
      Integer storedAmount,
      BigDecimal calculatedAmount
   ) {
      this.addDifference(differences, fieldName, caption, BigDecimal.valueOf((long)this.nullToZero(storedAmount)), calculatedAmount);
   }

   private void addDifference(
      List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> differences, String fieldName, String caption, Integer storedAmount, Integer calculatedAmount
   ) {
      this.addDifference(
         differences, fieldName, caption, BigDecimal.valueOf((long)this.nullToZero(storedAmount)), BigDecimal.valueOf((long)this.nullToZero(calculatedAmount))
      );
   }

   private void addDifference(
      List<com.dxsoft.rsgzgl.payroll.PayrollComponentDifference> differences,
      String fieldName,
      String caption,
      BigDecimal storedAmount,
      BigDecimal calculatedAmount
   ) {
      BigDecimal stored = this.nullToZero(storedAmount);
      BigDecimal calculated = this.nullToZero(calculatedAmount);
      BigDecimal difference = calculated.subtract(stored);
      if (difference.compareTo(BigDecimal.ZERO) != 0) {
         differences.add(new com.dxsoft.rsgzgl.payroll.PayrollComponentDifference(fieldName, caption, stored, calculated, difference));
      }
   }

