   private Integer teachingIncreaseForPosition(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String positionCode, Integer positionSalary, Integer baseSalary
   ) {
      return this.teachingIncreaseForPosition(history, positionCode, positionSalary, baseSalary, history.salaryStandardYearMonth());
   }

   private Integer teachingIncreaseForPosition(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String positionCode, Integer positionSalary, Integer baseSalary, String salaryStandardYearMonth
   ) {
      int percentage = history.raisePercentage();
      if (this.isEducationPosition(positionCode) && percentage > 0) {
         int effectivePercentage = percentage;
         if (salaryStandardYearMonth != null
            && salaryStandardYearMonth.compareTo("201807") >= 0
            && this.isCompulsoryEducationTechnicalPosition(history.organizationCode(), positionCode)) {
            effectivePercentage = percentage - 10;
         }

         BigDecimal base = BigDecimal.valueOf((long)(this.nullToZero(positionSalary) + this.nullToZero(baseSalary)));
         return base.multiply(BigDecimal.valueOf((long)effectivePercentage)).divide(BigDecimal.valueOf(100L), 0, RoundingMode.HALF_UP).intValue();
      } else {
         return 0;
      }
   }

   private boolean isCompulsoryEducationTechnicalPosition(String organizationCode, String positionCode) {
      return positionCode != null && positionCode.startsWith("11")
         ? true
         : this.mapCompulsoryEducation10To11
            && positionCode != null
            && positionCode.startsWith("10")
            && this.payrollRepository.organizationPerformanceCategory(organizationCode) == 2;
   }

