   private com.dxsoft.rsgzgl.payroll.NormalPromotionPreview normalPromotionPreview(
      int uid,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache gradeCache,
      boolean forList,
      boolean listSummaryOnly,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId,
      String laterPeriodMode
   ) {
      if (history == null) {
         return null;
      } else if (this.isNormalPromotionProcessedInYear(history, promotionYear)) {
         return this.processedNormalPromotionPreview(uid, promotionYear, history, assessmentCache, listSummaryOnly, predecessorsByTipId);
      } else {
         int currentGradeStep = this.payrollRepository.intValue(history.positionSalaryGrade());
         int gradeStepDifferenceCount = this.payrollRepository.intValue(history.gradeSalaryStep());
         int highestGradeStep = this.payrollRepository.highestGradeStepForLevel(history.gradeSalaryLevel());
         String baseSalarySource = this.baseSalarySource(history.positionCode(), history.gradeSalaryLevel());
         String promotedGradeOrLevel;
         if ("GRADE".equals(baseSalarySource)) {
            if (currentGradeStep >= highestGradeStep) {
               int effectiveStep = Math.max(currentGradeStep, highestGradeStep + gradeStepDifferenceCount);
               promotedGradeOrLevel = String.valueOf(effectiveStep + 1);
            } else {
               promotedGradeOrLevel = String.valueOf(currentGradeStep + 1);
            }
         } else if ("JUDICIAL_GRADE".equals(baseSalarySource)) {
            promotedGradeOrLevel = String.valueOf(currentGradeStep + 1);
         } else if ("WORKER_GRADE".equals(baseSalarySource)) {
            promotedGradeOrLevel = String.valueOf(currentGradeStep + 1);
         } else {
            promotedGradeOrLevel = String.valueOf(currentGradeStep + 1);
         }

         Integer promotedBaseSalary;
         Integer currentBaseSalary;
         if (listSummaryOnly) {
            if (this.isPositionSalaryPromotionSource(baseSalarySource)) {
               currentBaseSalary = this.nullToZero(history.storedPositionSalary()) > 0 ? history.storedPositionSalary() : 0;
            } else {
               currentBaseSalary = this.nullToZero(history.storedGradeSalary()) > 0 ? history.storedGradeSalary() : 0;
            }

            promotedBaseSalary = currentBaseSalary;
         } else if ("JUDICIAL_GRADE".equals(baseSalarySource)) {
            int lookedUpCurrent = this.payrollRepository
               .positionGradeSalary(history.positionCode(), history.positionSalaryGrade(), "0", history.salaryStandardYearMonth());
            currentBaseSalary = this.nullToZero(history.storedPositionSalary()) > 0 ? history.storedPositionSalary() : lookedUpCurrent;
            promotedBaseSalary = this.payrollRepository
               .positionGradeSalary(history.positionCode(), promotedGradeOrLevel, "0", history.salaryStandardYearMonth());
            if (this.nullToZero(promotedBaseSalary) <= 0) {
               promotedBaseSalary = currentBaseSalary;
            }
         } else if ("WORKER_GRADE".equals(baseSalarySource)) {
            currentBaseSalary = this.nullToZero(history.storedPositionSalary()) > 0
               ? history.storedPositionSalary()
               : this.workerPositionSalary(history.positionCode(), history.positionSalaryGrade(), history.salaryStandardYearMonth());
            promotedBaseSalary = this.workerPositionSalary(history.positionCode(), promotedGradeOrLevel, history.salaryStandardYearMonth());
            if (this.nullToZero(promotedBaseSalary) <= 0) {
               promotedBaseSalary = currentBaseSalary;
            }
         } else {
            currentBaseSalary = this.nullToZero(history.storedGradeSalary()) > 0
               ? history.storedGradeSalary()
               : this.basicCalculation(history).selectedBaseSalary();
            if ("GRADE".equals(baseSalarySource)) {
               promotedBaseSalary = this.payrollRepository
                  .civilServantGradeSalary(history.gradeSalaryLevel(), promotedGradeOrLevel, "0", history.salaryStandardYearMonth());
            } else if ("POLICE_GRADE".equals(baseSalarySource)) {
               promotedBaseSalary = this.payrollRepository
                  .policeOfficerGradeSalary(history.gradeSalaryLevel(), this.policeGradeStep(promotedGradeOrLevel, "0"), history.salaryStandardYearMonth());
            } else {
               promotedBaseSalary = this.payrollRepository
                  .salaryLevelSalary(
                     promotedGradeOrLevel,
                     history.gradeSalaryStep(),
                     history.salaryStandardYearMonth(),
                     this.salaryStandardPositionCode(history.organizationCode(), history.positionCode(), history.salaryStandardYearMonth())
                  );
            }
         }

         int stepStartYear = this.assessmentStartYear(history.stepAssessmentStartYear(), history.positionStartYearMonth(), history.positionCode());
         int assessmentEndYear = promotionYear - 1;
         int qualifiedYears = assessmentCache == null
            ? this.payrollRepository.countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), stepStartYear, assessmentEndYear)
            : assessmentCache.countQualified(uid, stepStartYear, assessmentEndYear);
         List<Integer> missingStepAssessmentYears = assessmentCache == null
            ? this.missingAssessmentYears(history.organizationCode(), history.personCode(), stepStartYear, assessmentEndYear)
            : assessmentCache.missingYears(uid, stepStartYear, assessmentEndYear);
         int requiredYears = this.normalPromotionRequiredYears(history);
         String assessmentPeriod = this.formatAssessmentPeriod(stepStartYear, assessmentEndYear);
         boolean structurallyEligible = requiredYears > 0 && promotionYear >= 2007;
         boolean stepSpanMet = structurallyEligible && stepStartYear > 0 && promotionYear - stepStartYear >= requiredYears;
         boolean eligible = structurallyEligible && qualifiedYears >= requiredYears && missingStepAssessmentYears.isEmpty();
         boolean rollbackEligible = false;
         boolean overdueFromLastYear = eligible
            && this.isNormalStepPromotionDueInPriorYear(uid, promotionYear, stepStartYear, requiredYears, assessmentCache, history);
         com.dxsoft.rsgzgl.payroll.LevelPromotionPreview levelPreview = null;
         if (eligible && !overdueFromLastYear && !"WORKER_GRADE".equals(baseSalarySource)) {
            levelPreview = this.levelPromotionPreview(
               uid,
               promotionYear,
               history,
               assessmentCache,
               forList,
               gradeCache == null ? com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository) : gradeCache,
               listSummaryOnly
            );
         }

         boolean levelPromotionRequiredFirst = !overdueFromLastYear
            && levelPreview != null
            && Boolean.TRUE.equals(levelPreview.eligible())
            && Boolean.TRUE.equals(levelPreview.levelPromotionDue())
            && !Boolean.TRUE.equals(levelPreview.rollbackEligible());
         boolean applyEligible = eligible && !overdueFromLastYear && !levelPromotionRequiredFirst;
         Object note = "";
         if (overdueFromLastYear) {
            note = "上年符合";
         }

         if (levelPromotionRequiredFirst) {
            note = ((String)note).isEmpty() ? "需先办理级别晋升" : (String)note + "；需先办理级别晋升";
         }

         if (note.toString().isEmpty() && stepSpanMet && !eligible) {
            note = missingStepAssessmentYears.isEmpty() ? "不符合" : "缺考";
         }

         boolean positionSalaryPromotion = this.isPositionSalaryPromotionSource(baseSalarySource);
         int gradeIncrease = listSummaryOnly ? 0 : this.nullToZero(promotedBaseSalary) - this.nullToZero(currentBaseSalary);
         int teachingIncreaseDelta = listSummaryOnly ? 0 : this.normalPromotionTeachingIncreaseDelta(history, positionSalaryPromotion, promotedBaseSalary);
         int totalIncrease = gradeIncrease + teachingIncreaseDelta;
         Integer currentTotal = history.storedTotal();
         Integer promotedTotal = listSummaryOnly ? currentTotal : this.nullToZero(currentTotal) + totalIncrease;
         return this.enrichNormalPromotionLaterPeriodPreview(
            new com.dxsoft.rsgzgl.payroll.NormalPromotionPreview(
               uid,
               history.id(),
               history.organizationCode(),
               history.personCode(),
               history.name(),
               String.format("%04d01", promotionYear),
               history.calculationType(),
               history.positionCode(),
               history.positionName(),
               history.salaryStandardYearMonth(),
               history.positionSalaryGrade(),
               promotedGradeOrLevel,
               history.gradeSalaryLevel(),
               history.levelAssessmentStartYear(),
               stepStartYear > 0 ? String.valueOf(stepStartYear) : history.stepAssessmentStartYear(),
               String.valueOf(promotionYear),
               assessmentPeriod,
               qualifiedYears,
               requiredYears,
               eligible,
               applyEligible,
               overdueFromLastYear,
               levelPromotionRequiredFirst,
               rollbackEligible,
               (String)note,
               currentBaseSalary,
               promotedBaseSalary,
               totalIncrease,
               baseSalarySource,
               false,
               null,
               currentTotal,
               promotedTotal,
               gradeIncrease,
               totalIncrease
            ),
            history,
            promotionYear,
            laterPeriodMode
         );
      }
   }

   private com.dxsoft.rsgzgl.payroll.NormalPromotionPreview enrichNormalPromotionLaterPeriodPreview(
      com.dxsoft.rsgzgl.payroll.NormalPromotionPreview base, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip, int promotionYear, String laterPeriodMode
   ) {
      if (Boolean.TRUE.equals(base.applyEligible()) && this.isPromotionLaterPeriodCase(tip, promotionYear)) {
         String executionPeriod = this.promotionExecutionPeriod(promotionYear);
         String organizationCode = this.emptyToNull(tip.organizationCode());
         String personCode = this.emptyToNull(tip.personCode());
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
         int successorCount = this.countBasicSalaryMidChainSuccessors(chain, anchor);
         if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
            return this.copyNormalPromotionPreview(
               base,
               base.calculationPeriod(),
               base.currentBaseSalary(),
               base.promotedBaseSalary(),
               base.increaseAmount(),
               null,
               null,
               false,
               "当前为后变动人员（后继 " + successorCount + " 条），请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式。",
               false,
               successorCount
            );
         } else if (this.isLaterPeriodSequentialMode(laterPeriodMode)) {
            String tipPeriod = this.historyCalculationPeriod(tip);
            return this.copyNormalPromotionPreview(
               base,
               tipPeriod,
               base.currentBaseSalary(),
               base.promotedBaseSalary(),
               base.increaseAmount(),
               null,
               null,
               base.applyEligible(),
               "后变动人员：顺延办理，档次/薪级晋升执行年月为 " + this.formatYearMonth(tipPeriod) + "（当前变动年月）。",
               false,
               null
            );
         } else if (anchor == null) {
            return this.copyNormalPromotionPreview(
               base,
               base.calculationPeriod(),
               base.currentBaseSalary(),
               base.promotedBaseSalary(),
               base.increaseAmount(),
               null,
               null,
               false,
               "未找到可插入档次/薪级晋升的历史锚点。",
               false,
               successorCount
            );
         } else {
            com.dxsoft.rsgzgl.payroll.NormalPromotionPreview anchorPreview = this.normalPromotionPreview(
               base.uid(),
               promotionYear,
               anchor,
               null,
               com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository),
               false,
               false,
               null,
               "block"
            );
            boolean anchorApplyEligible = anchorPreview != null && Boolean.TRUE.equals(anchorPreview.applyEligible());
            String note = anchorApplyEligible
               ? "后变动人员：将在 "
                  + this.formatYearMonth(executionPeriod)
                  + " 中段插入档次/薪级晋升，并重算后继 "
                  + successorCount
                  + " 条记录。锚点试算差额 "
                  + this.nullToZero(anchorPreview.increaseAmount())
                  + "。"
               : "锚点记录不满足档次/薪级晋升办理条件。";
            return this.copyNormalPromotionPreview(
               base,
               base.calculationPeriod(),
               anchorPreview == null ? base.currentBaseSalary() : anchorPreview.currentBaseSalary(),
               anchorPreview == null ? base.promotedBaseSalary() : anchorPreview.promotedBaseSalary(),
               anchorPreview == null ? base.increaseAmount() : anchorPreview.increaseAmount(),
               anchorPreview == null ? base.currentTotal() : anchorPreview.currentTotal(),
               anchorPreview == null ? base.promotedTotal() : anchorPreview.promotedTotal(),
               anchorApplyEligible,
               note,
               true,
               successorCount
            );
         }
      } else {
         return base;
      }
   }

   private com.dxsoft.rsgzgl.payroll.NormalPromotionPreview copyNormalPromotionPreview(
      com.dxsoft.rsgzgl.payroll.NormalPromotionPreview base,
      String calculationPeriod,
      Integer currentBaseSalary,
      Integer promotedBaseSalary,
      Integer increaseAmount,
      Integer currentTotal,
      Integer promotedTotal,
      Boolean applyEligible,
      String note,
      Boolean midChainApply,
      Integer laterPeriodSuccessorCount
   ) {
      Integer resolvedCurrentBase = currentBaseSalary != null ? currentBaseSalary : base.currentBaseSalary();
      Integer resolvedPromotedBase = promotedBaseSalary != null ? promotedBaseSalary : base.promotedBaseSalary();
      Integer resolvedCurrentTotal = currentTotal != null ? currentTotal : base.currentTotal();
      Integer resolvedTotalIncrease = increaseAmount != null ? increaseAmount : base.totalIncrease();
      Integer resolvedPromotedTotal = promotedTotal != null
         ? promotedTotal
         : (resolvedCurrentTotal != null && resolvedTotalIncrease != null
            ? this.nullToZero(resolvedCurrentTotal) + resolvedTotalIncrease
            : base.promotedTotal());
      int resolvedBaseIncrease = this.nullToZero(resolvedPromotedBase) - this.nullToZero(resolvedCurrentBase);
      return new com.dxsoft.rsgzgl.payroll.NormalPromotionPreview(
         base.uid(),
         base.payrollHistoryId(),
         base.organizationCode(),
         base.personCode(),
         base.name(),
         calculationPeriod,
         base.changeType(),
         base.positionCode(),
         base.positionName(),
         base.salaryStandardYearMonth(),
         base.currentGradeOrLevel(),
         base.promotedGradeOrLevel(),
         base.gradeSalaryLevel(),
         base.levelAssessmentStartYear(),
         base.stepAssessmentStartYear(),
         base.nextStepAssessmentStartYear(),
         base.assessmentPeriod(),
         base.qualifiedYears(),
         base.requiredYears(),
         base.eligible(),
         applyEligible,
         base.overdueFromLastYear(),
         base.levelPromotionRequiredFirst(),
         base.rollbackEligible(),
         note,
         resolvedCurrentBase,
         resolvedPromotedBase,
         resolvedTotalIncrease,
         base.baseSalarySource(),
         midChainApply,
         laterPeriodSuccessorCount,
         resolvedCurrentTotal,
         resolvedPromotedTotal,
         resolvedBaseIncrease,
         resolvedTotalIncrease
      );
   }

   private com.dxsoft.rsgzgl.payroll.NormalPromotionPreview processedNormalPromotionPreview(
      int uid,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot after,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      boolean listSummaryOnly,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId
   ) {
      String tipId = after.id() == null ? "" : after.id().trim();
      String changeType = after.calculationType();
      String calculationPeriod = this.firstNonBlank(
         (after.calculationYear() == null ? "" : after.calculationYear()) + (after.calculationMonth() == null ? "" : after.calculationMonth()),
         String.format("%04d01", promotionYear)
      );
      String note = "当前最近工资变动为「" + this.emptyToDash(changeType) + "」，可执行还原。";
      String baseSalarySource = this.baseSalarySource(after.positionCode(), after.gradeSalaryLevel());
      if (listSummaryOnly) {
         Integer tipSalary = this.normalPromotionStoredBaseSalary(after, baseSalarySource);
         Integer tipTotal = after.storedTotal();
         return new com.dxsoft.rsgzgl.payroll.NormalPromotionPreview(
            uid,
            after.id(),
            after.organizationCode(),
            after.personCode(),
            after.name(),
            calculationPeriod,
            changeType,
            after.positionCode(),
            after.positionName(),
            after.salaryStandardYearMonth(),
            after.positionSalaryGrade(),
            after.positionSalaryGrade(),
            after.gradeSalaryLevel(),
            after.levelAssessmentStartYear(),
            after.stepAssessmentStartYear(),
            after.stepAssessmentStartYear(),
            "",
            0,
            0,
            false,
            false,
            false,
            false,
            true,
            note,
            tipSalary,
            tipSalary,
            0,
            baseSalarySource,
            false,
            null,
            tipTotal,
            tipTotal,
            0,
            0
         );
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = null;
         if (predecessorsByTipId != null && !tipId.isEmpty()) {
            before = predecessorsByTipId.get(tipId);
         }

         if (before == null) {
            before = this.payrollRepository.findPredecessorHistory(after.organizationCode(), after.personCode(), after.id()).orElse(null);
         }

         if (before == null) {
            before = this.payrollRepository.findPredecessorHistoryId(after.id()).flatMap(this.payrollRepository::findPayrollHistoryById).orElse(null);
         }

         if (before == null) {
            Integer tipSalary = this.normalPromotionStoredBaseSalary(after, baseSalarySource);
            Integer tipTotal = after.storedTotal();
            return new com.dxsoft.rsgzgl.payroll.NormalPromotionPreview(
               uid,
               after.id(),
               after.organizationCode(),
               after.personCode(),
               after.name(),
               calculationPeriod,
               changeType,
               after.positionCode(),
               after.positionName(),
               after.salaryStandardYearMonth(),
               after.positionSalaryGrade(),
               after.positionSalaryGrade(),
               after.gradeSalaryLevel(),
               after.levelAssessmentStartYear(),
               after.stepAssessmentStartYear(),
               after.stepAssessmentStartYear(),
               "",
               0,
               this.normalPromotionRequiredYears(after),
               false,
               false,
               false,
               false,
               true,
               note + "；未找到办理前记录，列表仅展示办理后状态。",
               tipSalary,
               tipSalary,
               0,
               baseSalarySource,
               false,
               null,
               tipTotal,
               tipTotal,
               0,
               0
            );
         } else {
            int stepStartYear = this.assessmentStartYear(before.stepAssessmentStartYear(), before.positionStartYearMonth(), before.positionCode());
            int assessmentEndYear = promotionYear - 1;
            int qualifiedYears = assessmentCache == null
               ? this.payrollRepository.countQualifiedAssessmentYears(before.organizationCode(), before.personCode(), stepStartYear, assessmentEndYear)
               : assessmentCache.countQualified(uid, stepStartYear, assessmentEndYear);
            int requiredYears = this.normalPromotionRequiredYears(before);
            String assessmentPeriod = this.formatAssessmentPeriod(stepStartYear, assessmentEndYear);
            Integer currentBaseSalary = this.normalPromotionStoredBaseSalary(before, baseSalarySource);
            if (this.nullToZero(currentBaseSalary) <= 0) {
               currentBaseSalary = this.basicCalculation(before).selectedBaseSalary();
            }

            Integer promotedBaseSalary = this.normalPromotionStoredBaseSalary(after, baseSalarySource);
            if (this.nullToZero(promotedBaseSalary) <= 0) {
               promotedBaseSalary = this.basicCalculation(after).selectedBaseSalary();
            }

            Integer currentTotal = before.storedTotal();
            Integer promotedTotal = after.storedTotal();
            int baseSalaryIncrease = this.nullToZero(promotedBaseSalary) - this.nullToZero(currentBaseSalary);
            int totalIncrease = this.nullToZero(promotedTotal) - this.nullToZero(currentTotal);
            return new com.dxsoft.rsgzgl.payroll.NormalPromotionPreview(
               uid,
               after.id(),
               after.organizationCode(),
               after.personCode(),
               after.name(),
               calculationPeriod,
               changeType,
               after.positionCode(),
               after.positionName(),
               after.salaryStandardYearMonth(),
               before.positionSalaryGrade(),
               after.positionSalaryGrade(),
               after.gradeSalaryLevel(),
               before.levelAssessmentStartYear(),
               before.stepAssessmentStartYear(),
               after.stepAssessmentStartYear(),
               assessmentPeriod,
               qualifiedYears,
               requiredYears,
               false,
               false,
               false,
               false,
               true,
               note,
               currentBaseSalary,
               promotedBaseSalary,
               totalIncrease,
               baseSalarySource,
               false,
               null,
               currentTotal,
               promotedTotal,
               baseSalaryIncrease,
               totalIncrease
            );
         }
      }
   }

   private Integer normalPromotionStoredBaseSalary(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String baseSalarySource) {
      if (history == null) {
         return 0;
      } else {
         return !"JUDICIAL_GRADE".equals(baseSalarySource) && !"WORKER_GRADE".equals(baseSalarySource)
            ? this.nullToZero(history.storedGradeSalary()) > 0 ? history.storedGradeSalary() : 0
            : this.nullToZero(history.storedPositionSalary()) > 0 ? history.storedPositionSalary() : 0;
      }
   }

   private String formatAssessmentPeriod(int startYear, int endYear) {
      if (startYear <= 0 || endYear < startYear) {
         return "";
      } else {
         return startYear == endYear ? String.valueOf(startYear) : startYear + "～" + endYear;
      }
   }

   private int resolveNormalPromotionYear(String year) {
      String normalized = this.emptyToNull(year);
      if (normalized == null) {
         return LocalDate.now().getYear();
      } else if (!normalized.matches("\\d{4}")) {
         throw new IllegalArgumentException("晋升年度必须为四位年份。");
      } else {
         return Integer.parseInt(normalized);
      }
   }

