   private com.dxsoft.rsgzgl.payroll.LevelPromotionPreview levelPromotionPreview(
      int uid,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      boolean forList,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache gradeCache,
      boolean listSummaryOnly,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId,
      String laterPeriodMode
   ) {
      if (history == null) {
         return null;
      } else if (this.isLevelPromotionProcessedInYear(history, promotionYear)) {
         return this.processedLevelPromotionPreview(uid, promotionYear, history, assessmentCache, listSummaryOnly, predecessorsByTipId);
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache = gradeCache == null
            ? com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository)
            : gradeCache;
         int levelStartYear = this.yearOf(history.levelAssessmentStartYear());
         if (levelStartYear <= 0 && !forList) {
            levelStartYear = this.yearOf(this.inheritedLevelAssessmentStartYear(history));
         }

         if (levelStartYear <= 0) {
            levelStartYear = this.assessmentStartYear(history.levelAssessmentStartYear(), history.positionStartYearMonth(), history.positionCode());
         }

         int stepStartYear = this.yearOf(history.stepAssessmentStartYear());
         if (stepStartYear <= 0) {
            stepStartYear = this.assessmentStartYear(history.stepAssessmentStartYear(), history.positionStartYearMonth(), history.positionCode());
         }

         int assessmentEndYear = promotionYear - 1;
         int qualifiedYearsForLevel = assessmentCache == null
            ? this.payrollRepository.countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), levelStartYear, assessmentEndYear)
            : assessmentCache.countQualified(uid, levelStartYear, assessmentEndYear);
         int qualifiedYearsForStep = assessmentCache == null
            ? this.payrollRepository.countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), stepStartYear, assessmentEndYear)
            : assessmentCache.countQualified(uid, stepStartYear, assessmentEndYear);
         List<Integer> missingLevelAssessmentYears = assessmentCache == null
            ? this.missingAssessmentYears(history.organizationCode(), history.personCode(), levelStartYear, assessmentEndYear)
            : assessmentCache.missingYears(uid, levelStartYear, assessmentEndYear);
         boolean levelSpanMeetsFiveYears = levelStartYear > 0 && promotionYear - levelStartYear >= 5;
         com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState projectionState = this.projectionStateFromHistory(history);
         com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation rollingSimulation = new com.dxsoft.rsgzgl.payroll.PayrollService.ReformRollingSimulation(
            OptionalInt.empty(), null
         );
         OptionalInt reformRollingYear = OptionalInt.empty();
         boolean reformProjectionEligible = false;
         if (this.supportsReformLevelRollingInPromotionYear(promotionYear)) {
            com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionStart projectionStart = this.wageProjectionStart(history);
            reformProjectionEligible = projectionStart.eligible();
            int payrollPeriod = this.payrollRepository.intValue(this.normalizeYearMonth(history.calculationYear() + history.calculationMonth()));
            Set<Integer> appliedRollingYears = this.appliedReformLevelRollingYears(history);
            rollingSimulation = this.simulateReformLevelRolling(history, projectionStart, promotionYear, appliedRollingYears, payrollPeriod);
            reformRollingYear = rollingSimulation.pendingYear();
         }

         boolean eligible = this.isLevelPromotionPosition(history.positionCode())
            && this.supportsGradePromotion(projectionState)
            && this.payrollRepository.intValue(history.gradeSalaryLevel()) > 1
            && promotionYear >= 2007;
         boolean reformLevelRollingDue = eligible && reformProjectionEligible && reformRollingYear.isPresent() && reformRollingYear.getAsInt() == promotionYear;
         boolean normalLevelDue = eligible
            && !reformLevelRollingDue
            && levelSpanMeetsFiveYears
            && qualifiedYearsForLevel >= 5
            && missingLevelAssessmentYears.isEmpty();
         boolean levelPromotionDue = normalLevelDue || reformLevelRollingDue;
         boolean stepPromotionDue = eligible && qualifiedYearsForStep >= 2;
         boolean rollbackEligible = false;
         boolean overdueFromLastYear = normalLevelDue && qualifiedYearsForLevel > 5 || levelSpanMeetsFiveYears && qualifiedYearsForLevel > 5;
         boolean earlierStepPromotionPending = this.isEarlierNormalStepPromotionPending(
            uid, promotionYear, stepStartYear, assessmentCache, history, eligible, rollbackEligible
         );
         boolean applyEligible = eligible && levelPromotionDue && !overdueFromLastYear && !earlierStepPromotionPending;
         boolean levelPromotionHintOnly = eligible && !applyEligible && !overdueFromLastYear && !earlierStepPromotionPending && levelSpanMeetsFiveYears;
         boolean listVisible = applyEligible
            || reformLevelRollingDue
            || earlierStepPromotionPending
            || overdueFromLastYear
            || eligible && levelSpanMeetsFiveYears;
         if (forList && !listSummaryOnly && !listVisible) {
            return null;
         } else {
            Integer currentGradeSalary = this.nullToZero(history.storedGradeSalary()) > 0
               ? history.storedGradeSalary()
               : (
                  listSummaryOnly
                     ? this.nullToZero(history.storedGradeSalary())
                     : this.levelPromotionGradeSalary(
                        history.positionCode(),
                        history.gradeSalaryLevel(),
                        history.positionSalaryGrade(),
                        history.gradeSalaryStep(),
                        history.salaryStandardYearMonth()
                     )
               );
            String currentStep = history.positionSalaryGrade();
            String currentStepDifference = history.gradeSalaryStep();
            String promotedLevel = history.gradeSalaryLevel();
            String promotedStep = currentStep;
            Integer promotedGradeSalary = currentGradeSalary;
            boolean policeGrade = "POLICE_GRADE".equals(this.baseSalarySource(history.positionCode(), history.gradeSalaryLevel()));
            if (!listSummaryOnly && eligible && reformLevelRollingDue) {
               com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState stateBeforeRolling = rollingSimulation.stateBeforePendingRolling();
               String previousLevel = stateBeforeRolling.level();
               String previousStep = stateBeforeRolling.stepOrSalaryLevel();
               int currentSalary = this.gradeSalaryAmount(stateBeforeRolling, previousLevel, previousStep, stateBeforeRolling.salaryStandardYearMonth());
               promotedLevel = this.cappedPromotedLevel(
                  stateBeforeRolling.positionCode(), String.valueOf(Math.max(1, this.payrollRepository.intValue(previousLevel) - 1))
               );
               promotedStep = policeGrade
                  ? this.firstHigherPoliceGradeStep(previousLevel, previousStep, promotedLevel, stateBeforeRolling.salaryStandardYearMonth())
                  : this.firstHigherGradeStep(promotedLevel, currentSalary, stateBeforeRolling.salaryStandardYearMonth(), cache);
               String var54 = "0";
               promotedGradeSalary = this.levelPromotionGradeSalary(
                  stateBeforeRolling.positionCode(), promotedLevel, promotedStep, var54, stateBeforeRolling.salaryStandardYearMonth()
               );
            } else if (!listSummaryOnly && eligible && normalLevelDue) {
               promotedLevel = String.valueOf(this.payrollRepository.intValue(history.gradeSalaryLevel()) - 1);
               promotedStep = policeGrade
                  ? this.firstHigherPoliceGradeStep(history.gradeSalaryLevel(), currentStep, promotedLevel, history.salaryStandardYearMonth())
                  : this.firstHigherGradeStep(promotedLevel, currentGradeSalary, history.salaryStandardYearMonth(), cache);
               String promotedStepDifference = "0";
               promotedGradeSalary = this.levelPromotionGradeSalary(
                  history.positionCode(), promotedLevel, promotedStep, promotedStepDifference, history.salaryStandardYearMonth()
               );
            }

            String gradeIncreasePreviousLevel = reformLevelRollingDue && rollingSimulation.stateBeforePendingRolling() != null
               ? rollingSimulation.stateBeforePendingRolling().level()
               : history.gradeSalaryLevel();
            String gradeIncreasePreviousStep = reformLevelRollingDue && rollingSimulation.stateBeforePendingRolling() != null
               ? rollingSimulation.stateBeforePendingRolling().stepOrSalaryLevel()
               : currentStep;
            String gradeIncreaseStandardYearMonth = reformLevelRollingDue && rollingSimulation.stateBeforePendingRolling() != null
               ? rollingSimulation.stateBeforePendingRolling().salaryStandardYearMonth()
               : history.salaryStandardYearMonth();
            boolean gradeIncreaseExceedsStepDifference = !listSummaryOnly
               && eligible
               && levelPromotionDue
               && this.gradeIncreaseExceedsStepDifference(
                  history.positionCode(), gradeIncreasePreviousLevel, gradeIncreasePreviousStep, promotedLevel, gradeIncreaseStandardYearMonth
               );
            String promotionEffectYear = reformLevelRollingDue ? String.valueOf(reformRollingYear.getAsInt()) : String.valueOf(promotionYear);
            String nextLevelAssessmentStartYear = levelPromotionDue ? promotionEffectYear : String.valueOf(levelStartYear);
            String nextStepAssessmentStartYear = gradeIncreaseExceedsStepDifference ? promotionEffectYear : String.valueOf(stepStartYear);
            Object note = this.composeLevelPromotionNote(
               this.levelPromotionNote(
                  eligible,
                  reformLevelRollingDue,
                  normalLevelDue,
                  stepPromotionDue,
                  gradeIncreaseExceedsStepDifference,
                  levelSpanMeetsFiveYears,
                  qualifiedYearsForLevel
               ),
               missingLevelAssessmentYears
            );
            if (earlierStepPromotionPending) {
               note = "上年符合档次晋升条件";
            }

            com.dxsoft.rsgzgl.payroll.LevelPromotionPreview base = new com.dxsoft.rsgzgl.payroll.LevelPromotionPreview(
               uid,
               history.id(),
               history.organizationCode(),
               history.personCode(),
               history.name(),
               String.format("%04d01", promotionYear),
               history.calculationType(),
               history.positionCode(),
               history.positionName(),
               history.salaryStandardYearMonth(),
               history.gradeSalaryLevel(),
               currentStep,
               promotedLevel,
               promotedStep,
               String.valueOf(levelStartYear),
               String.valueOf(stepStartYear),
               nextLevelAssessmentStartYear,
               nextStepAssessmentStartYear,
               qualifiedYearsForLevel,
               qualifiedYearsForStep,
               levelPromotionDue,
               stepPromotionDue,
               reformLevelRollingDue,
               gradeIncreaseExceedsStepDifference,
               currentGradeSalary,
               promotedGradeSalary,
               this.nullToZero(promotedGradeSalary) - this.nullToZero(currentGradeSalary),
               eligible,
               rollbackEligible,
               applyEligible,
               overdueFromLastYear,
               earlierStepPromotionPending,
               levelPromotionHintOnly,
               (String)note,
               false,
               null
            );
            return this.enrichLevelPromotionLaterPeriodPreview(base, history, promotionYear, laterPeriodMode);
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.LevelPromotionPreview enrichLevelPromotionLaterPeriodPreview(
      com.dxsoft.rsgzgl.payroll.LevelPromotionPreview base, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot tip, int promotionYear, String laterPeriodMode
   ) {
      if (Boolean.TRUE.equals(base.applyEligible()) && this.isPromotionLaterPeriodCase(tip, promotionYear)) {
         String executionPeriod = this.promotionExecutionPeriod(promotionYear);
         String organizationCode = this.emptyToNull(tip.organizationCode());
         String personCode = this.emptyToNull(tip.personCode());
         List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain = this.findSidOrderedHistoryChain(organizationCode, personCode);
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot anchor = this.findBasicSalaryMidChainAnchor(chain, executionPeriod);
         int successorCount = this.countBasicSalaryMidChainSuccessors(chain, anchor);
         if (this.isLaterPeriodBlockMode(laterPeriodMode)) {
            return this.copyLevelPromotionPreview(
               base,
               base.calculationPeriod(),
               base.currentGradeSalary(),
               base.promotedGradeSalary(),
               base.increaseAmount(),
               false,
               "当前为后变动人员（后继 " + successorCount + " 条），请先还原后续变动，或切换为「中段插入重算」/「顺延办理」模式。",
               false,
               successorCount
            );
         } else if (this.isLaterPeriodSequentialMode(laterPeriodMode)) {
            String tipPeriod = this.historyCalculationPeriod(tip);
            return this.copyLevelPromotionPreview(
               base,
               tipPeriod,
               base.currentGradeSalary(),
               base.promotedGradeSalary(),
               base.increaseAmount(),
               base.applyEligible(),
               "后变动人员：顺延办理，级别晋升执行年月为 " + this.formatYearMonth(tipPeriod) + "（当前变动年月）。",
               false,
               null
            );
         } else if (anchor == null) {
            return this.copyLevelPromotionPreview(
               base,
               base.calculationPeriod(),
               base.currentGradeSalary(),
               base.promotedGradeSalary(),
               base.increaseAmount(),
               false,
               "未找到可插入级别晋升的历史锚点。",
               false,
               successorCount
            );
         } else {
            com.dxsoft.rsgzgl.payroll.LevelPromotionPreview anchorPreview = this.levelPromotionPreview(
               base.uid(),
               promotionYear,
               anchor,
               null,
               false,
               com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository),
               false,
               null,
               "block"
            );
            boolean anchorApplyEligible = anchorPreview != null && Boolean.TRUE.equals(anchorPreview.applyEligible());
            String note = anchorApplyEligible
               ? "后变动人员：将在 "
                  + this.formatYearMonth(executionPeriod)
                  + " 中段插入级别晋升，并重算后继 "
                  + successorCount
                  + " 条记录。锚点试算差额 "
                  + this.nullToZero(anchorPreview.increaseAmount())
                  + "。"
               : "锚点记录不满足级别晋升办理条件。";
            return this.copyLevelPromotionPreview(
               base,
               base.calculationPeriod(),
               anchorPreview == null ? base.currentGradeSalary() : anchorPreview.currentGradeSalary(),
               anchorPreview == null ? base.promotedGradeSalary() : anchorPreview.promotedGradeSalary(),
               anchorPreview == null ? base.increaseAmount() : anchorPreview.increaseAmount(),
               anchorApplyEligible,
               note,
               true,
               successorCount
            );
         }
      } else {
         return base;
      }
   }

   private com.dxsoft.rsgzgl.payroll.LevelPromotionPreview copyLevelPromotionPreview(
      com.dxsoft.rsgzgl.payroll.LevelPromotionPreview base,
      String calculationPeriod,
      Integer currentGradeSalary,
      Integer promotedGradeSalary,
      Integer increaseAmount,
      Boolean applyEligible,
      String note,
      Boolean midChainApply,
      Integer laterPeriodSuccessorCount
   ) {
      return new com.dxsoft.rsgzgl.payroll.LevelPromotionPreview(
         base.uid(),
         base.payrollHistoryId(),
         base.organizationCode(),
         base.personCode(),
         base.name(),
         calculationPeriod,
         base.changeType(),
         base.positionCode(),
         base.positionName(),
         base.salaryStandardYearMonth(),
         base.currentLevel(),
         base.currentStep(),
         base.promotedLevel(),
         base.promotedStep(),
         base.levelAssessmentStartYear(),
         base.stepAssessmentStartYear(),
         base.nextLevelAssessmentStartYear(),
         base.nextStepAssessmentStartYear(),
         base.qualifiedYearsForLevel(),
         base.qualifiedYearsForStep(),
         base.levelPromotionDue(),
         base.stepPromotionDue(),
         base.reformLevelRollingDue(),
         base.gradeIncreaseExceedsStepDifference(),
         currentGradeSalary,
         promotedGradeSalary,
         increaseAmount,
         base.eligible(),
         base.rollbackEligible(),
         applyEligible,
         base.overdueFromLastYear(),
         base.earlierStepPromotionPending(),
         base.levelPromotionHintOnly(),
         note,
         midChainApply,
         laterPeriodSuccessorCount
      );
   }

   private com.dxsoft.rsgzgl.payroll.LevelPromotionPreview processedLevelPromotionPreview(
      int uid,
      int promotionYear,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot after,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      boolean listSummaryOnly,
      Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByTipId
   ) {
      String tipId = after.id() == null ? "" : after.id().trim();
      String changeType = after.calculationType();
      String calculationPeriod = this.firstNonBlank(
         (after.calculationYear() == null ? "" : after.calculationYear()) + (after.calculationMonth() == null ? "" : after.calculationMonth()),
         String.format("%04d01", promotionYear)
      );
      String note = "已处理";
      boolean reformRolling = "级别滚动".equals(changeType);
      if (listSummaryOnly) {
         Integer tipSalary = this.nullToZero(after.storedGradeSalary()) > 0 ? after.storedGradeSalary() : 0;
         return new com.dxsoft.rsgzgl.payroll.LevelPromotionPreview(
            uid,
            after.id(),
            after.organizationCode(),
            after.personCode(),
            after.name(),
            calculationPeriod,
            changeType,
            after.positionCode(),
            after.positionName(),
            after.salaryStandardYearMonth(),
            after.gradeSalaryLevel(),
            after.positionSalaryGrade(),
            after.gradeSalaryLevel(),
            after.positionSalaryGrade(),
            after.levelAssessmentStartYear(),
            after.stepAssessmentStartYear(),
            after.levelAssessmentStartYear(),
            after.stepAssessmentStartYear(),
            0,
            0,
            true,
            false,
            reformRolling,
            false,
            tipSalary,
            tipSalary,
            0,
            false,
            true,
            false,
            false,
            false,
            false,
            note,
            false,
            null
         );
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = null;
         if (predecessorsByTipId != null && !tipId.isEmpty()) {
            before = predecessorsByTipId.get(tipId);
         }

         if (before == null) {
            before = this.payrollRepository.findPredecessorHistory(after.organizationCode(), after.personCode(), after.id()).orElse(null);
         }

         if (before == null) {
            before = this.payrollRepository.findPredecessorHistoryId(after.id()).flatMap(this.payrollRepository::findPayrollHistoryById).orElse(null);
         }

         if (before == null) {
            Integer tipSalary = this.nullToZero(after.storedGradeSalary()) > 0 ? after.storedGradeSalary() : 0;
            return new com.dxsoft.rsgzgl.payroll.LevelPromotionPreview(
               uid,
               after.id(),
               after.organizationCode(),
               after.personCode(),
               after.name(),
               calculationPeriod,
               changeType,
               after.positionCode(),
               after.positionName(),
               after.salaryStandardYearMonth(),
               after.gradeSalaryLevel(),
               after.positionSalaryGrade(),
               after.gradeSalaryLevel(),
               after.positionSalaryGrade(),
               after.levelAssessmentStartYear(),
               after.stepAssessmentStartYear(),
               after.levelAssessmentStartYear(),
               after.stepAssessmentStartYear(),
               0,
               0,
               true,
               false,
               reformRolling,
               false,
               tipSalary,
               tipSalary,
               0,
               false,
               true,
               false,
               false,
               false,
               false,
               "已处理；未找到办理前记录，列表仅展示办理后状态。",
               false,
               null
            );
         } else {
            Integer currentGradeSalary = this.nullToZero(before.storedGradeSalary()) > 0
               ? before.storedGradeSalary()
               : this.payrollRepository
                  .civilServantGradeSalary(before.gradeSalaryLevel(), before.positionSalaryGrade(), before.gradeSalaryStep(), before.salaryStandardYearMonth());
            Integer promotedGradeSalary = this.nullToZero(after.storedGradeSalary()) > 0
               ? after.storedGradeSalary()
               : this.payrollRepository
                  .civilServantGradeSalary(after.gradeSalaryLevel(), after.positionSalaryGrade(), after.gradeSalaryStep(), after.salaryStandardYearMonth());
            int levelStartYear = this.assessmentStartYear(before.levelAssessmentStartYear(), before.positionStartYearMonth(), before.positionCode());
            int stepStartYear = this.assessmentStartYear(before.stepAssessmentStartYear(), before.positionStartYearMonth(), before.positionCode());
            int assessmentEndYear = promotionYear - 1;
            int qualifiedYearsForLevel = assessmentCache == null
               ? this.payrollRepository.countQualifiedAssessmentYears(before.organizationCode(), before.personCode(), levelStartYear, assessmentEndYear)
               : assessmentCache.countQualified(uid, levelStartYear, assessmentEndYear);
            int qualifiedYearsForStep = assessmentCache == null
               ? this.payrollRepository.countQualifiedAssessmentYears(before.organizationCode(), before.personCode(), stepStartYear, assessmentEndYear)
               : assessmentCache.countQualified(uid, stepStartYear, assessmentEndYear);
            return new com.dxsoft.rsgzgl.payroll.LevelPromotionPreview(
               uid,
               after.id(),
               after.organizationCode(),
               after.personCode(),
               after.name(),
               calculationPeriod,
               changeType,
               after.positionCode(),
               after.positionName(),
               after.salaryStandardYearMonth(),
               before.gradeSalaryLevel(),
               before.positionSalaryGrade(),
               after.gradeSalaryLevel(),
               after.positionSalaryGrade(),
               String.valueOf(levelStartYear),
               String.valueOf(stepStartYear),
               this.valueOrEmpty(after.levelAssessmentStartYear()),
               this.valueOrEmpty(after.stepAssessmentStartYear()),
               qualifiedYearsForLevel,
               qualifiedYearsForStep,
               true,
               false,
               reformRolling,
               false,
               currentGradeSalary,
               promotedGradeSalary,
               this.nullToZero(promotedGradeSalary) - this.nullToZero(currentGradeSalary),
               false,
               true,
               false,
               false,
               false,
               false,
               note,
               false,
               null
            );
         }
      }
   }

   private boolean isEarlierNormalStepPromotionPending(
      int uid,
      int promotionYear,
      int stepStartYear,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      boolean eligible,
      boolean rollbackEligible
   ) {
      if (eligible && !rollbackEligible) {
         if ("POLICE_GRADE".equals(this.baseSalarySource(history.positionCode(), history.gradeSalaryLevel()))) {
            return false;
         } else {
            int requiredYears = this.normalPromotionRequiredYears(history);
            if (requiredYears <= 0) {
               requiredYears = 2;
            }

            return this.isNormalStepPromotionDueInPriorYear(uid, promotionYear, stepStartYear, requiredYears, assessmentCache, history);
         }
      } else {
         return false;
      }
   }

   private boolean isNormalStepPromotionDueInPriorYear(
      int uid,
      int promotionYear,
      int stepStartYear,
      int requiredYears,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history
   ) {
      if (requiredYears > 0 && stepStartYear > 0 && promotionYear > 2007) {
         int priorYear = promotionYear - 1;
         if (priorYear < 2007) {
            return false;
         } else {
            int priorAssessmentEnd = priorYear - 1;
            if (priorAssessmentEnd < stepStartYear) {
               return false;
            } else {
               int priorQualifiedYears = assessmentCache == null
                  ? this.payrollRepository.countQualifiedAssessmentYears(history.organizationCode(), history.personCode(), stepStartYear, priorAssessmentEnd)
                  : assessmentCache.countQualified(uid, stepStartYear, priorAssessmentEnd);
               return priorQualifiedYears >= requiredYears;
            }
         }
      } else {
         return false;
      }
   }

   private com.dxsoft.rsgzgl.payroll.LevelPromotionPreview levelPromotionPreview(int uid) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = this.payrollRepository
         .findLatestHistory(uid)
         .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      return this.levelPromotionPreview(uid, this.yearOf(history.calculationYear()));
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache loadPositionChangePreviewCache(
      List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows
   ) {
      return this.loadPositionChangePreviewCache(candidateRows, true);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache loadPositionChangePreviewCache(
      List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows, boolean includePositionSalaries
   ) {
      if (candidateRows != null && !candidateRows.isEmpty()) {
         List<Integer> uids = candidateRows.stream().map(com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow::uid).distinct().toList();
         Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> rowsByUid = candidateRows.stream()
            .collect(
               Collectors.toMap(
                  com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow::uid,
                  row -> (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow)row,
                  (left, right) -> left,
                  LinkedHashMap::new
               )
            );
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories = this.payrollRepository.findLatestHistoriesByUids(uids);
         LinkedHashMap<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplays = new LinkedHashMap<>();
         rowsByUid.forEach(
            (uid, row) -> {
               if (row.beforePositionName() != null && !row.beforePositionName().isBlank()) {
                  processedDisplays.put(
                     uid,
                     new com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair(
                        row.beforePositionCode(), row.beforePositionName(), row.afterPositionCode(), row.afterPositionName()
                     )
                  );
               }
            }
         );
         List<Integer> missingDisplayUids = uids.stream().filter(uid -> {
            com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = processedDisplays.get(uid);
            return pair == null || pair.beforePositionName() == null || pair.beforePositionName().isBlank();
         }).toList();
         if (!missingDisplayUids.isEmpty()) {
            processedDisplays.putAll(this.payrollRepository.findProcessedPositionChangeDisplaysByUids(missingDisplayUids));
            List<String> missingDisplayHistoryIds = histories.entrySet()
               .stream()
               .filter(entry -> missingDisplayUids.contains(entry.getKey()))
               .filter(entry -> this.isPositionChangeAuditType(entry.getValue().calculationType()))
               .filter(entry -> {
                  com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = processedDisplays.get(entry.getKey());
                  return pair == null || pair.beforePositionName() == null || pair.beforePositionName().isBlank();
               })
               .map(entry -> entry.getValue().id())
               .toList();
            if (!missingDisplayHistoryIds.isEmpty()) {
               Map<String, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> byHistoryId = this.payrollRepository
                  .findProcessedPositionChangeDisplaysByHistoryIds(missingDisplayHistoryIds);
               histories.forEach((uid, history) -> {
                  com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = byHistoryId.get(history.id());
                  if (pair != null) {
                     processedDisplays.putIfAbsent(uid, pair);
                  }
               });
            }
         }

         LinkedHashMap<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> candidates = new LinkedHashMap<>();

         for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : rowsByUid.values()) {
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = histories.get(row.uid());
            String startYearMonth = this.emptyToNull(row.appointmentYearMonth());
            if (startYearMonth == null && history != null) {
               startYearMonth = history.positionStartYearMonth();
            }

            candidates.put(
               Integer.valueOf(row.uid()),
               new com.dxsoft.rsgzgl.payroll.PositionChangeCandidate(
                  row.afterPositionCode(), row.afterPositionName(), startYearMonth == null ? "" : startYearMonth
               )
            );
         }

         LinkedHashSet<String> positionCodes = new LinkedHashSet<>();
         LinkedHashSet<String> yearMonths = new LinkedHashSet<>();
         histories.values().forEach(history -> {
            yearMonths.add(history.salaryStandardYearMonth());
            positionCodes.add(history.positionCode());
         });
         rowsByUid.values().forEach(row -> {
            positionCodes.add(row.beforePositionCode());
            positionCodes.add(row.afterPositionCode());
         });
         processedDisplays.values().forEach(pair -> {
            positionCodes.add(pair.beforePositionCode());
            positionCodes.add(pair.afterPositionCode());
         });
         candidates.values().forEach(candidate -> positionCodes.add(candidate.positionCode()));
         Map<String, com.dxsoft.rsgzgl.payroll.PositionLevelRange> levelRanges = this.payrollRepository.findPositionLevelRanges(positionCodes);
         HashMap<String, Integer> positionSalaries = new HashMap<>();
         if (includePositionSalaries) {
            this.loadPositionSalariesInto(positionSalaries, yearMonths, positionCodes);
         }

         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessors = this.loadPositionChangePredecessors(histories, rowsByUid.values());
         return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache(
            this.payrollRepository, histories, processedDisplays, candidates, levelRanges, positionSalaries, rowsByUid, predecessors
         );
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository);
      }
   }

   private void fillPositionChangeSalaries(
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache, List<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> rows
   ) {
      if (cache != null && rows != null && !rows.isEmpty()) {
         LinkedHashSet<String> positionCodes = new LinkedHashSet<>();
         LinkedHashSet<String> yearMonths = new LinkedHashSet<>();

         for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : rows) {
            positionCodes.add(row.beforePositionCode());
            positionCodes.add(row.afterPositionCode());
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = cache.histories().get(row.uid());
            if (history != null) {
               yearMonths.add(history.salaryStandardYearMonth());
               positionCodes.add(history.positionCode());
               positionCodes.add(this.salaryStandardPositionCode(history.organizationCode(), row.beforePositionCode(), history.salaryStandardYearMonth()));
               positionCodes.add(this.salaryStandardPositionCode(history.organizationCode(), row.afterPositionCode(), history.salaryStandardYearMonth()));
            }
         }

         HashMap<String, Integer> salaries = new HashMap<>();
         this.loadPositionChangeStandardAmountsInto(salaries, yearMonths, positionCodes);
         cache.mergePositionSalaries(salaries);
      }
   }

   private void loadPositionChangeStandardAmountsInto(Map<String, Integer> amountCache, Collection<String> yearMonths, Collection<String> positionCodes) {
      if (amountCache != null && yearMonths != null && positionCodes != null && !positionCodes.isEmpty()) {
         for (String yearMonth : yearMonths) {
            if (yearMonth != null && !yearMonth.isBlank()) {
               this.payrollRepository
                  .findPositionSalaries(yearMonth, positionCodes)
                  .forEach(
                     (code, amount) -> amountCache.put(
                           com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.positionSalaryKey(code, yearMonth), amount
                        )
                  );
               this.payrollRepository
                  .findTechnicalGradeSalaries(yearMonth, positionCodes)
                  .forEach(
                     (code, amount) -> amountCache.put(
                           com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.technicalGradeSalaryKey(code, yearMonth), amount
                        )
                  );
            }
         }
      }
   }

   private void loadPositionSalariesInto(Map<String, Integer> positionSalaries, Collection<String> yearMonths, Collection<String> positionCodes) {
      this.loadPositionChangeStandardAmountsInto(positionSalaries, yearMonths, positionCodes);
   }

