   private com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem positionChangePromotionListItem(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      boolean listSummaryOnly,
      boolean skipPriorPromotionCheck
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = cache.requireHistory(uid);
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext trialContext = this.resolvePositionChangeTrialContext(history, uid, cache);
      if (trialContext.processed()) {
         return listSummaryOnly
            ? this.processedPositionChangeListItemSummary(history, trialContext)
            : this.processedPositionChangeListItem(history, trialContext, cache);
      } else {
         return com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem.fromPreview(
            this.positionChangePromotionPreview(uid, cache, false, false, assessmentCache, listSummaryOnly, skipPriorPromotionCheck)
         );
      }
   }

