   private com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem processedPositionChangeListItem(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext trialContext,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache
   ) {
      com.dxsoft.rsgzgl.payroll.PayrollService.ProcessedPositionChangeSalaryBreakdown breakdown = this.processedPositionChangeSalaryBreakdown(
         history, trialContext, cache, false
      );
      return new com.dxsoft.rsgzgl.payroll.PositionChangePromotionListItem(
         history.id(),
         history.organizationCode(),
         history.personCode(),
         history.name(),
         trialContext.beforePositionCode(),
         trialContext.beforePositionName(),
         trialContext.afterPositionCode(),
         trialContext.afterPositionName(),
         history.calculationType(),
         history.positionStartYearMonth(),
         this.nextMonth(history.positionStartYearMonth()),
         history.gradeSalaryLevel(),
         breakdown.beforeDisplayStep(),
         history.gradeSalaryLevel(),
         breakdown.afterDisplayStep(),
         breakdown.positionSalaryIncrease(),
         breakdown.netPositionSalaryIncrease(),
         breakdown.gradeSalaryIncrease(),
         breakdown.totalIncrease(),
         history.calculationType(),
         true,
         false,
         false
      );
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.ProcessedPositionChangeSalaryBreakdown processedPositionChangeSalaryBreakdown(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext trialContext,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache,
      boolean applyRankPgbcRetention
   ) {
      String beforePositionCode = trialContext.beforePositionCode();
      String afterPositionCode = trialContext.afterPositionCode();
      boolean institutionPositionChange = this.isInstitutionPosition(beforePositionCode) && this.isInstitutionPosition(afterPositionCode);
      Optional<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessor = cache.predecessor(history.id());
      Integer beforePositionSalary;
      Integer beforeGradeSalary;
      if (predecessor.isPresent()) {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before = predecessor.get();
         String beforeCode = this.firstNonBlank(before.positionCode(), beforePositionCode);
         beforePositionSalary = this.resolvedStoredOrPositionSalary(before, beforeCode, cache);
         beforeGradeSalary = this.resolvedStoredOrGradeSalary(before, beforeCode, institutionPositionChange);
      } else {
         beforePositionSalary = cache.positionSalary(
            this.salaryStandardPositionCode(history.organizationCode(), beforePositionCode, history.salaryStandardYearMonth()),
            history.salaryStandardYearMonth()
         );
         beforeGradeSalary = this.resolvedStoredOrGradeSalary(history, beforePositionCode, institutionPositionChange);
      }

      Integer afterPositionSalary = this.resolvedStoredOrPositionSalary(history, afterPositionCode, cache);
      Integer afterGradeSalary = this.resolvedStoredOrGradeSalary(history, afterPositionCode, institutionPositionChange);
      boolean rankConversion = this.isRankConversion(this.positionPrefix(beforePositionCode), this.positionPrefix(afterPositionCode));
      int positionSalaryIncrease = this.nullToZero(afterPositionSalary) - this.nullToZero(beforePositionSalary);
      int pgbcRetainedAmount = applyRankPgbcRetention && rankConversion && positionSalaryIncrease < 0 ? Math.abs(positionSalaryIncrease) : 0;
      int pgbcOffsetAmount = 0;
      int netPositionSalaryIncrease = positionSalaryIncrease + pgbcRetainedAmount - pgbcOffsetAmount;
      int gradeSalaryIncrease = this.nullToZero(afterGradeSalary) - this.nullToZero(beforeGradeSalary);
      String afterDisplayStep = this.positionChangeDisplayStep(history, afterPositionCode);
      String beforeDisplayStep = predecessor.<String>map(before -> this.positionChangeDisplayStep(before, beforePositionCode))
         .orElseGet(() -> this.positionChangeDisplayStep(history, beforePositionCode));
      return new com.dxsoft.rsgzgl.payroll.PayrollService.ProcessedPositionChangeSalaryBreakdown(
         beforeDisplayStep,
         afterDisplayStep,
         beforePositionSalary,
         afterPositionSalary,
         beforeGradeSalary,
         afterGradeSalary,
         positionSalaryIncrease,
         pgbcRetainedAmount,
         pgbcOffsetAmount,
         netPositionSalaryIncrease,
         gradeSalaryIncrease,
         netPositionSalaryIncrease + gradeSalaryIncrease
      );
   }

   private Integer resolvedStoredOrPositionSalary(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot snapshot, String positionCode, com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache
   ) {
      if (this.nullToZero(snapshot.storedPositionSalary()) > 0) {
         return snapshot.storedPositionSalary();
      } else {
         String standardYearMonth = snapshot.salaryStandardYearMonth();
         return cache.positionSalary(this.salaryStandardPositionCode(snapshot.organizationCode(), positionCode, standardYearMonth), standardYearMonth);
      }
   }

   private Integer resolvedStoredOrGradeSalary(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot snapshot, String positionCode, boolean institution) {
      if (this.nullToZero(snapshot.storedGradeSalary()) > 0) {
         return snapshot.storedGradeSalary();
      } else {
         String standardYearMonth = snapshot.salaryStandardYearMonth();
         return institution
            ? this.payrollRepository
               .salaryLevelSalary(
                  snapshot.positionSalaryGrade(),
                  this.firstNonBlank(snapshot.gradeSalaryStep(), "0"),
                  standardYearMonth,
                  this.salaryStandardPositionCode(snapshot.organizationCode(), positionCode, standardYearMonth)
               )
            : this.civilServantGradeSalaryAmount(
               positionCode, snapshot.gradeSalaryLevel(), snapshot.positionSalaryGrade(), snapshot.gradeSalaryStep(), standardYearMonth
            );
      }
   }

   private Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> loadPositionChangePredecessors(
      Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories,
      Collection<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows
   ) {
      if (histories != null && !histories.isEmpty()) {
         LinkedHashSet<String> historyIds = new LinkedHashSet<>();
         if (candidateRows != null) {
            for (com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row : candidateRows) {
               if (row.processed()) {
                  com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = histories.get(row.uid());
                  if (history != null && this.emptyToNull(history.id()) != null) {
                     historyIds.add(history.id().trim());
                  }
               }
            }
         }

         for (com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history : histories.values()) {
            if (history != null && this.emptyToNull(history.id()) != null && this.isPositionChangeAuditType(history.calculationType())) {
               historyIds.add(history.id().trim());
            }
         }

         return historyIds.isEmpty() ? Map.of() : this.payrollRepository.findPredecessorHistoriesByCurrentIds(historyIds);
      } else {
         return Map.of();
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache loadPositionChangePreviewCacheForUids(List<Integer> uids) {
      if (uids != null && !uids.isEmpty()) {
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories = this.payrollRepository.findLatestHistoriesByUids(uids);
         LinkedHashMap<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplays = new LinkedHashMap<>(
            this.payrollRepository.findProcessedPositionChangeDisplaysByUids(uids)
         );
         List<String> missingDisplayHistoryIds = histories.entrySet()
            .stream()
            .filter(entry -> this.isPositionChangeAuditType(entry.getValue().calculationType()))
            .filter(entry -> {
               com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = processedDisplays.get(entry.getKey());
               return pair == null || pair.beforePositionName() == null || pair.beforePositionName().isBlank();
            })
            .map(entry -> entry.getValue().id())
            .toList();
         if (!missingDisplayHistoryIds.isEmpty()) {
            Map<String, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> byHistoryId = this.payrollRepository
               .findProcessedPositionChangeDisplaysByHistoryIds(missingDisplayHistoryIds);
            histories.forEach((uid, history) -> {
               com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = byHistoryId.get(history.id());
               if (pair != null) {
                  processedDisplays.putIfAbsent(uid, pair);
               }
            });
         }

         Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> candidates = this.payrollRepository.findCurrentPositionChangeCandidatesByUids(uids);
         LinkedHashSet<String> positionCodes = new LinkedHashSet<>();
         LinkedHashSet<String> yearMonths = new LinkedHashSet<>();
         histories.values().forEach(history -> {
            yearMonths.add(history.salaryStandardYearMonth());
            positionCodes.add(history.positionCode());
         });
         processedDisplays.values().forEach(pair -> {
            positionCodes.add(pair.beforePositionCode());
            positionCodes.add(pair.afterPositionCode());
         });
         candidates.values().forEach(candidate -> positionCodes.add(candidate.positionCode()));
         Map<String, com.dxsoft.rsgzgl.payroll.PositionLevelRange> levelRanges = this.payrollRepository.findPositionLevelRanges(positionCodes);
         HashMap<String, Integer> positionSalaries = new HashMap<>();

         for (String yearMonth : yearMonths) {
            if (yearMonth != null && !yearMonth.isBlank()) {
               this.payrollRepository
                  .findPositionSalaries(yearMonth, positionCodes)
                  .forEach(
                     (code, amount) -> positionSalaries.put(
                           com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.positionSalaryKey(code, yearMonth), amount
                        )
                  );
            }
         }

         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessors = this.loadPositionChangePredecessors(histories, List.of());
         return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache(
            this.payrollRepository, histories, processedDisplays, candidates, levelRanges, positionSalaries, Map.of(), predecessors
         );
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository);
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext resolvePositionChangeTrialContext(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, int uid, com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache
   ) {
      Optional<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> sqlRow = cache.candidateRow(uid);
      if (sqlRow.isPresent()) {
         com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow row = sqlRow.get();
         if (row.beforePositionName() != null && !row.beforePositionName().isBlank()) {
            com.dxsoft.rsgzgl.payroll.PositionChangeCandidate appointment = cache.appointmentCandidate(uid, history);
            return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext(
               row.beforePositionCode(), row.beforePositionName(), row.afterPositionCode(), row.afterPositionName(), appointment, row.processed()
            );
         }
      }

      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate appointment = cache.appointmentCandidate(uid, history);
      if (!this.isPositionChangeAuditType(history.calculationType())) {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext(
            history.positionCode(), history.positionName(), appointment.positionCode(), appointment.positionName(), appointment, false
         );
      } else {
         Optional<com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplay = cache.processedDisplay(uid, history);
         if (processedDisplay.isEmpty()) {
            processedDisplay = cache.processedDisplayById(uid, history.id());
         }

         if (processedDisplay.isPresent() && processedDisplay.get().beforePositionName() != null && !processedDisplay.get().beforePositionName().isBlank()) {
            com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair pair = processedDisplay.get();
            return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext(
               pair.beforePositionCode(), pair.beforePositionName(), pair.afterPositionCode(), pair.afterPositionName(), appointment, true
            );
         } else {
            String beforeCode = history.positionCode();
            String beforeName = history.positionName();
            Optional<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessor = cache.predecessor(history.id());
            if (predecessor.isEmpty()) {
               String organizationCode = this.emptyToNull(history.organizationCode());
               String personCode = this.emptyToNull(history.personCode());
               Optional<String> predecessorId = organizationCode != null && personCode != null
                  ? this.payrollRepository.findPredecessorHistoryId(organizationCode, personCode, history.id())
                  : this.payrollRepository.findPredecessorHistoryId(history.id());
               predecessor = predecessorId.flatMap(this.payrollRepository::findPayrollHistoryById);
            }

            if (predecessor.isEmpty()) {
               predecessor = this.payrollRepository.findPositionChangePredecessor(history.id());
            }

            if (predecessor.isPresent()) {
               beforeCode = predecessor.get().positionCode();
               beforeName = predecessor.get().positionName();
            } else {
               Optional<Map<String, Object>> predecessorValues = this.payrollRepository.findPredecessorHistoryValues(history.id());
               if (predecessorValues.isPresent()) {
                  beforeCode = this.textValue(predecessorValues.get(), "zwbm2");
                  beforeName = this.textValue(predecessorValues.get(), "zwgw2");
               } else {
                  Optional<com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> priorAppointment = this.payrollRepository
                     .findPreviousDistinctAppointment(
                        history.organizationCode(), history.personCode(), history.positionCode(), history.calculationYear() + history.calculationMonth()
                     );
                  if (priorAppointment.isPresent()) {
                     beforeCode = priorAppointment.get().positionCode();
                     beforeName = priorAppointment.get().positionName();
                  }
               }
            }

            String afterCode = history.positionCode();
            String afterName = history.positionName();
            return Objects.equals(beforeCode, afterCode)
                  && !Objects.equals(appointment.positionCode(), history.positionCode())
                  && !this.isPositionChangeAuditType(history.calculationType())
               ? new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext(
                  history.positionCode(), history.positionName(), appointment.positionCode(), appointment.positionName(), appointment, false
               )
               : new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext(beforeCode, beforeName, afterCode, afterName, appointment, true);
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PositionChangePromotionPreview processedPositionChangePromotionPreview(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangeTrialContext trialContext,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache,
      boolean includeExplanation,
      boolean includeNote
   ) {
      String beforePositionCode = trialContext.beforePositionCode();
      String beforePositionName = trialContext.beforePositionName();
      String afterPositionCode = trialContext.afterPositionCode();
      String afterPositionName = trialContext.afterPositionName();
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate = new com.dxsoft.rsgzgl.payroll.PositionChangeCandidate(
         afterPositionCode, afterPositionName, history.positionStartYearMonth()
      );
      com.dxsoft.rsgzgl.payroll.PositionLevelRange levelRange = cache.levelRange(afterPositionCode).orElse(null);
      String currentPositionPrefix = this.positionPrefix(beforePositionCode);
      String newPositionPrefix = this.positionPrefix(afterPositionCode);
      boolean sequenceConversion = this.isSequenceConversion(currentPositionPrefix, newPositionPrefix);
      boolean policeOfficerConversion = this.isPoliceOfficerConversion(currentPositionPrefix, newPositionPrefix);
      boolean judicialConversion = this.isJudicialConversion(currentPositionPrefix, newPositionPrefix);
      boolean rankConversion = this.isRankConversion(currentPositionPrefix, newPositionPrefix);
      boolean rankHighPositionPromotion = rankConversion && this.isHigherPositionLayer(beforePositionCode, afterPositionCode);
      boolean institutionPositionChange = this.isInstitutionPosition(currentPositionPrefix) && this.isInstitutionPosition(newPositionPrefix);
      boolean policeToAdministrativeConversion = this.isPoliceToAdministrativeConversion(currentPositionPrefix, newPositionPrefix);
      String lastPayrollChangeType;
      String changeType = lastPayrollChangeType = history.calculationType();
      com.dxsoft.rsgzgl.payroll.PayrollService.ProcessedPositionChangeSalaryBreakdown breakdown = this.processedPositionChangeSalaryBreakdown(
         history, trialContext, cache, rankConversion
      );
      Optional<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessor = cache.predecessor(history.id());
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot beforeSnapshot = predecessor.orElse(history);
      String currentStep = breakdown.beforeDisplayStep();
      String promotedStep = breakdown.afterDisplayStep();
      String currentLevel = beforeSnapshot.gradeSalaryLevel();
      String promotedLevel = history.gradeSalaryLevel();
      Integer currentPositionSalary = breakdown.beforePositionSalary();
      Integer newPositionSalary = breakdown.afterPositionSalary();
      Integer currentGradeSalary = breakdown.beforeGradeSalary();
      Integer promotedGradeSalary = breakdown.afterGradeSalary();
      int positionSalaryIncrease = breakdown.positionSalaryIncrease();
      int pgbcRetainedAmount = breakdown.pgbcRetainedAmount();
      int pgbcOffsetAmount = breakdown.pgbcOffsetAmount();
      int netPositionSalaryIncrease = breakdown.netPositionSalaryIncrease();
      int gradeSalaryIncrease = breakdown.gradeSalaryIncrease();
      boolean rollbackEligible = true;
      boolean applyEligible = false;
      boolean eligible = false;
      String note = includeNote
         ? "当前最近工资变动为「"
            + lastPayrollChangeType
            + "」，可执行还原；"
            + this.positionChangePromotionNote(
               history,
               candidate,
               levelRange,
               eligible,
               0,
               false,
               sequenceConversion,
               policeOfficerConversion,
               judicialConversion,
               rankConversion,
               null,
               null,
               null,
               null,
               null,
               null,
               true
            )
         : "";
      List<String> explanationLines = includeExplanation
         ? this.positionChangeExplanationLines(
            history,
            beforePositionCode,
            beforePositionName,
            afterPositionCode,
            afterPositionName,
            candidate.startYearMonth(),
            changeType,
            currentStep,
            levelRange,
            null,
            null,
            null,
            null,
            null,
            promotedLevel,
            promotedStep,
            beforeSnapshot.levelAssessmentStartYear(),
            beforeSnapshot.stepAssessmentStartYear(),
            positionSalaryIncrease,
            pgbcRetainedAmount,
            pgbcOffsetAmount,
            netPositionSalaryIncrease,
            gradeSalaryIncrease,
            0,
            0,
            0,
            false,
            note
         )
         : List.of();
      return new com.dxsoft.rsgzgl.payroll.PositionChangePromotionPreview(
         history.id(),
         history.organizationCode(),
         history.personCode(),
         history.name(),
         beforePositionCode,
         beforePositionName,
         afterPositionCode,
         afterPositionName,
         currentPositionPrefix,
         newPositionPrefix,
         sequenceConversion,
         policeOfficerConversion,
         judicialConversion,
         rankConversion,
         rankHighPositionPromotion,
         institutionPositionChange,
         null,
         null,
         null,
         changeType,
         candidate.startYearMonth(),
         this.nextMonth(candidate.startYearMonth()),
         history.salaryStandardYearMonth(),
         currentLevel,
         currentStep,
         levelRange == null ? null : String.valueOf(levelRange.minimumLevel()),
         levelRange == null ? null : String.valueOf(levelRange.maximumLevel()),
         null,
         null,
         null,
         null,
         policeToAdministrativeConversion,
         null,
         null,
         null,
         null,
         promotedLevel,
         promotedStep,
         currentPositionSalary,
         newPositionSalary,
         currentGradeSalary,
         promotedGradeSalary,
         positionSalaryIncrease,
         pgbcRetainedAmount,
         pgbcOffsetAmount,
         netPositionSalaryIncrease,
         gradeSalaryIncrease,
         netPositionSalaryIncrease + gradeSalaryIncrease,
         beforeSnapshot.levelAssessmentStartYear(),
         beforeSnapshot.stepAssessmentStartYear(),
         history.levelAssessmentStartYear(),
         history.stepAssessmentStartYear(),
         false,
         lastPayrollChangeType,
         rollbackEligible,
         applyEligible,
         eligible,
         note,
         explanationLines,
         includeExplanation ? this.positionChangeSalaryComponents(history, true, afterPositionCode, null, null, null, null, null, null, 0) : List.of()
      );
   }

   private com.dxsoft.rsgzgl.payroll.PositionChangePromotionPreview positionChangePromotionPreview(int uid) {
      return this.positionChangePromotionPreview(uid, this.loadPositionChangePreviewCacheForUids(List.of(uid)), true, true);
   }

