   private List<com.dxsoft.rsgzgl.payroll.PayrollChangeComponentComparison> detailSalaryComponentsFromSnapshots(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot before, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot after
   ) {
      Map<String, Object> beforeValues = this.salaryAmountValuesForDetail(before);
      Map<String, Object> afterValues = this.salaryAmountValuesForDetail(after);
      String positionCode = after != null ? after.positionCode() : (before == null ? null : before.positionCode());
      String organizationType = after != null ? after.organizationType() : (before == null ? null : before.organizationType());
      return this.detailSalaryComponentComparisons(beforeValues, afterValues, positionCode, organizationType);
   }

