   private String salaryExecutionPeriodForPersonnelDetermination(String joinYearMonth, String changeType) {
      String join = this.normalizeYearMonth(joinYearMonth);
      if (join.length() != 6) {
         return "";
      } else if ("见习工资".equals(changeType)) {
         return join;
      } else if (NEW_PERSONNEL_DETERMINED_CHANGE_TYPES.contains(changeType)) {
         String next = this.nextMonth(join);
         return next.length() == 6 ? next : join;
      } else {
         return "";
      }
   }

