   private String resolveRegularizationApplyPeriod(
      com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates dates, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, boolean nonInternProbationPath
   ) {
      String fromEntryPlusOneYear;
      if (nonInternProbationPath && (fromEntryPlusOneYear = this.plusOneYear(dates.unitEntryYearMonth())).length() == 6) {
         return fromEntryPlusOneYear;
      } else {
         String fromZz = this.normalizeYearMonth(dates.regularizationYearMonth());
         String fromHistory = this.normalizeYearMonth(history.calculationYear() + history.calculationMonth());
         if (fromZz.length() != 6 || fromHistory.length() >= 6 && fromZz.compareTo(fromHistory) < 0) {
            if (fromHistory.length() == 6) {
               return fromHistory;
            } else {
               throw new IllegalArgumentException("无法确定转正定级执行年月。");
            }
         } else {
            return fromZz;
         }
      }
   }

