   private boolean isWithinCivilInternPeriod(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      Map<String, com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates> regularizationDatesByOrgPerson
   ) {
      if (history == null) {
         return false;
      } else if (this.isProbationAppointment(history.positionCode(), history.positionName())) {
         return true;
      } else {
         String org = this.emptyToNull(history.organizationCode());
         String person = this.emptyToNull(history.personCode());
         String tc = null;
         if (org != null && person != null && regularizationDatesByOrgPerson != null) {
            com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates dates = regularizationDatesByOrgPerson.get(this.orgPersonKey(org, person));
            tc = dates == null ? null : dates.classificationTag();
         }

         if (tc == null && org != null && person != null) {
            tc = this.payrollRepository
               .findPersonnelRegularizationDates(org, person)
               .map(com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates::classificationTag)
               .orElse(null);
         }

         return "新增见习".equals(this.emptyToNull(tc));
      }
   }

   private boolean isWithinCivilInternPeriod(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, Integer uid, com.dxsoft.rsgzgl.payroll.PayrollService.EducationPromotionBatchContext context
   ) {
      if (history == null) {
         return false;
      } else if (this.isProbationAppointment(history.positionCode(), history.positionName())) {
         return true;
      } else {
         String tc;
         if (context != null && uid != null) {
            com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates dates = context.dates().get(uid);
            tc = dates == null ? null : dates.classificationTag();
         } else {
            tc = this.payrollRepository
               .findPersonnelRegularizationDates(history.organizationCode(), history.personCode())
               .map(com.dxsoft.rsgzgl.payroll.PersonnelRegularizationDates::classificationTag)
               .orElse(null);
         }

         return "新增见习".equals(this.emptyToNull(tc));
      }
   }

