   private com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationSalaryPosition resolveRegularizationSalaryPosition(
      String organizationCode,
      String personCode,
      String regularizationPeriod,
      String fallbackPositionCode,
      String educationLookupPeriod,
      boolean forceAdministrativeRegularizationLookup,
      com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationBatchContext context,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot personnelContext
   ) {
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate appointed = this.findRegularizationAppointedPosition(
            organizationCode, personCode, regularizationPeriod, true, context
         )
         .orElse(null);
      com.dxsoft.rsgzgl.payroll.EducationPromotionSource education = this.findEducationForRegularization(
         organizationCode, personCode, regularizationPeriod, educationLookupPeriod, context
      );
      String standardLookupCode = this.resolveRegularizationStandardLookupCode(
         personnelContext, fallbackPositionCode, appointed, forceAdministrativeRegularizationLookup
      );
      com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard = this.findEducationRegularizationStandard(standardLookupCode, education, context);
      if (this.isRegularizationAppointedPosition(appointed) && this.isInstitutionPosition(appointed.positionCode())) {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationSalaryPosition(
            standard, appointed, appointed.positionCode(), appointed.positionName(), true, false
         );
      } else if (standard == null) {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationSalaryPosition(null, appointed, null, null, false, false);
      } else {
         boolean salaryPositionFromStandard = !this.isRegularizationAppointedPosition(appointed);
         String salaryPositionCode = salaryPositionFromStandard
            ? this.normalizeEducationPromotionPositionCode(standard.positionCode())
            : appointed.positionCode();
         String salaryPositionName = salaryPositionFromStandard ? standard.positionName() : appointed.positionName();
         return new com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationSalaryPosition(
            standard, appointed, salaryPositionCode, salaryPositionName, false, salaryPositionFromStandard
         );
      }
   }

   private String resolveRegularizationStandardLookupCode(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot personnelContext,
      String fallbackPositionCode,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate appointed,
      boolean forceAdministrativeRegularizationLookup
   ) {
      if (this.isRegularizationAppointedPosition(appointed) && this.isInstitutionPosition(appointed.positionCode())) {
         return appointed.positionCode();
      } else if (!forceAdministrativeRegularizationLookup
         || this.isRegularizationAppointedPosition(appointed)
         || personnelContext != null && this.isGovernmentWorkerPersonnel(personnelContext)) {
         if (personnelContext != null && this.isGovernmentWorkerPersonnel(personnelContext) && !this.isRegularizationAppointedPosition(appointed)) {
            String workerLookupPosition = this.governmentWorkerRegularizationLookupPosition(personnelContext);
            if (workerLookupPosition != null) {
               return workerLookupPosition;
            }
         }

         return fallbackPositionCode;
      } else {
         return "01B0";
      }
   }

   private String governmentWorkerOrganizationPrefix(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest) {
      if (latest == null) {
         return null;
      } else {
         String organizationType = this.emptyToNull(latest.organizationType());
         if (this.isGovernmentWorkerOrganizationType(organizationType)) {
            return organizationType.trim();
         } else {
            return this.isGovernmentWorkerPosition(latest.positionCode()) ? latest.positionCode().substring(0, 2) : null;
         }
      }
   }

   private String governmentWorkerRegularizationLookupPosition(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest) {
      String prefix = this.governmentWorkerOrganizationPrefix(latest);
      if (prefix == null) {
         return null;
      } else {
         return switch (prefix) {
            case "05", "08" -> prefix + "05";
            case "06", "09" -> prefix + "01";
            default -> prefix + "05";
         };
      }
   }

   private String educationPositionSuffix(String educationName) {
      String normalized = this.emptyToNull(educationName);
      if (normalized == null) {
         return "5";
      } else if (this.educationNameMatches(normalized, "博士学位研究生毕业")) {
         return "1";
      } else if (this.educationNameMatches(normalized, "硕士学位研究生毕业")) {
         return "2";
      } else if (this.educationNameMatches(normalized, "研究生班毕业", "无学位研究生", "研究生结业", "研究生轄业", "双学士学位大学本科", "6年制以上大学毕业")) {
         return "3";
      } else if (this.educationNameMatches(normalized, "大学本科毕业", "大学本科结业", "相当大学毕业", "大学轄业", "大普")) {
         return "4";
      } else {
         return this.educationNameMatches(normalized, "大专毕业", "大专结业", "相当大专毕业", "大专轄业", "高中毕业") ? "5" : "5";
      }
   }

   private boolean educationNameMatches(String educationName, String... candidates) {
      for (String candidate : candidates) {
         if (educationName.equals(candidate)) {
            return true;
         }
      }

      return false;
   }

   private String organizationSalaryPrefix(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest) {
      if (latest == null) {
         return "01";
      } else {
         String workerPrefix = this.governmentWorkerOrganizationPrefix(latest);
         if (workerPrefix != null) {
            return workerPrefix;
         } else {
            String organizationType = this.emptyToNull(latest.organizationType());
            if (organizationType != null && organizationType.length() >= 2) {
               return organizationType.substring(0, 2);
            } else {
               String positionCode = this.emptyToNull(latest.positionCode());
               return positionCode != null && positionCode.length() >= 2 ? positionCode.substring(0, 2) : "01";
            }
         }
      }
   }

