   private String normalizeInternProbationPositionCode(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest, String positionCode, String educationName) {
      String normalized = this.emptyToNull(positionCode);
      if (normalized != null && this.isInternSalaryPosition(normalized)) {
         return normalized.length() >= 4 && "FF".equalsIgnoreCase(normalized.substring(2, 4))
            ? this.internProbationPositionCode(latest, educationName)
            : normalized;
      } else {
         return positionCode;
      }
   }

