   private com.dxsoft.rsgzgl.payroll.EducationPromotionSource findEducationForRegularization(
      String organizationCode,
      String personCode,
      String regularizationPeriod,
      String educationLookupPeriod,
      Map<String, List<com.dxsoft.rsgzgl.payroll.EducationPromotionSource>> educationsByOrgPerson,
      com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationBatchContext context
   ) {
      LinkedHashSet<String> periods = new LinkedHashSet<>();
      String normalizedRegularization = this.normalizeYearMonth(regularizationPeriod);
      String normalizedLookup = this.normalizeYearMonth(educationLookupPeriod);
      if (!normalizedRegularization.isBlank()) {
         periods.add(normalizedRegularization);
      }

      if (!normalizedLookup.isBlank()) {
         periods.add(normalizedLookup);
      }

      periods.add("200607");
      List<com.dxsoft.rsgzgl.payroll.EducationPromotionSource> cached = educationsByOrgPerson == null
         ? (context == null ? null : context.educations().get(organizationCode + "|" + personCode))
         : educationsByOrgPerson.get(organizationCode + "|" + personCode);

      for (String period : periods) {
         if (cached != null) {
            com.dxsoft.rsgzgl.payroll.EducationPromotionSource picked = this.pickEducationAtOrBefore(cached, period);
            if (picked != null) {
               return picked;
            }
         } else {
            Optional<com.dxsoft.rsgzgl.payroll.EducationPromotionSource> education = this.payrollRepository
               .findLatestEducationForPromotion(organizationCode, personCode, period);
            if (education.isPresent()) {
               return education.get();
            }
         }
      }

      return context == null && educationsByOrgPerson == null
         ? this.payrollRepository
            .findPersonnelEducationCode(organizationCode, personCode)
            .filter(code -> !code.isBlank())
            .map(code -> new com.dxsoft.rsgzgl.payroll.EducationPromotionSource(code, null, null))
            .orElse(null)
         : null;
   }

   private com.dxsoft.rsgzgl.payroll.EducationPromotionSource pickEducationAtOrBefore(
      List<com.dxsoft.rsgzgl.payroll.EducationPromotionSource> educations, String period
   ) {
      if (educations != null && !educations.isEmpty() && period != null && period.length() == 6) {
         com.dxsoft.rsgzgl.payroll.EducationPromotionSource best = null;

         for (com.dxsoft.rsgzgl.payroll.EducationPromotionSource education : educations) {
            String graduation = this.normalizeYearMonth(education.graduationDate());
            if (graduation.length() == 6 && graduation.compareTo(period) <= 0) {
               if (best == null) {
                  best = education;
               } else {
                  String bestCode = this.valueOrEmpty(best.educationCode());
                  String code = this.valueOrEmpty(education.educationCode());
                  int codeCompare = code.compareTo(bestCode);
                  if (codeCompare < 0) {
                     best = education;
                  } else if (codeCompare == 0 && graduation.compareTo(this.normalizeYearMonth(best.graduationDate())) > 0) {
                     best = education;
                  }
               }
            }
         }

         return best;
      } else {
         return null;
      }
   }

   private com.dxsoft.rsgzgl.payroll.EducationPromotionSource pickEducationAfterPeriod(
      List<com.dxsoft.rsgzgl.payroll.EducationPromotionSource> educations, String tipPeriod
   ) {
      if (educations != null && !educations.isEmpty() && tipPeriod != null && tipPeriod.length() == 6) {
         com.dxsoft.rsgzgl.payroll.EducationPromotionSource best = null;

         for (com.dxsoft.rsgzgl.payroll.EducationPromotionSource education : educations) {
            String graduation = this.normalizeYearMonth(education.graduationDate());
            if (graduation.length() == 6 && graduation.compareTo(tipPeriod) > 0) {
               if (best == null) {
                  best = education;
               } else {
                  String bestCode = this.valueOrEmpty(best.educationCode());
                  String code = this.valueOrEmpty(education.educationCode());
                  int codeCompare = code.compareTo(bestCode);
                  if (codeCompare < 0) {
                     best = education;
                  } else if (codeCompare == 0 && graduation.compareTo(this.normalizeYearMonth(best.graduationDate())) > 0) {
                     best = education;
                  }
               }
            }
         }

         return best;
      } else {
         return null;
      }
   }

