   private String educationPromotionLevel(String currentLevel, com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard) {
      int standardLevel = this.payrollRepository.intValue(standard.gradeLevel());
      int level = this.payrollRepository.intValue(currentLevel);
      return standardLevel > 0 && level > 0 && standardLevel < level ? standard.gradeLevel() : currentLevel;
   }

   private String educationPromotionGradeStep(
      String positionCode,
      String currentLevel,
      String currentGradeStep,
      String currentGradeStepDifference,
      com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard,
      String promotedLevel,
      String salaryStandardYearMonth
   ) {
      return this.educationPromotionGradeStep(
         positionCode, currentLevel, currentGradeStep, currentGradeStepDifference, standard, promotedLevel, salaryStandardYearMonth, null
      );
   }

   private String educationPromotionGradeStep(
      String positionCode,
      String currentLevel,
      String currentGradeStep,
      String currentGradeStepDifference,
      com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard,
      String promotedLevel,
      String salaryStandardYearMonth,
      com.dxsoft.rsgzgl.payroll.PayrollService.EducationPromotionBatchContext context
   ) {
      int standardLevel = this.payrollRepository.intValue(standard.gradeLevel());
      int level = this.payrollRepository.intValue(currentLevel);
      int standardStep = this.payrollRepository.intValue(standard.gradeStep());
      int currentSalary = this.nullToZero(
         this.educationPromotionGradeSalaryAmount(
            null, positionCode, currentLevel, currentGradeStep, currentGradeStepDifference, salaryStandardYearMonth, false, context
         )
      );
      int standardSalary = this.nullToZero(
         this.educationPromotionGradeSalaryAmount(null, positionCode, standard.gradeLevel(), standard.gradeStep(), "0", salaryStandardYearMonth, false, context)
      );
      if (standardLevel > 0 && level > 0 && standardLevel < level) {
         return standardSalary >= currentSalary
            ? standard.gradeStep()
            : this.firstHigherGradeStep(standard.gradeLevel(), currentSalary, salaryStandardYearMonth);
      } else if (standardLevel == level) {
         return standardSalary > currentSalary
            ? standard.gradeStep()
            : String.valueOf(Math.max(standardStep, this.payrollRepository.intValue(currentGradeStep)));
      } else {
         return standardSalary > currentSalary ? this.firstHigherGradeStep(promotedLevel, standardSalary, salaryStandardYearMonth) : currentGradeStep;
      }
   }

   private String normalizeEducationPromotionPositionCode(String positionCode) {
      return positionCode != null && positionCode.startsWith("07") && positionCode.length() >= 4 && "0".equals(positionCode.substring(3, 4))
         ? "070" + positionCode.substring(2, 3)
         : positionCode;
   }

   private boolean gradeIncreaseExceedsStepDifference(String currentLevel, String currentStep, String promotedLevel, String standardYearMonth) {
      return this.gradeIncreaseExceedsStepDifference(null, currentLevel, currentStep, promotedLevel, standardYearMonth);
   }

   private boolean gradeIncreaseExceedsStepDifference(
      String positionCode, String currentLevel, String currentStep, String promotedLevel, String standardYearMonth
   ) {
      return "POLICE_GRADE".equals(this.baseSalarySource(positionCode, currentLevel))
         ? this.policeGradeIncreaseExceedsStepDifference(currentLevel, currentStep, promotedLevel, standardYearMonth)
         : this.gradeIncreaseExceedsStepDifference(currentLevel, currentStep, "0", promotedLevel, null, "0", standardYearMonth);
   }

   private boolean policeGradeIncreaseExceedsStepDifference(String currentLevel, String currentStep, String promotedLevel, String standardYearMonth) {
      int sourceLevel = this.payrollRepository.intValue(currentLevel);
      int targetLevel = this.payrollRepository.intValue(promotedLevel);
      if (sourceLevel > 0 && targetLevel > 0 && sourceLevel > targetLevel) {
         String previousStep = currentStep;
         int previousSalary = this.payrollRepository
            .policeOfficerGradeSalary(String.valueOf(sourceLevel), this.policeGradeStep(currentStep, "0"), standardYearMonth);

         for (int level = sourceLevel - 1; level >= targetLevel; level--) {
            String nextLevel = String.valueOf(level);
            String nextStep = this.firstHigherPoliceGradeStep(String.valueOf(level + 1), previousStep, nextLevel, standardYearMonth);
            int nextSalary = this.payrollRepository.policeOfficerGradeSalary(nextLevel, nextStep, standardYearMonth);
            int increase = nextSalary - previousSalary;
            int oneStepDifference = this.policeGradeStepDifference(nextLevel, nextStep, standardYearMonth);
            if (increase > oneStepDifference) {
               return true;
            }

            previousSalary = nextSalary;
            previousStep = nextStep;
         }

         return false;
      } else {
         return false;
      }
   }

   private int policeGradeStepDifference(String gradeLevel, String gradeStep, String standardYearMonth) {
      int step = this.payrollRepository.intValue(gradeStep);
      if (step > 1) {
         int current = this.payrollRepository.policeOfficerGradeSalary(gradeLevel, String.valueOf(step), standardYearMonth);
         int previous = this.payrollRepository.policeOfficerGradeSalary(gradeLevel, String.valueOf(step - 1), standardYearMonth);
         return Math.max(0, current - previous);
      } else {
         int current = this.payrollRepository.policeOfficerGradeSalary(gradeLevel, "1", standardYearMonth);
         int next = this.payrollRepository.policeOfficerGradeSalary(gradeLevel, "2", standardYearMonth);
         return Math.max(0, next - current);
      }
   }

   private int levelPromotionGradeSalary(String positionCode, String level, String step, String stepDifference, String standardYearMonth) {
      return "POLICE_GRADE".equals(this.baseSalarySource(positionCode, level))
         ? this.payrollRepository.policeOfficerGradeSalary(level, this.policeGradeStep(step, stepDifference), standardYearMonth)
         : this.payrollRepository.civilServantGradeSalary(level, step, stepDifference, standardYearMonth);
   }

   private boolean gradeIncreaseExceedsStepDifference(
      String currentLevel,
      String currentStep,
      String currentGradeStepDifference,
      String promotedLevel,
      String promotedGradeStep,
      String promotedGradeStepDifference,
      String standardYearMonth
   ) {
      int sourceLevel = this.payrollRepository.intValue(currentLevel);
      int targetLevel = this.payrollRepository.intValue(promotedLevel);
      if (sourceLevel > 0 && targetLevel > 0 && sourceLevel > targetLevel) {
         String previousStepDifference = blankToZero(currentGradeStepDifference);
         int previousSalary = this.payrollRepository
            .civilServantGradeSalary(String.valueOf(sourceLevel), currentStep, previousStepDifference, standardYearMonth);

         for (int level = sourceLevel - 1; level >= targetLevel; level--) {
            String nextLevel = String.valueOf(level);
            com.dxsoft.rsgzgl.payroll.PayrollRepository var10000 = this.payrollRepository;
            String var10002 = level == targetLevel && promotedGradeStep != null && !promotedGradeStep.isBlank()
               ? promotedGradeStep
               : this.firstHigherGradeStep(nextLevel, previousSalary, standardYearMonth);
            String nextStep = var10002;
            int nextSalary = var10000.civilServantGradeSalary(
               nextLevel, var10002, level == targetLevel ? blankToZero(promotedGradeStepDifference) : "0", standardYearMonth
            );
            int increase = nextSalary - previousSalary;
            if (increase > this.gradeStepDifference(nextLevel, nextStep, standardYearMonth)) {
               return true;
            }

            previousSalary = nextSalary;
         }

         return false;
      } else {
         return false;
      }
   }

   private static String blankToZero(String value) {
      return value != null && !value.isBlank() ? value.trim() : "0";
   }

   private int gradeStepDifference(String level, String step, String standardYearMonth) {
      int stepValue = this.payrollRepository.intValue(step);
      if (stepValue > 1) {
         int current = this.payrollRepository.gradeSalary(level, String.valueOf(stepValue), standardYearMonth);
         int previous = this.payrollRepository.gradeSalary(level, String.valueOf(stepValue - 1), standardYearMonth);
         return Math.max(0, current - previous);
      } else {
         int current = this.payrollRepository.gradeSalary(level, "1", standardYearMonth);
         int next = this.payrollRepository.gradeSalary(level, "2", standardYearMonth);
         return Math.max(0, next - current);
      }
   }

   private String lowerGradeStepByLevel(String currentLevel, String currentStep, String demotedLevel, String standardYearMonth) {
      return this.lowerGradeStepByLevel(
         this.payrollRepository.intValue(currentLevel), currentStep, this.payrollRepository.intValue(demotedLevel), standardYearMonth
      );
   }

   private String lowerGradeStepByLevel(int currentLevel, String currentStep, int demotedLevel, String standardYearMonth) {
      int previousSalary = this.payrollRepository.gradeSalary(String.valueOf(currentLevel), currentStep, standardYearMonth);

      for (int level = currentLevel + 1; level <= demotedLevel; level++) {
         String nextStep = this.nearestLowerGradeStep(String.valueOf(level), previousSalary, standardYearMonth);
         previousSalary = this.payrollRepository.gradeSalary(String.valueOf(level), nextStep, standardYearMonth);
      }

      return currentLevel < demotedLevel ? this.nearestLowerGradeStep(String.valueOf(demotedLevel), previousSalary, standardYearMonth) : currentStep;
   }

   private String nearestLowerGradeStep(String level, Integer currentGradeSalary, String standardYearMonth) {
      String selectedStep = "1";

      for (int step = 1;
         step <= 20 && this.payrollRepository.gradeSalary(level, String.valueOf(step), standardYearMonth) <= this.nullToZero(currentGradeSalary);
         step++
      ) {
         selectedStep = String.valueOf(step);
      }

      return selectedStep;
   }

   private boolean isCivilServantForPositionChange(String positionCode) {
      return positionCode != null && positionCode.length() >= 2
         ? Set.of("01", "02", "04", "21", "22", "23", "24", "25", "26", "27", "28").contains(positionCode.substring(0, 2))
         : false;
   }

   private boolean hasPendingPositionChange(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      return this.isPositionChangeAuditType(history.calculationType())
         ? false
         : this.payrollRepository.findCurrentPositionChangeCandidate(history.organizationCode(), history.personCode()).isPresent();
   }

   private String positionPrefix(String positionCode) {
      return positionCode != null && positionCode.length() >= 2 ? positionCode.substring(0, 2) : "";
   }

   private boolean isSequenceConversion(String currentPositionPrefix, String newPositionPrefix) {
      if (POLICE_OFFICER_CONVERSION_TARGET_PREFIXES.contains(currentPositionPrefix) && POLICE_OFFICER_CONVERSION_TARGET_PREFIXES.contains(newPositionPrefix)) {
         return false;
      } else {
         return "01".equals(currentPositionPrefix) && "02".equals(newPositionPrefix)
            ? false
            : POSITION_SEQUENCE_PREFIXES.contains(currentPositionPrefix)
               && POSITION_SEQUENCE_PREFIXES.contains(newPositionPrefix)
               && !currentPositionPrefix.equals(newPositionPrefix);
      }
   }

   private boolean isPoliceOfficerConversion(String currentPositionPrefix, String newPositionPrefix) {
      return POLICE_OFFICER_CONVERSION_SOURCE_PREFIXES.contains(currentPositionPrefix) && POLICE_OFFICER_CONVERSION_TARGET_PREFIXES.contains(newPositionPrefix);
   }

   private boolean isLegacyPolicePositionConversion(String currentPositionPrefix, String newPositionPrefix) {
      return "01".equals(currentPositionPrefix) && "02".equals(newPositionPrefix);
   }

   private boolean isJudicialConversion(String currentPositionPrefix, String newPositionPrefix) {
      return POLICE_OFFICER_CONVERSION_SOURCE_PREFIXES.contains(currentPositionPrefix) && JUDICIAL_CONVERSION_TARGET_PREFIXES.contains(newPositionPrefix);
   }

   private boolean isRankConversion(String currentPositionPrefix, String newPositionPrefix) {
      return "01".equals(currentPositionPrefix)
         && POSITION_SEQUENCE_PREFIXES.contains(newPositionPrefix)
         && !Set.of("01", "02", "03", "21", "22").contains(newPositionPrefix);
   }

   private boolean isPoliceToAdministrativeConversion(String currentPositionPrefix, String newPositionPrefix) {
      return POLICE_OFFICER_CONVERSION_TARGET_PREFIXES.contains(currentPositionPrefix) && POLICE_OFFICER_CONVERSION_SOURCE_PREFIXES.contains(newPositionPrefix);
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult rankConversionResult(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange targetLevelRange,
      int currentLevel,
      String currentStep,
      Integer currentGradeSalary,
      boolean highPositionPromotion,
      com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache
   ) {
      if (targetLevelRange != null && currentLevel > 0 && this.payrollRepository.intValue(currentStep) > 0) {
         String promotedLevel = currentLevel > targetLevelRange.minimumLevel()
            ? String.valueOf(targetLevelRange.minimumLevel())
            : (highPositionPromotion ? String.valueOf(Math.max(1, currentLevel - 1)) : String.valueOf(currentLevel));
         String promotedStep = currentStep;
         if (!promotedLevel.equals(String.valueOf(currentLevel))) {
            promotedStep = this.firstHigherGradeStepForPosition(
               candidate.positionCode(),
               promotedLevel,
               currentGradeSalary,
               String.valueOf(currentLevel),
               currentStep,
               "0",
               history.salaryStandardYearMonth(),
               cache
            );
         }

         return new com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult(
            true,
            promotedLevel,
            promotedStep,
            this.positionChangeGradeSalaryAmount(candidate.positionCode(), promotedLevel, promotedStep, history.salaryStandardYearMonth(), cache)
         );
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult.ineligible();
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.GovernmentWorkerPositionChangeResult governmentWorkerPositionChangeResult(
      String beforePositionCode,
      String currentGradeStep,
      String invertedStep,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      String currentStepAssessmentStartYear,
      String salaryStandardYearMonth,
      String organizationCode
   ) {
      int oldGrade = this.payrollRepository.intValue(currentGradeStep);
      if (oldGrade <= 0) {
         return com.dxsoft.rsgzgl.payroll.PayrollService.GovernmentWorkerPositionChangeResult.ineligible("当前岗位工资档次不完整，无法试算机关工人岗位变动。");
      } else {
         com.dxsoft.rsgzgl.payroll.OrganizationPayrollPolicy policy = this.organizationPayrollPolicy(organizationCode);
         boolean includeTechnicalGradeInCalculation = this.organizationPolicyEnabled(policy.positionChangeIncludeTechnicalGrade());
         boolean includeTechnicalGradeInOverStepCheck = this.organizationPolicyEnabled(policy.rankChangeIncludeTechnicalGrade());
         boolean octoberRule = this.organizationPolicyEnabled(policy.positionChangeOctoberRule());
         String promotedGradeStep = this.workerPositionChangeGradeStep(
            beforePositionCode, currentGradeStep, invertedStep, candidate.positionCode(), salaryStandardYearMonth, includeTechnicalGradeInCalculation
         );
         boolean exceedsStepDifference = this.workerPositionChangeExceedsStepDifference(
            beforePositionCode, currentGradeStep, candidate.positionCode(), promotedGradeStep, salaryStandardYearMonth, includeTechnicalGradeInOverStepCheck
         );
         String nextStepStartYear = exceedsStepDifference
            ? this.workerPositionChangeStepStartYear(candidate.startYearMonth(), octoberRule)
            : currentStepAssessmentStartYear;
         int promotedPositionSalary = this.workerPositionSalary(candidate.positionCode(), promotedGradeStep, salaryStandardYearMonth);
         String note = "按 58 号文岗位工资就近就高，档次 "
            + currentGradeStep
            + " → "
            + promotedGradeStep
            + (exceedsStepDifference ? "；增资额超过原岗位工资一个档差，xckhndzw 应从本次变动年度重新计算。" : "；增资额未超过原岗位工资一个档差，xckhndzw 沿用原起算年。");
         return new com.dxsoft.rsgzgl.payroll.PayrollService.GovernmentWorkerPositionChangeResult(
            true, currentGradeStep, promotedGradeStep, nextStepStartYear, promotedPositionSalary, exceedsStepDifference, note
         );
      }
   }

   private String workerPositionChangeGradeStep(
      String oldPositionCode, String oldGradeStep, String invertedStep, String newPositionCode, String standardYearMonth, boolean includeTechnicalGrade
   ) {
      int oldGradeSalary = this.payrollRepository.positionGradeSalary(oldPositionCode, oldGradeStep, invertedStep, standardYearMonth);
      int technicalGradeAdjustment = 0;
      if (includeTechnicalGrade) {
         technicalGradeAdjustment = this.payrollRepository.technicalGradeSalary(newPositionCode, standardYearMonth)
            - this.payrollRepository.technicalGradeSalary(oldPositionCode, standardYearMonth);
      }

      for (int grade = 1; grade <= 20; grade++) {
         int newGradeSalary = this.payrollRepository.positionGradeSalary(newPositionCode, String.valueOf(grade), invertedStep, standardYearMonth);
         if (newGradeSalary + technicalGradeAdjustment > oldGradeSalary) {
            return String.valueOf(grade);
         }
      }

      return oldGradeStep;
   }

   private boolean workerPositionChangeExceedsStepDifference(
      String oldPositionCode, String oldGradeStep, String newPositionCode, String newGradeStep, String standardYearMonth, boolean includeTechnicalGrade
   ) {
      int oldGrade = this.payrollRepository.intValue(oldGradeStep);
      if (oldGrade > 0 && this.payrollRepository.intValue(newGradeStep) > 0) {
         int technicalGradeAdjustment = includeTechnicalGrade
            ? this.payrollRepository.technicalGradeSalary(newPositionCode, standardYearMonth)
               - this.payrollRepository.technicalGradeSalary(oldPositionCode, standardYearMonth)
            : 0;
         int newPositionGradeSalary = this.payrollRepository.positionGradeSalary(newPositionCode, newGradeStep, "0", standardYearMonth)
            + technicalGradeAdjustment;
         int oldNextGradeSalary = this.payrollRepository.positionGradeSalary(oldPositionCode, String.valueOf(oldGrade + 1), "0", standardYearMonth);
         return newPositionGradeSalary > oldNextGradeSalary;
      } else {
         return false;
      }
   }

   private String workerPositionChangeStepStartYear(String appointmentYearMonth, boolean octoberRule) {
      String normalized = this.normalizeYearMonth(appointmentYearMonth);
      if (normalized.length() < 6) {
         return "";
      } else {
         int year = this.payrollRepository.intValue(normalized.substring(0, 4));
         int month = this.payrollRepository.intValue(normalized.substring(4, 6));
         return octoberRule && month >= 10 ? String.valueOf(year + 1) : String.valueOf(year);
      }
   }

   private com.dxsoft.rsgzgl.payroll.OrganizationPayrollPolicy organizationPayrollPolicy(String organizationCode) {
      return this.payrollRepository.findOrganizationPayrollPolicy(organizationCode).orElse(new com.dxsoft.rsgzgl.payroll.OrganizationPayrollPolicy("", "", ""));
   }

   private boolean organizationPolicyEnabled(String value) {
      return "√".equals(this.emptyToNull(value));
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult institutionPositionChangeResult(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      String currentSalaryLevel,
      String currentStepAssessmentStartYear
   ) {
      int currentLevel = this.payrollRepository.intValue(currentSalaryLevel);
      if (currentLevel <= 0) {
         return com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult.ineligible("当前薪级不完整，无法试算事业岗位变动。");
      } else {
         String currentPrefix = this.positionPrefix(history.positionCode());
         String targetPrefix = this.positionPrefix(candidate.positionCode());
         String startLevel;
         String promotedLevel = startLevel = String.valueOf(currentLevel);
         String nextStepStartYear = currentStepAssessmentStartYear != null && !currentStepAssessmentStartYear.isBlank()
            ? currentStepAssessmentStartYear
            : history.stepAssessmentStartYear();
         com.dxsoft.rsgzgl.payroll.PositionLevelRange range = null;
         Object note;
         if (currentPrefix.equals(targetPrefix)) {
            range = this.payrollRepository.findPositionLevelRange(candidate.positionCode()).orElse(null);
            if (range != null && currentLevel < range.minimumLevel()) {
               promotedLevel = String.valueOf(range.minimumLevel());
               nextStepStartYear = this.nextAssessmentYear(candidate.startYearMonth(), history.calculationYear());
               note = "事业人员同序列岗位变动：未达新岗位最低薪级，进入最低薪级，第二年不再考核晋升薪级。";
            } else {
               note = "事业人员同序列岗位变动：已达新岗位最低薪级，薪级不变。";
            }
         } else if ("08".equals(currentPrefix) && Set.of("07", "10", "11").contains(targetPrefix)) {
            com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart start = this.institutionTransferStart(history, candidate);
            if (!start.eligible()) {
               return com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult.ineligible(start.note());
            }

            startLevel = start.startSalaryLevel();
            promotedLevel = this.replayInstitutionSalaryLevel(history, start.historyStartPeriod(), startLevel, targetPrefix);
            nextStepStartYear = start.stepStartYear();
            note = start.note() + "；回放套改/转正以来正常薪级晋升和学历变化后确定转岗薪级。";
         } else {
            range = this.payrollRepository.findPositionLevelRange(candidate.positionCode()).orElse(null);
            if (range != null && currentLevel < range.minimumLevel()) {
               promotedLevel = String.valueOf(range.minimumLevel());
               nextStepStartYear = this.nextAssessmentYear(candidate.startYearMonth(), history.calculationYear());
               note = "事业人员不同序列岗位变动：未达新岗位最低薪级，进入最低薪级。";
            } else {
               note = "事业人员不同序列岗位变动：已达新岗位最低薪级，薪级不变。";
            }
         }

         int promotedSalary = this.payrollRepository
            .salaryLevelSalary(
               promotedLevel,
               "0",
               history.salaryStandardYearMonth(),
               this.salaryStandardPositionCode(history.organizationCode(), candidate.positionCode(), history.salaryStandardYearMonth())
            );
         return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult(
            true, startLevel, promotedLevel, nextStepStartYear, promotedSalary, (String)note
         );
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart institutionTransferStart(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate
   ) {
      String regularization = this.normalizeYearMonth(this.payrollRepository.findRegularizationYearMonth(history.organizationCode(), history.personCode()));
      if (regularization.isBlank()) {
         return com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart.ineligible("未找到转正年月，无法确定事业转岗起点。");
      } else if (regularization.compareTo("200607") >= 0) {
         com.dxsoft.rsgzgl.payroll.EducationPromotionSource education = this.payrollRepository
            .findLatestEducationForPromotion(history.organizationCode(), history.personCode(), regularization)
            .orElse(null);
         com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard2 = education == null
            ? null
            : this.payrollRepository.findEducationRegularizationStandard(candidate.positionCode(), education.educationCode()).orElse(null);
         return standard2 == null
            ? com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart.ineligible("2006.07 后转正人员未能按学历匹配新岗位序列转正薪级。")
            : new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart(
               true,
               regularization,
               standard2.gradeStep(),
               String.valueOf(this.yearOf(regularization)),
               "2006.07 后转正，按转正时学历确定新任岗位序列薪级 " + standard2.gradeStep()
            );
      } else {
         boolean hasManagementOrTechnicalBeforeWorker = this.payrollRepository
            .findLatestPositionBefore(
               history.organizationCode(), history.personCode(), this.normalizeYearMonth(history.positionStartYearMonth()), Set.of("07", "10", "11")
            )
            .isPresent();
         com.dxsoft.rsgzgl.payroll.EducationPromotionSource education = this.payrollRepository
            .findLatestEducationForPromotion(history.organizationCode(), history.personCode(), "200607")
            .orElse(null);
         com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard = education == null
            ? null
            : this.payrollRepository.findEducationRegularizationStandard(candidate.positionCode(), education.educationCode()).orElse(null);
         String reformPosition = hasManagementOrTechnicalBeforeWorker
            ? candidate.positionCode()
            : (standard == null ? candidate.positionCode() : this.normalizeEducationPromotionPositionCode(standard.positionCode()));
         int reformYears;
         Optional<com.dxsoft.rsgzgl.payroll.WageReformStandard> wageReform = this.payrollRepository
            .findWageReformStandard(
               reformPosition,
               hasManagementOrTechnicalBeforeWorker ? Math.max(1, 2006 - this.yearOf(candidate.startYearMonth()) + 1) : 1,
               reformYears = history.salaryYears() != null && history.salaryYears() > 0
                  ? history.salaryYears()
                  : Math.max(1, 2006 - this.yearOf(history.workStartYearMonth()) + 1 - this.nullToZero(history.interruptedSalaryYears()))
            );
         if (wageReform.isEmpty()) {
            return com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart.ineligible("2006.07 前已转正事业人员未能匹配新任岗位序列套改薪级。");
         } else {
            com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart reformStart = this.institutionSalaryLevelReformStart(
               history, reformPosition, wageReform.get(), reformYears
            );
            String baseNote = hasManagementOrTechnicalBeforeWorker
               ? "2006.07 前已转正，曾有管理/专技岗位，按新聘岗位序列查表套改薪级 " + reformStart.tableSalaryLevel()
               : "2006.07 前已转正，工勤转岗，按学历模拟定级岗位、任职年限1年查表套改薪级 " + reformStart.tableSalaryLevel();
            return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionStart(
               true, "200607", reformStart.salaryLevel(), "2006", baseNote + reformStart.noteSuffix() + "，最终套改薪级 " + reformStart.salaryLevel()
            );
         }
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart institutionSalaryLevelReformStart(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest,
      String currentPositionCode,
      com.dxsoft.rsgzgl.payroll.WageReformStandard currentStandard,
      int reformYears
   ) {
      String tableSalaryLevel = currentStandard.convertedStep();
      int currentLevel = this.payrollRepository.intValue(tableSalaryLevel);
      if (currentLevel > 0 && latest != null) {
         List<com.dxsoft.rsgzgl.payroll.WageReformPosition> positions = this.payrollRepository
            .findWageReformPositionsBefore(latest.organizationCode(), latest.personCode(), "200607", INSTITUTION_POSITION_PREFIXES);
         com.dxsoft.rsgzgl.payroll.WageReformPosition lowerPosition = null;

         for (int i = 0; i < positions.size(); i++) {
            if (currentPositionCode.equals(positions.get(i).positionCode()) && i + 1 < positions.size()) {
               lowerPosition = positions.get(i + 1);
               break;
            }
         }

         if (lowerPosition == null) {
            return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart(tableSalaryLevel, tableSalaryLevel, "");
         } else {
            int lowerAppointmentYears = Math.max(1, this.wageReformAppointmentYears(lowerPosition));
            Optional<com.dxsoft.rsgzgl.payroll.WageReformStandard> lowerStandard = this.lookupWageReformStandard(
               lowerPosition.positionCode(), lowerAppointmentYears, reformYears
            );
            if (lowerStandard.isEmpty()) {
               return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart(
                  tableSalaryLevel,
                  tableSalaryLevel,
                  "；原任低一职务 "
                     + this.positionDisplay(lowerPosition.positionCode(), lowerPosition.positionName())
                     + "（任职 "
                     + this.formatYearMonth(lowerPosition.startYearMonth())
                     + "）未找到 2006 套改标准"
               );
            } else {
               int lowerLevel = this.payrollRepository.intValue(lowerStandard.get().convertedStep());
               if (lowerLevel > currentLevel) {
                  String promotedLevel = String.valueOf(currentLevel + 1);
                  return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart(
                     tableSalaryLevel,
                     promotedLevel,
                     "；现任岗位套改薪级 "
                        + currentLevel
                        + " 低于原任低一职务 "
                        + this.positionDisplay(lowerPosition.positionCode(), lowerPosition.positionName())
                        + "（任职 "
                        + this.formatYearMonth(lowerPosition.startYearMonth())
                        + "，套改薪级 "
                        + lowerLevel
                        + "），按低一职务套改高套一级"
                  );
               } else {
                  return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart(
                     tableSalaryLevel,
                     tableSalaryLevel,
                     "；已比照原任低一职务 "
                        + this.positionDisplay(lowerPosition.positionCode(), lowerPosition.positionName())
                        + "（任职 "
                        + this.formatYearMonth(lowerPosition.startYearMonth())
                        + "，套改薪级 "
                        + lowerLevel
                        + "），不作低一职务套改调整"
                  );
               }
            }
         }
      } else {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionSalaryLevelReformStart(tableSalaryLevel, tableSalaryLevel, "");
      }
   }

   private String replayInstitutionSalaryLevel(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String startPeriod, String startSalaryLevel, String targetPrefix
   ) {
      int level = this.payrollRepository.intValue(startSalaryLevel);
      if (level <= 0) {
         return startSalaryLevel;
      } else {
         for (com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot row : this.payrollRepository.findHistoryChain(history.organizationCode(), history.personCode())) {
            String rowPeriod = this.normalizeYearMonth(row.calculationYear() + row.calculationMonth());
            if (rowPeriod.compareTo(startPeriod) > 0) {
               if (this.containsAny(row.calculationType(), "正常档次", "薪级")) {
                  level++;
               } else {
                  int value;
                  if (this.containsAny(row.calculationType(), "学历")
                     && (
                           value = this.payrollRepository
                              .intValue(
                                 String.valueOf(
                                    this.payrollRepository.intValue(row.positionSalaryGrade()) + this.payrollRepository.intValue(row.gradeSalaryStep())
                                 )
                              )
                        )
                        > level
                     && this.isInstitutionPosition(row.positionCode())) {
                     level = value;
                  }
               }
            }
         }

         return String.valueOf(level);
      }
   }

   private String nextAssessmentYear(String yearMonth, String fallbackYear) {
      int year = this.yearOf(yearMonth);
      return year > 0 ? String.valueOf(year + 1) : fallbackYear;
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult administrativeReplayResult(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate
   ) {
      int convertedLevel = this.payrollRepository.intValue(current.gradeSalaryLevel()) + 7;
      String level = String.valueOf(convertedLevel);
      String step = String.valueOf(this.payrollRepository.intValue(current.positionSalaryGrade()) + this.payrollRepository.intValue(current.gradeSalaryStep()));
      String levelStartYear = current.levelAssessmentStartYear();
      String stepStartYear = current.stepAssessmentStartYear();
      com.dxsoft.rsgzgl.payroll.PositionLevelRange targetRange = this.payrollRepository.findPositionLevelRange(candidate.positionCode()).orElse(null);
      if (targetRange != null && convertedLevel > 0 && this.payrollRepository.intValue(step) > 0) {
         int promotedLevelValue = convertedLevel;
         if (this.isHigherPositionLayer(current.positionCode(), candidate.positionCode())) {
            promotedLevelValue = convertedLevel > targetRange.minimumLevel() ? targetRange.minimumLevel() : Math.max(1, convertedLevel - 1);
         }

         String promotedLevel = String.valueOf(promotedLevelValue);
         String promotedStep = step;
         if (!promotedLevel.equals(level)) {
            int currentSalary = this.payrollRepository.gradeSalary(level, step, current.salaryStandardYearMonth());
            promotedStep = this.firstHigherGradeStep(promotedLevel, currentSalary, current.salaryStandardYearMonth());
            int promotedLevels = convertedLevel - promotedLevelValue;
            if (promotedLevels >= 2) {
               levelStartYear = this.yearOf(candidate.startYearMonth()) > 0
                  ? String.valueOf(this.yearOf(candidate.startYearMonth()))
                  : current.calculationYear();
            }

            if (this.gradeIncreaseExceedsStepDifference(level, step, promotedLevel, current.salaryStandardYearMonth())) {
               stepStartYear = this.yearOf(candidate.startYearMonth()) > 0
                  ? String.valueOf(this.yearOf(candidate.startYearMonth()))
                  : current.calculationYear();
            }
         }

         int promotedSalary = this.payrollRepository.gradeSalary(promotedLevel, promotedStep, current.salaryStandardYearMonth());
         return new com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult(
            true,
            level,
            step,
            levelStartYear,
            stepStartYear,
            promotedLevel,
            promotedStep,
            promotedSalary,
            "警员回到其他类，按警员等级加 7 得其他类级别；同职务层次级别不变，高于原职务层次时未达最低进最低，已达最低晋升 1 级。"
         );
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult.ineligible("未找到回到其他类目标职务的级别范围，或当前警员等级档次不完整。");
      }
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart administrativeReplayStart(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current,
      List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate
   ) {
      String regularization = this.normalizeYearMonth(this.payrollRepository.findRegularizationYearMonth(current.organizationCode(), current.personCode()));
      if (!regularization.isBlank() && regularization.compareTo("200607") < 0) {
         Optional<com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> administrativePosition = this.payrollRepository
            .findAdministrativePositionBeforeReform(current.organizationCode(), current.personCode());
         String startPositionCode = administrativePosition.map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::positionCode)
            .orElseGet(() -> this.administrativeEquivalentPosition(current.positionCode()));
         Optional<com.dxsoft.rsgzgl.payroll.WageReformStandard> standard = this.payrollRepository
            .findWageReformStandard(
               startPositionCode,
               Math.max(
                  1,
                  2006
                     - this.yearOf(
                        administrativePosition.map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::startYearMonth).orElse(current.positionStartYearMonth())
                     )
                     + 1
               ),
               current.salaryYears() != null && current.salaryYears() > 0
                  ? current.salaryYears()
                  : Math.max(1, 2006 - this.yearOf(current.workStartYearMonth()) + 1 - this.nullToZero(current.interruptedSalaryYears()))
            );
         if (standard.isEmpty()) {
            return com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart.ineligible("2006.07 前已转正人员未能按基本信息匹配 2006 套改标准。");
         } else {
            com.dxsoft.rsgzgl.payroll.WageReformStandard start = standard.get();
            int historyStartIndex = this.firstHistoryIndexAtOrAfter(chain, "200607");
            return new com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart(
               true,
               historyStartIndex,
               start.positionCode(),
               start.convertedLevel(),
               start.convertedStep(),
               "2006",
               "2006",
               "2006.07 前已转正，按基本信息和 2006 套改标准确定 01 职务套改起点 " + start.positionCode() + " " + start.convertedLevel() + "级" + start.convertedStep() + "档开始回放"
            );
         }
      } else if (regularization.isBlank()) {
         return com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart.ineligible("未找到转正年月，无法按学历转正定级确定起点。");
      } else {
         com.dxsoft.rsgzgl.payroll.PayrollService.RegularizationSalaryPosition resolved = this.resolveRegularizationSalaryPosition(
            current.organizationCode(), current.personCode(), regularization, candidate.positionCode(), regularization
         );
         com.dxsoft.rsgzgl.payroll.EducationRegularizationStandard standard = resolved.standard();
         if (standard == null) {
            return com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart.ineligible("2006.07 及以后转正人员未能按学历匹配转正定级标准。");
         } else {
            boolean institutionRegularization = resolved.institutionRegularization();
            int startIndex = this.firstHistoryIndexAtOrAfter(chain, regularization);
            String replayPositionCode = resolved.salaryPositionCode();
            String replayNote = institutionRegularization
               ? "2006.07 及以后转正，事业人员按学历转正定级标准确定薪级，岗位取转正时聘任岗位 " + replayPositionCode + " " + standard.gradeStep() + "薪级开始回放"
               : (
                  resolved.salaryPositionFromStandard()
                     ? "2006.07 及以后转正，未找到转正定级任职记录，按转正定级标准确认执行工资职务 " + replayPositionCode + " " + standard.gradeLevel() + "级" + standard.gradeStep() + "档开始回放"
                     : "2006.07 及以后转正，按学历转正定级标准确定起点 " + replayPositionCode + " " + standard.gradeLevel() + "级" + standard.gradeStep() + "档开始回放"
               );
            return new com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayStart(
               true,
               startIndex,
               replayPositionCode,
               standard.gradeLevel(),
               standard.gradeStep(),
               String.valueOf(this.yearOf(regularization)),
               String.valueOf(this.yearOf(regularization)),
               replayNote
            );
         }
      }
   }

   private int firstHistoryIndexByType(List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain, String token) {
      for (int i = 0; i < chain.size(); i++) {
         if (this.containsAny(chain.get(i).calculationType(), token)) {
            return i;
         }
      }

      return -1;
   }

   private int firstHistoryIndexAtOrAfter(List<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> chain, String period) {
      for (int i = 0; i < chain.size(); i++) {
         String rowPeriod = this.normalizeYearMonth(chain.get(i).calculationYear() + chain.get(i).calculationMonth());
         if (!rowPeriod.isBlank() && rowPeriod.compareTo(period) >= 0) {
            return i;
         }
      }

      return Math.max(0, chain.size() - 1);
   }

   private String administrativeEquivalentPosition(String positionCode) {
      if (positionCode == null || positionCode.length() < 4) {
         return positionCode;
      } else {
         return Set.of("21", "22", "23", "24", "25", "26", "27", "28").contains(this.positionPrefix(positionCode))
            ? "01" + positionCode.substring(2)
            : positionCode;
      }
   }

   private String normalizeYearMonth(String value) {
      String normalized = value == null ? "" : value.replace(".", "").trim();
      return normalized.length() >= 6 ? normalized.substring(0, 6) : "";
   }

   private String formatYearMonth(String value) {
      String normalized = this.normalizeYearMonth(value);
      return normalized.isBlank() ? this.emptyToDash(value) : normalized.substring(0, 4) + "." + normalized.substring(4, 6);
   }

   private String positionDisplay(String code, String name) {
      String normalizedCode = code == null ? "" : code.trim();
      String normalizedName = name == null ? "" : name.trim();
      return !normalizedCode.isBlank() && !normalizedName.isBlank()
         ? normalizedCode + " " + normalizedName
         : this.emptyToDash(normalizedCode.isBlank() ? normalizedName : normalizedCode);
   }

   private String positionDisplayWithoutCode(String name, String fallbackCode) {
      String normalizedName = name == null ? "" : name.trim();
      return normalizedName.isBlank() ? this.emptyToDash(fallbackCode) : normalizedName;
   }

   private String positionNameForProjectionStart(Optional<com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> position, String fallbackCode) {
      return position.filter(candidate -> fallbackCode != null && fallbackCode.equals(candidate.positionCode()))
         .map(com.dxsoft.rsgzgl.payroll.PositionChangeCandidate::positionName)
         .orElse("");
   }

   private String positionLabel(String baseSalarySource) {
      return "SALARY_LEVEL".equals(baseSalarySource) ? "岗位" : "职务";
   }

   private String levelStepLabel(String baseSalarySource) {
      return "SALARY_LEVEL".equals(baseSalarySource) ? "薪级" : "级别/档次";
   }

   private String levelStepDisplay(String baseSalarySource, String level, String step) {
      return this.levelStepDisplay(baseSalarySource, level, step, "0");
   }

   private String levelStepDisplay(String baseSalarySource, String level, String step, String gradeStepDifferenceCount) {
      if (!"SALARY_LEVEL".equals(baseSalarySource) && !"WORKER_GRADE".equals(baseSalarySource)) {
         String normalizedLevel = level == null ? "" : level.trim();
         String normalizedStep = step == null ? "" : step.trim();
         int stepDifferenceCount = this.payrollRepository.intValue(gradeStepDifferenceCount);
         if ("GRADE".equals(baseSalarySource) && stepDifferenceCount > 0) {
            return normalizedLevel + "-" + normalizedStep + "+" + stepDifferenceCount;
         } else {
            return !normalizedLevel.isBlank() && !normalizedStep.isBlank()
               ? normalizedLevel + "-" + normalizedStep
               : this.emptyToDash(normalizedLevel.isBlank() ? normalizedStep : normalizedLevel);
         }
      } else {
         return this.emptyToDash(step);
      }
   }

   private boolean containsAny(String value, String... tokens) {
      String text = value == null ? "" : value;

      for (String token : tokens) {
         if (text.contains(token)) {
            return true;
         }
      }

      return false;
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult policeOfficerConversionResult(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange targetLevelRange,
      int currentLevel,
      String currentStep,
      Integer currentGradeSalary
   ) {
      return this.policeOfficerConversionResult(
         history.positionCode(), candidate.positionCode(), targetLevelRange, currentLevel, currentStep, currentGradeSalary, history.salaryStandardYearMonth()
      );
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult policeOfficerConversionResult(
      String currentPositionCode,
      String targetPositionCode,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange targetLevelRange,
      int currentLevel,
      String currentStep,
      Integer currentGradeSalary,
      String salaryStandardYearMonth
   ) {
      if (targetLevelRange != null && currentLevel > 0 && this.payrollRepository.intValue(currentStep) > 0) {
         int sameRankCivilLevel = targetLevelRange.minimumLevel() + 7;
         boolean highPositionPromotion = this.isPoliceHighPositionPromotion(currentPositionCode, targetPositionCode);
         String promotedStep;
         String promotedLevel;
         String sameRankStep;
         String sameRankLevel;
         if (currentLevel > sameRankCivilLevel) {
            sameRankLevel = String.valueOf(targetLevelRange.minimumLevel());
            sameRankStep = this.firstHigherGradeStep(String.valueOf(sameRankCivilLevel), currentGradeSalary, "201807");
            promotedLevel = sameRankLevel;
            promotedStep = sameRankStep;
         } else {
            sameRankLevel = String.valueOf(Math.max(1, currentLevel - 7));
            sameRankStep = currentStep;
            if (highPositionPromotion) {
               promotedLevel = String.valueOf(Math.max(1, currentLevel - 8));
               promotedStep = this.firstHigherPoliceGradeStep(sameRankLevel, currentStep, promotedLevel, "201807");
            } else {
               promotedLevel = sameRankLevel;
               promotedStep = currentStep;
            }
         }

         int promotedGradeSalary = this.payrollRepository.policeOfficerGradeSalary(promotedLevel, promotedStep, "201807");
         if (promotedGradeSalary == 0) {
            promotedGradeSalary = this.payrollRepository.gradeSalary(promotedLevel, promotedStep, salaryStandardYearMonth);
         }

         return new com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult(
            true, sameRankLevel, sameRankStep, highPositionPromotion, promotedLevel, promotedStep, promotedGradeSalary
         );
      } else {
         return com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult.ineligible();
      }
   }

   private boolean isPoliceHighPositionPromotion(String currentPositionCode, String targetPositionCode) {
      return Set.of("0207", "01C0").contains(currentPositionCode) && "2111".equals(targetPositionCode)
         || Set.of("0206", "01B0").contains(currentPositionCode) && Set.of("2110", "2109").contains(targetPositionCode)
         || Set.of("0204", "0205", "01A1", "01A0").contains(currentPositionCode) && Set.of("2108", "2107").contains(targetPositionCode)
         || Set.of("0203", "0191", "0190").contains(currentPositionCode) && Set.of("2106", "2105").contains(targetPositionCode)
         || Set.of("0202", "0181", "0180").contains(currentPositionCode) && Set.of("2104", "2103").contains(targetPositionCode)
         || Set.of("0201", "0171", "0170").contains(currentPositionCode) && Set.of("2102", "2101").contains(targetPositionCode);
   }

   private boolean isHigherPositionLayer(String currentPositionCode, String targetPositionCode) {
      int currentLayer = this.positionLayer(currentPositionCode);
      int targetLayer = this.positionLayer(targetPositionCode);
      return currentLayer > 0 && targetLayer > 0 && targetLayer < currentLayer;
   }

   private boolean isLowerPositionLayer(String currentPositionCode, String targetPositionCode) {
      int currentLayer = this.positionLayer(currentPositionCode);
      int targetLayer = this.positionLayer(targetPositionCode);
      return currentLayer > 0 && targetLayer > currentLayer;
   }

   private int positionLayer(String positionCode) {
      if (positionCode != null && positionCode.length() >= 4) {
         return switch (positionCode) {
            case "0150", "0151", "2101", "2201", "2301", "2401", "2501", "2601", "2701", "2801" -> 1;
            case "0160", "0161", "2102", "2202", "2302", "2402", "2502", "2602", "2702", "2802" -> 2;
            case "0170", "0171", "0201", "2103", "2104", "2203", "2204", "2303", "2304", "2403", "2404", "2503", "2504", "2603", "2604", "2703", "2704", "2803", "2804" -> 3;
            case "0180", "0181", "0202", "2105", "2106", "2205", "2206", "2305", "2306", "2405", "2406", "2505", "2506", "2605", "2606", "2705", "2706", "2805", "2806" -> 4;
            case "0190", "0191", "0203", "2107", "2108", "2207", "2208", "2307", "2308", "2407", "2408", "2507", "2508", "2607", "2608", "2707", "2708", "2807", "2808" -> 5;
            case "01A0", "01A1", "0204", "0205", "2109", "2110", "2209", "2210", "2309", "2310", "2409", "2410", "2509", "2510", "2609", "2610", "2709", "2710", "2809", "2810" -> 6;
            case "01B0", "0206", "2111", "2211", "2311", "2411", "2511", "2611", "2711", "2811" -> 7;
            case "01C0", "0207", "2112", "2212", "2312", "2412", "2512", "2612", "2712", "2812" -> 8;
            default -> 0;
         };
      } else {
         return 0;
      }
   }

   private String firstHigherPoliceGradeStep(String currentLevel, String currentStep, String promotedLevel, String standardYearMonth) {
      int currentSalary = this.payrollRepository.policeOfficerGradeSalary(currentLevel, currentStep, standardYearMonth);

      for (int step = 1; step <= 14; step++) {
         int amount = this.payrollRepository.policeOfficerGradeSalary(promotedLevel, String.valueOf(step), standardYearMonth);
         if (amount > currentSalary) {
            return String.valueOf(step);
         }
      }

      return "14";
   }

   private String positionChangeType(
      String currentPositionCode,
      String newPositionCode,
      boolean sequenceConversion,
      boolean policeOfficerConversion,
      boolean judicialConversion,
      boolean rankConversion,
      boolean institutionPositionChange
   ) {
      if (newPositionCode == null || newPositionCode.equals(currentPositionCode)) {
         return "未变化";
      } else if (policeOfficerConversion) {
         return "警员套改";
      } else if (judicialConversion) {
         return "法检套改";
      } else if (rankConversion) {
         return "职级套改";
      } else if (this.isLegacyPolicePositionConversion(this.positionPrefix(currentPositionCode), this.positionPrefix(newPositionCode))) {
         return "警员套改";
      } else if (institutionPositionChange) {
         return "职务变化";
      } else {
         return sequenceConversion ? "转换序列" : "同序列职务变化";
      }
   }

   private String nextMonth(String yearMonth) {
      String normalized = yearMonth == null ? "" : yearMonth.replace(".", "");
      if (normalized.length() < 6) {
         return "";
      } else {
         int year = this.payrollRepository.intValue(normalized.substring(0, 4));
         int month = this.payrollRepository.intValue(normalized.substring(4, 6)) + 1;
         if (month > 12) {
            year++;
            month = 1;
         }

         return "%04d%02d".formatted(year, month);
      }
   }

   private String plusOneYear(String yearMonth) {
      String normalized = this.normalizeYearMonth(yearMonth);
      if (normalized.length() < 6) {
         return "";
      } else {
         int year = this.payrollRepository.intValue(normalized.substring(0, 4)) + 1;
         return "%04d%s".formatted(year, normalized.substring(4, 6));
      }
   }

   private String buildPendingPositionChangeNote(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      String lastPayrollChangeType,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange levelRange,
      boolean eligible,
      int promotedLevels,
      boolean gradeIncreaseExceedsStepDifference,
      boolean sequenceConversion,
      boolean policeOfficerConversion,
      boolean judicialConversion,
      boolean rankConversion,
      com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult rankConversionResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult institutionResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.GovernmentWorkerPositionChangeResult governmentWorkerResult,
      String judicialConversionStep,
      com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult administrativeReplayResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult policeOfficerResult,
      boolean pendingPositionChange,
      boolean applyEligible
   ) {
      String note = this.positionChangePromotionNote(
         history,
         candidate,
         levelRange,
         eligible,
         promotedLevels,
         gradeIncreaseExceedsStepDifference,
         sequenceConversion,
         policeOfficerConversion,
         judicialConversion,
         rankConversion,
         rankConversionResult,
         institutionResult,
         governmentWorkerResult,
         judicialConversionStep,
         administrativeReplayResult,
         policeOfficerResult,
         false
      );
      if (pendingPositionChange && !applyEligible) {
         note = "存在待处理职务变化，但当前试算条件不满足，暂不能办理；" + (note != null && !note.isBlank() ? note : "");
      }

      return note;
   }

   private String positionChangeDisplayStep(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot snapshot, String positionCode) {
      if (snapshot == null) {
         return "";
      } else {
         String code = this.firstNonBlank(positionCode, snapshot.positionCode());
         if (this.isGovernmentWorkerPosition(code)) {
            return this.firstNonBlank(snapshot.positionSalaryGrade(), "");
         } else {
            int combinedStep = this.payrollRepository.intValue(snapshot.positionSalaryGrade()) + this.payrollRepository.intValue(snapshot.gradeSalaryStep());
            return combinedStep > 0 ? String.valueOf(combinedStep) : this.firstNonBlank(snapshot.positionSalaryGrade(), "");
         }
      }
   }

   private String positionChangePriorPromotionRequiredNote(int uid, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, String effectivePeriod) {
      return this.positionChangePriorPromotionRequiredNote(uid, history, effectivePeriod, null, false);
   }

   private String positionChangePriorPromotionRequiredNote(
      int uid,
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      String effectivePeriod,
      com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache assessmentCache,
      boolean forList
   ) {
      int promotionYear = this.yearOf(effectivePeriod);
      if (promotionYear >= 2007 && history != null) {
         com.dxsoft.rsgzgl.payroll.LevelPromotionPreview levelPreview = this.levelPromotionPreview(
            uid,
            promotionYear,
            history,
            assessmentCache,
            forList,
            com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository),
            true
         );
         if (levelPreview == null) {
            return null;
         } else {
            boolean levelDue = Boolean.TRUE.equals(levelPreview.eligible())
               && Boolean.TRUE.equals(levelPreview.levelPromotionDue())
               && !Boolean.TRUE.equals(levelPreview.rollbackEligible());
            boolean stepDueInLevelSeries = Boolean.TRUE.equals(levelPreview.eligible())
               && Boolean.TRUE.equals(levelPreview.stepPromotionDue())
               && !Boolean.TRUE.equals(levelPreview.rollbackEligible());
            if (levelDue && stepDueInLevelSeries) {
               return "职务变化前已符合级别晋升和档次晋升条件，请先办理级别或档次变动。";
            } else if (levelDue) {
               return "职务变化前已符合级别晋升条件，请先办理级别晋升。";
            } else if (stepDueInLevelSeries) {
               return "职务变化前已符合档次晋升条件，请先办理档次晋升。";
            } else {
               if (!Boolean.TRUE.equals(levelPreview.eligible())) {
                  if (this.isNormalPromotionProcessedInYear(uid, promotionYear)) {
                     return null;
                  }

                  com.dxsoft.rsgzgl.payroll.NormalPromotionPreview normalPreview = this.normalPromotionPreview(
                     uid, promotionYear, history, assessmentCache, null, forList, true
                  );
                  if (Boolean.TRUE.equals(normalPreview.applyEligible())) {
                     return "职务变化前已符合档次/薪级晋升条件，请先办理档次或薪级晋升。";
                  }
               }

               return null;
            }
         }
      } else {
         return null;
      }
   }

   private String positionChangePromotionNote(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange levelRange,
      boolean eligible,
      int promotedLevels,
      boolean gradeIncreaseExceedsStepDifference,
      boolean sequenceConversion,
      boolean policeOfficerConversion,
      boolean judicialConversion,
      boolean rankConversion,
      com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult rankConversionResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult institutionResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.GovernmentWorkerPositionChangeResult governmentWorkerResult,
      String judicialConversionStep,
      com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult administrativeReplayResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult policeOfficerResult,
      boolean processedPositionChange
   ) {
      if (processedPositionChange) {
         if (administrativeReplayResult != null) {
            return "已完成综合管理类回放处理，可执行还原。";
         } else if (policeOfficerConversion) {
            return "已完成警员套改处理，可执行还原。";
         } else if (rankConversion) {
            return "已完成职级套改处理，可执行还原。";
         } else if (institutionResult != null) {
            return "已完成职务变化处理，可执行还原。";
         } else if (judicialConversion) {
            return "已完成法检套改处理，可执行还原。";
         } else {
            return sequenceConversion ? "已完成转换序列处理，可执行还原。" : "已完成「" + history.calculationType() + "」处理，可执行还原。";
         }
      } else if (administrativeReplayResult != null) {
         return administrativeReplayResult.eligible()
            ? "识别为警员回到综合管理类；" + administrativeReplayResult.note()
            : "识别为警员回到综合管理类；" + administrativeReplayResult.note();
      } else if (policeOfficerConversion) {
         if (policeOfficerResult != null && policeOfficerResult.eligible()) {
            return policeOfficerResult.highPositionPromotion()
               ? "识别为警员套改；高套职务按旧系统 jytg 规则先按同级职务平套，再按职务晋升政策晋升到套改后职务。"
               : "识别为警员套改；按旧系统 jytg 规则先判断是否达到套改后职务最低等级，未达最低进最低，已达最低保持平套等级。";
         } else {
            return "识别为警员套改，但未找到套改后职务对应的等级范围，暂不能试算。";
         }
      } else if (rankConversion) {
         return rankConversionResult != null && rankConversionResult.eligible()
            ? "识别为职级套改；从 01 前缀行政职务转为职级类序列，按职级套改规则处理。职务工资减少额保留到 PGBC，后续职务晋升时从职务工资增资额中冲减。"
            : "识别为职级套改，但未找到目标职级对应的级别范围，暂不能试算。";
      } else if (institutionResult != null) {
         return institutionResult.eligible() ? institutionResult.note() : institutionResult.note();
      } else if (governmentWorkerResult != null) {
         return governmentWorkerResult.eligible() ? governmentWorkerResult.note() : governmentWorkerResult.note();
      } else if (!judicialConversion) {
         if (candidate.positionCode() == null || !this.hasPendingPositionChange(history)) {
            return "未发现不同于当前工资记录的新任职务，不参与职务变化晋升试算。";
         } else if (sequenceConversion) {
            return "新旧职务前缀属于不同序列，识别为转换序列；不按同序列职务晋升级别规则试算。";
         } else if (!eligible) {
            return governmentWorkerResult != null ? governmentWorkerResult.note() : "仅公务员/参公岗位且存在新任职务级别范围时参与职务变化晋升试算。";
         } else if (promotedLevels >= 2) {
            return gradeIncreaseExceedsStepDifference
               ? "晋升职务相应晋升级别达到两级及以上，xckhndjb 应从职务变动级别当年重新计算；逐级计算增资额超过下一级别一个档差，xckhndzw 也应从本次晋升年度重新计算。"
               : "晋升职务相应晋升级别达到两级及以上，xckhndjb 应从职务变动级别当年重新计算；逐级计算增资额未超过下一级别一个档差，xckhndzw 沿用原起算年。";
         } else if (promotedLevels == 1) {
            return gradeIncreaseExceedsStepDifference
               ? "晋升职务相应晋升一个级别，xckhndjb 继续从上一次按考核结果晋升级别当年计算；增资额超过下一级别一个档差，xckhndzw 应从本次晋升年度重新计算。"
               : "晋升职务相应晋升一个级别，xckhndjb 继续从上一次按考核结果晋升级别当年计算；增资额未超过下一级别一个档差，xckhndzw 沿用原起算年。";
         } else {
            return "新任职务级别范围未导致级别晋升，仅试算职务工资变化。";
         }
      } else {
         return judicialConversionStep != null && !judicialConversionStep.isBlank()
            ? "识别为法检套改；按当前执行职务、级别、档次和目标法检等级，在 bz06_fjtgb 中确定套改后档次。"
            : "识别为法检套改，但未在 bz06_fjtgb 中找到当前级别档次和目标法检等级对应的套改档次。";
      }
   }

   private List<String> positionChangeExplanationLines(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history,
      String beforePositionCode,
      String beforePositionName,
      String afterPositionCode,
      String afterPositionName,
      String appointmentStartYearMonth,
      String changeType,
      String currentStep,
      com.dxsoft.rsgzgl.payroll.PositionLevelRange levelRange,
      com.dxsoft.rsgzgl.payroll.PayrollService.PoliceOfficerConversionResult policeOfficerResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.RankConversionResult rankConversionResult,
      com.dxsoft.rsgzgl.payroll.PayrollService.InstitutionPositionChangeResult institutionResult,
      String judicialConversionStep,
      com.dxsoft.rsgzgl.payroll.PayrollService.AdministrativeReplayResult administrativeReplayResult,
      String promotedLevel,
      String promotedStep,
      String nextLevelAssessmentStartYear,
      String nextStepAssessmentStartYear,
      int positionSalaryIncrease,
      int pgbcRetainedAmount,
      int pgbcOffsetAmount,
      int netPositionSalaryIncrease,
      int gradeSalaryIncrease,
      int technicalGradeSalaryIncrease,
      int performanceAllowanceIncrease,
      int subsidyAllowanceIncrease,
      boolean gradeIncreaseExceedsStepDifference,
      String note
   ) {
      ArrayList<String> lines = new ArrayList<>();
      lines.add("识别类型：" + changeType + "。");
      lines.add(
         "当前执行工资："
            + history.calculationYear()
            + history.calculationMonth()
            + "，原职务 "
            + this.emptyToDash(beforePositionCode)
            + " "
            + this.emptyToDash(beforePositionName)
            + "，原级别/薪级 "
            + this.emptyToDash(history.gradeSalaryLevel())
            + "/"
            + this.emptyToDash(currentStep)
            + "。"
      );
      lines.add(
         "新任职务："
            + this.emptyToDash(afterPositionCode)
            + " "
            + this.emptyToDash(afterPositionName)
            + "，任职年月 "
            + this.emptyToDash(appointmentStartYearMonth)
            + "，执行年月 "
            + this.emptyToDash(this.nextMonth(appointmentStartYearMonth))
            + "。"
      );
      if (levelRange != null) {
         lines.add("新职务级别范围：最低 " + levelRange.minimumLevel() + "，最高 " + levelRange.maximumLevel() + "。");
      }

      if (policeOfficerResult != null) {
         if (policeOfficerResult.eligible()) {
            lines.add(
               "警员套改：平套等级/档次 "
                  + policeOfficerResult.sameRankLevel()
                  + "/"
                  + policeOfficerResult.sameRankStep()
                  + (policeOfficerResult.highPositionPromotion() ? "，高套职务后再晋升一级。" : "。")
            );
         } else {
            lines.add("警员套改：未能取得目标等级范围，未参与试算。");
         }
      }

      if (rankConversionResult != null) {
         lines.add(
            rankConversionResult.eligible()
               ? "职级套改：按最低级别/跨层晋升规则试算为 " + rankConversionResult.promotedLevel() + "级" + rankConversionResult.promotedStep() + "档。"
               : "职级套改：未找到目标职级级别范围。"
         );
      }

      if (judicialConversionStep != null) {
         lines.add(judicialConversionStep.isBlank() ? "法检套改：未在 bz06_fjtgb 找到对应套改档次。" : "法检套改：按 bz06_fjtgb 取得套改档次 " + judicialConversionStep + "。");
      }

      if (administrativeReplayResult != null) {
         lines.add(administrativeReplayResult.note());
         if (administrativeReplayResult.eligible()) {
            lines.add(
               "回放结果：级别/档次 "
                  + administrativeReplayResult.replayedLevel()
                  + "/"
                  + administrativeReplayResult.replayedStep()
                  + "，xckhndjb/xckhndzw "
                  + this.emptyToDash(administrativeReplayResult.levelStartYear())
                  + "/"
                  + this.emptyToDash(administrativeReplayResult.stepStartYear())
                  + "。"
            );
         }
      }

      if (institutionResult != null) {
         lines.add(institutionResult.note());
         if (institutionResult.eligible()) {
            lines.add(
               "事业岗位变动薪级：起点 "
                  + institutionResult.startSalaryLevel()
                  + "，试算 "
                  + institutionResult.promotedSalaryLevel()
                  + "，更新后 xckhndzw="
                  + this.emptyToDash(institutionResult.nextStepAssessmentStartYear())
                  + "。"
            );
         }
      }

      lines.add(
         "试算结果：级别/薪级 "
            + this.emptyToDash(promotedLevel)
            + "/"
            + this.emptyToDash(promotedStep)
            + "，更新后 xckhndjb/xckhndzw "
            + this.emptyToDash(nextLevelAssessmentStartYear)
            + "/"
            + this.emptyToDash(nextStepAssessmentStartYear)
            + "。"
      );
      StringBuilder increaseBreakdown = new StringBuilder("增资分解：职务增资 ")
         .append(positionSalaryIncrease)
         .append("，PGBC保留 ")
         .append(pgbcRetainedAmount)
         .append("，PGBC冲销 ")
         .append(pgbcOffsetAmount)
         .append("，职务净增 ")
         .append(netPositionSalaryIncrease)
         .append("，级别/薪级增资 ")
         .append(gradeSalaryIncrease);
      if (technicalGradeSalaryIncrease > 0) {
         increaseBreakdown.append("，技术等级增资 ").append(technicalGradeSalaryIncrease);
      }

      if (performanceAllowanceIncrease != 0) {
         increaseBreakdown.append("，")
            .append(this.dfbt2CaptionForPosition(afterPositionCode, history.organizationType()))
            .append("增资 ")
            .append(performanceAllowanceIncrease);
      }

      if (subsidyAllowanceIncrease != 0) {
         increaseBreakdown.append("，")
            .append(this.sdbtCaptionForPosition(afterPositionCode, history.organizationType()))
            .append("增资 ")
            .append(subsidyAllowanceIncrease);
      }

      increaseBreakdown.append("。");
      lines.add(increaseBreakdown.toString());
      if (gradeIncreaseExceedsStepDifference) {
         lines.add("级别增资超过下一级别一个档差，xckhndzw 需从本次变动年度重新计算。");
      }

      lines.add("结论：" + note);
      return lines;
   }

   private String emptyToDash(String value) {
      return value != null && !value.isBlank() ? value : "-";
   }

   private String firstHigherGradeStep(String gradeLevel, Integer currentGradeSalary, String standardYearMonth) {
      return this.firstHigherGradeStep(
         gradeLevel, currentGradeSalary, standardYearMonth, com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache.empty(this.payrollRepository)
      );
   }

   private String firstHigherGradeStep(
      String gradeLevel, Integer currentGradeSalary, String standardYearMonth, com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache cache
   ) {
      for (int step = 1; step <= 20; step++) {
         int amount = cache.gradeSalary(gradeLevel, String.valueOf(step), standardYearMonth);
         if (amount > this.nullToZero(currentGradeSalary)) {
            return String.valueOf(step);
         }
      }

      return "20";
   }

   private String firstHigherGradeStepAtOrAbove(String gradeLevel, String currentStep, Integer targetSalary, String standardYearMonth) {
      int minimumStep;
      for (int step = minimumStep = Math.max(1, this.payrollRepository.intValue(currentStep)); step <= 20; step++) {
         int amount = this.payrollRepository.gradeSalary(gradeLevel, String.valueOf(step), standardYearMonth);
         if (amount >= this.nullToZero(targetSalary)) {
            return String.valueOf(step);
         }
      }

      return String.valueOf(Math.min(20, minimumStep));
   }

   private int assessmentStartYear(String storedStartYear, String positionStartYearMonth, String positionCode) {
      int stored = this.yearOf(storedStartYear);
      if (stored > 0) {
         return stored;
      } else {
         String normalizedPositionStart = positionStartYearMonth == null ? "" : positionStartYearMonth.replace(".", "");
         int minimumStartYear = 2006;
         if (normalizedPositionStart.compareTo("200607") > 0) {
            minimumStartYear = this.yearOf(normalizedPositionStart);
         }

         return minimumStartYear;
      }
   }

   private void appendMissingAssessmentPrompt(
      List<String> lines, String organizationCode, String personCode, int startYear, int endYear, Set<Integer> promptedYears
   ) {
      List<Integer> missingYears = this.missingAssessmentYears(organizationCode, personCode, startYear, endYear).stream().filter(promptedYears::add).toList();
      if (!missingYears.isEmpty()) {
         lines.add("缺少 " + missingYears.stream().map(String::valueOf).collect(Collectors.joining("、")) + " 年度考核结果，请先补录后再推算正常晋升。");
      }
   }

   private List<Integer> missingAssessmentYears(String organizationCode, String personCode, int startYear, int endYear) {
      if (startYear > 0 && endYear >= startYear) {
         Set<Integer> existingYears = this.payrollRepository.assessmentYears(organizationCode, personCode, startYear, endYear);
         ArrayList<Integer> missing = new ArrayList<>();

         for (int year = startYear; year <= endYear; year++) {
            if (!existingYears.contains(year)) {
               missing.add(year);
            }
         }

         return missing;
      } else {
         return List.of();
      }
   }

   private boolean isLevelPromotionProcessedInYear(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, int promotionYear) {
      if (history != null && this.yearOf(history.calculationYear()) == promotionYear) {
         String changeType = history.calculationType();
         return "正常级别".equals(changeType) || "级别滚动".equals(changeType);
      } else {
         return false;
      }
   }

   private String inheritedLevelAssessmentStartYear(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      if (history != null && this.emptyToNull(history.id()) != null) {
         String currentId = history.id();

         for (int i = 0; i < 8; i++) {
            Optional<String> predecessorId = this.payrollRepository.findPredecessorHistoryId(history.organizationCode(), history.personCode(), currentId);
            if (predecessorId.isEmpty()) {
               predecessorId = this.payrollRepository.findPredecessorHistoryId(currentId);
            }

            if (predecessorId.isEmpty()) {
               return null;
            }

            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot predecessor = this.payrollRepository.findPayrollHistoryById(predecessorId.get()).orElse(null);
            if (predecessor == null) {
               return null;
            }

            String levelStart = this.emptyToNull(predecessor.levelAssessmentStartYear());
            if (levelStart != null) {
               return levelStart;
            }

            currentId = predecessor.id();
            if (this.emptyToNull(currentId) == null) {
               return null;
            }
         }

         return null;
      } else {
         return null;
      }
   }

   private boolean supportsReformLevelRollingInPromotionYear(int promotionYear) {
      return promotionYear >= 2007 && promotionYear <= 2010;
   }

   private boolean isLevelPromotionPosition(String positionCode) {
      return positionCode != null && positionCode.length() >= 2 && LEVEL_PROMOTION_POSITION_PREFIXES.contains(positionCode.substring(0, 2));
   }

   private boolean isInstitutionPosition(String positionCode) {
      return positionCode != null && positionCode.length() >= 2 && INSTITUTION_POSITION_PREFIXES.contains(positionCode.substring(0, 2));
   }

   private boolean isGovernmentWorkerPosition(String positionCode) {
      return positionCode != null && positionCode.length() >= 2 && GOVERNMENT_WORKER_POSITION_PREFIXES.contains(positionCode.substring(0, 2));
   }

   private boolean isGovernmentWorkerOrganizationType(String organizationType) {
      return organizationType != null && GOVERNMENT_WORKER_POSITION_PREFIXES.contains(organizationType.trim());
   }

   private boolean isGovernmentWorker(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history, com.dxsoft.rsgzgl.payroll.PayrollService.WageProjectionState state
   ) {
      return this.isGovernmentWorkerPosition(state == null ? null : state.positionCode())
         || history != null && (this.isGovernmentWorkerPosition(history.positionCode()) || this.isGovernmentWorkerOrganizationType(history.organizationType()));
   }

   private String salaryStepCaption(String positionCode, String baseSalarySource) {
      return this.isInstitutionPosition(positionCode) ? "薪级" : "档次";
   }

   private String gradeSalaryCaption(String positionCode) {
      if (this.isInstitutionPosition(positionCode)) {
         return "薪级工资";
      } else {
         return this.isGovernmentWorkerPosition(positionCode) ? "档次工资" : "级别工资";
      }
   }

   private boolean supportsRuralTeacherYearAllowance(String positionCode) {
      return "SALARY_LEVEL".equals(this.baseSalarySource(positionCode));
   }

   private int normalPromotionRequiredYears(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
      String source = this.baseSalarySource(history.positionCode());
      if ("SALARY_LEVEL".equals(source)) {
         return 1;
      } else if ("WORKER_GRADE".equals(source)) {
         return 2;
      } else {
         return !"GRADE".equals(source) && !"JUDICIAL_GRADE".equals(source) && !"POLICE_GRADE".equals(source) ? 0 : 2;
      }
   }

   private String levelPromotionNote(
      boolean eligible,
      boolean reformLevelRollingDue,
      boolean normalLevelDue,
      boolean stepPromotionDue,
      boolean gradeIncreaseExceedsStepDifference,
      boolean levelSpanMeetsFiveYears,
      int qualifiedYearsForLevel
   ) {
      if (!eligible) {
         return "当前岗位前缀或工资类型暂不参与级别晋升试算。";
      } else if (reformLevelRollingDue && stepPromotionDue) {
         return gradeIncreaseExceedsStepDifference
            ? "2007-2010套改后级别滚动试算；增资额超过下一级别一个档差，xckhndzw 从本次滚动年度重新计算。同年另符合档次晋升，请到「正常档次/薪级晋升」办理。"
            : "2007-2010套改后级别滚动试算。同年另符合档次晋升，请到「正常档次/薪级晋升」办理。";
      } else if (reformLevelRollingDue) {
         return gradeIncreaseExceedsStepDifference
            ? "2007-2010套改后级别滚动：上一年度考核称职及以上且达到套改表规定年限；级别滚动增资额超过下一级别一个档差，xckhndzw 从本次滚动年度重新计算。"
            : "2007-2010套改后级别滚动：上一年度考核称职及以上且达到套改表规定年限，按就近就高晋升1个级别试算。";
      } else if (normalLevelDue && qualifiedYearsForLevel > 5) {
         return "上年符合";
      } else if (normalLevelDue && stepPromotionDue) {
         return gradeIncreaseExceedsStepDifference ? "级别晋升增资额超过下一级别一个档差，xckhndzw 从本次晋升年度重新计算。同年符合档次晋升" : "同年符合档次晋升";
      } else if (normalLevelDue) {
         return gradeIncreaseExceedsStepDifference ? "级别晋升增资额超过下一级别一个档差，xckhndzw 从本次晋升年度重新计算。" : "";
      } else if (levelSpanMeetsFiveYears && qualifiedYearsForLevel > 5) {
         return "上年符合";
      } else if (levelSpanMeetsFiveYears && qualifiedYearsForLevel < 5) {
         return "不符合";
      } else if (stepPromotionDue) {
         return "";
      } else {
         return !levelSpanMeetsFiveYears ? "级别考核起算年与晋升年度差额未满5年，暂不符合级别晋升条件。" : "尚未满足级别晋升条件：级别考核起算年与晋升年度差额须满5年，且期间考核称职/合格及以上须累计5年。";
      }
   }

   private String rollbackEligibleLevelPromotionNote(
      boolean eligible,
      boolean reformLevelRollingDue,
      boolean normalLevelDue,
      boolean stepPromotionDue,
      boolean gradeIncreaseExceedsStepDifference,
      boolean levelSpanMeetsFiveYears,
      int qualifiedYearsForLevel,
      List<Integer> missingLevelAssessmentYears
   ) {
      return !reformLevelRollingDue && !normalLevelDue && !stepPromotionDue
         ? ""
         : this.composeLevelPromotionNote(
            this.levelPromotionNote(
               eligible,
               reformLevelRollingDue,
               normalLevelDue,
               stepPromotionDue,
               gradeIncreaseExceedsStepDifference,
               levelSpanMeetsFiveYears,
               qualifiedYearsForLevel
            ),
            missingLevelAssessmentYears
         );
   }

   private String composeLevelPromotionNote(String baseNote, List<Integer> missingLevelAssessmentYears) {
      ArrayList<String> parts = new ArrayList<>();
      if (baseNote != null && !baseNote.isBlank()) {
         parts.add(baseNote);
      }

      if (!missingLevelAssessmentYears.isEmpty()) {
         parts.add("缺少 " + missingLevelAssessmentYears.stream().map(String::valueOf).collect(Collectors.joining("、")) + " 年度考核结果，请先补录后再办理级别晋升。");
      }

      return parts.isEmpty() ? "" : String.join("；", parts);
   }

   private boolean isEducationPosition(String positionCode) {
      return positionCode != null
         && positionCode.length() >= 2
         && positionCode.substring(0, 2).compareTo("07") >= 0
         && positionCode.substring(0, 2).compareTo("20") < 0;
   }

   private int requireCurrentHistoryUid(String payrollHistoryId) {
      int uid = this.payrollRepository
         .findPersonnelUidByCurrentHistoryId(payrollHistoryId)
         .orElseThrow(() -> new NotFoundException("Current payroll history not found: " + payrollHistoryId));
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot latest = this.payrollRepository
         .findLatestHistory(uid)
         .orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      this.accessControlService.requireOrganization(latest.organizationCode());
      return uid;
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult rollbackPromotion(String payrollHistoryId, Set<String> allowedChangeTypes, String message) {
      return this.rollbackPromotion(payrollHistoryId, changeType -> changeType != null && allowedChangeTypes.contains(changeType), message);
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult rollbackPromotion(String payrollHistoryId, Predicate<String> allowedChangeType, String message) {
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current = this.payrollRepository
         .findCurrentHistoryById(payrollHistoryId)
         .orElseThrow(() -> new NotFoundException("Current payroll history not found: " + payrollHistoryId));
      return this.rollbackPromotion(current, allowedChangeType, message);
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult rollbackPromotion(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current, Predicate<String> allowedChangeType, String message
   ) {
      if (current != null && this.emptyToNull(current.id()) != null) {
         this.accessControlService.requireOrganization(current.organizationCode());
         if (!allowedChangeType.test(current.calculationType())) {
            throw new IllegalArgumentException("当前工资变动类别不能通过该模块还原：" + current.calculationType());
         } else {
            String organizationCode = this.emptyToNull(current.organizationCode());
            String personCode = this.emptyToNull(current.personCode());
            String previousId;
            if (organizationCode != null && personCode != null) {
               previousId = this.payrollRepository
                  .findPredecessorHistoryId(organizationCode, personCode, current.id())
                  .orElseThrow(() -> new IllegalArgumentException("未找到可恢复为当前工资的上一条记录。"));
               this.payrollRepository.rollbackCurrentHistory(organizationCode, personCode, current.id(), previousId);
            } else {
               previousId = this.payrollRepository.findPredecessorHistoryId(current.id()).orElseThrow(() -> new IllegalArgumentException("未找到可恢复为当前工资的上一条记录。"));
               this.payrollRepository.rollbackCurrentHistory(current.id(), previousId);
            }

            return this.buildRolledBackPayrollChange(current, previousId, message);
         }
      } else {
         throw new IllegalArgumentException("缺少工资记录。");
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult buildAppliedPayrollChange(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot context, String newId, String priorHistoryId, String changeType, String message
   ) {
      com.dxsoft.rsgzgl.payroll.PromotionActionResult result = new com.dxsoft.rsgzgl.payroll.PromotionActionResult(newId, priorHistoryId, changeType, message);
      this.recordPayrollApply(context, newId, changeType, message);
      return result;
   }

   private com.dxsoft.rsgzgl.payroll.PromotionActionResult buildRolledBackPayrollChange(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current, String previousId, String message
   ) {
      String changeType = current == null ? null : current.calculationType();
      com.dxsoft.rsgzgl.payroll.PromotionActionResult result = new com.dxsoft.rsgzgl.payroll.PromotionActionResult(
         previousId, current == null ? null : current.id(), changeType, message
      );
      this.recordPayrollRollback(current, previousId, message);
      return result;
   }

   private void recordPayrollApply(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot context, String newHistoryId, String changeType, String message) {
      if (this.operationLogService != null) {
         String targetId = this.emptyToNull(newHistoryId);
         if (targetId == null && context != null) {
            targetId = this.emptyToNull(context.id());
         }

         if (targetId == null) {
            targetId = "-";
         }

         this.operationLogService.record("APPLY_PAYROLL_CHANGE", "hisbase", targetId, this.formatPayrollAuditSummary(context, changeType, message));
      }
   }

   private void recordPayrollRollback(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot current, String restoredHistoryId, String message) {
      if (this.operationLogService != null) {
         String targetId = current == null ? null : this.emptyToNull(current.id());
         if (targetId == null) {
            targetId = "-";
         }

         this.operationLogService
            .record(
               "ROLLBACK_PAYROLL_CHANGE",
               "hisbase",
               targetId,
               this.formatPayrollAuditSummary(current, current == null ? null : current.calculationType(), message)
            );
      }
   }

   private String formatPayrollAuditSummary(com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot snapshot, String changeType, String message) {
      StringBuilder summary = new StringBuilder();
      if (message != null && !message.isBlank()) {
         summary.append(message.trim());
      }

      if (snapshot != null) {
         if (!summary.isEmpty()) {
            summary.append(' ');
         }

         summary.append(this.emptyToNull(snapshot.organizationCode())).append('-').append(this.emptyToNull(snapshot.personCode()));
         if (snapshot.name() != null && !snapshot.name().isBlank()) {
            summary.append(' ').append(snapshot.name().trim());
         }
      }

      if (changeType != null && !changeType.isBlank()) {
         summary.append(" [").append(changeType.trim()).append(']');
      }

      return summary.isEmpty() ? "工资变动" : summary.toString();
   }

   private String normalPromotionChangeType(String baseSalarySource) {
      if ("GRADE".equals(baseSalarySource)
         || "JUDICIAL_GRADE".equals(baseSalarySource)
         || "POLICE_GRADE".equals(baseSalarySource)
         || "WORKER_GRADE".equals(baseSalarySource)) {
         return "正常档次";
      } else if ("SALARY_LEVEL".equals(baseSalarySource)) {
         return "正常薪级";
      } else {
         throw new IllegalArgumentException("当前基础工资类型不支持正常档次/薪级晋升处理。");
      }
   }

   private com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation buildNormalPromotionMutation(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source,
      String calculationYearForMutation,
      String calculationMonth,
      String changeType,
      String nextStepAssessmentStartYear,
      String promotedGradeOrLevel,
      String gradeSalaryLevel,
      Integer promotedBaseSalary,
      Integer gradeSalaryIncrease,
      boolean positionSalaryPromotion
   ) {
      Integer salaryIncrease = this.normalPromotionTeachingIncreaseAfterWrite(source, positionSalaryPromotion, promotedBaseSalary);
      int totalAmount = this.nullToZero(source.storedTotal()) + this.nullToZero(gradeSalaryIncrease);
      return positionSalaryPromotion
         ? new com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation(
            calculationYearForMutation,
            calculationMonth,
            changeType,
            nextStepAssessmentStartYear,
            source.levelAssessmentStartYear(),
            promotedGradeOrLevel,
            "",
            "",
            0,
            totalAmount,
            promotedBaseSalary,
            salaryIncrease
         )
         : new com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation(
            calculationYearForMutation,
            calculationMonth,
            changeType,
            nextStepAssessmentStartYear,
            source.levelAssessmentStartYear(),
            promotedGradeOrLevel,
            gradeSalaryLevel,
            "",
            promotedBaseSalary,
            totalAmount,
            null,
            salaryIncrease
         );
   }

   private com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation buildLevelPromotionMutation(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source,
      String calculationYear,
      String calculationMonth,
      String changeType,
      String nextStepAssessmentStartYear,
      String nextLevelAssessmentStartYear,
      String promotedStep,
      String promotedLevel,
      Integer promotedGradeSalary,
      Integer gradeSalaryIncrease
   ) {
      Integer salaryIncrease = this.teachingIncreaseAfterWrite(
         source, source.positionCode(), source.storedPositionSalary(), promotedGradeSalary, source.salaryStandardYearMonth()
      );
      int teachingIncreaseDelta = this.teachingIncreaseDelta(
         source, source.positionCode(), source.storedPositionSalary(), promotedGradeSalary, source.salaryStandardYearMonth()
      );
      return new com.dxsoft.rsgzgl.payroll.PromotionHistoryMutation(
         calculationYear,
         calculationMonth,
         changeType,
         nextStepAssessmentStartYear,
         nextLevelAssessmentStartYear,
         String.valueOf(this.payrollRepository.intValue(promotedStep)),
         promotedLevel,
         "",
         promotedGradeSalary,
         this.nullToZero(source.storedTotal()) + this.nullToZero(gradeSalaryIncrease) + teachingIncreaseDelta,
         null,
         salaryIncrease
      );
   }

