   private com.dxsoft.rsgzgl.payroll.PayrollService.BasicSalaryTeachingIncreaseAdjustment finalizeBasicSalaryStandardAdjustmentTotal(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source,
      String salaryStandardYearMonth,
      Integer positionSalary,
      Integer gradeSalary,
      Integer technicalGradeSalary,
      Integer subsidyAllowance
   ) {
      return this.applyTeachingIncreaseToBasicSalaryTotal(
         source,
         salaryStandardYearMonth,
         positionSalary,
         gradeSalary,
         this.basicSalaryAdjustmentBaseTotal(source, positionSalary, gradeSalary, technicalGradeSalary, subsidyAllowance)
      );
   }

   private int basicSalaryAdjustmentBaseTotal(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source,
      Integer positionSalary,
      Integer gradeSalary,
      Integer technicalGradeSalary,
      Integer subsidyAllowance
   ) {
      int oldBasic = this.nullToZero(source.storedPositionSalary())
         + this.nullToZero(source.storedGradeSalary())
         + this.nullToZero(source.storedTechnicalGradeSalary());
      int newBasic = this.nullToZero(positionSalary) + this.nullToZero(gradeSalary) + this.nullToZero(technicalGradeSalary);
      int total = this.nullToZero(source.storedTotal()) - oldBasic + newBasic;
      if (this.isWithinCivilInternPeriod(source)) {
         total -= this.nullToZero(source.storedSubsidyAllowance());
      }

      return total;
   }

   private com.dxsoft.rsgzgl.payroll.PayrollService.BasicSalaryTeachingIncreaseAdjustment applyTeachingIncreaseToBasicSalaryTotal(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source, String salaryStandardYearMonth, Integer positionSalary, Integer gradeSalary, Integer baseTotal
   ) {
      Integer salaryIncrease = this.teachingIncreaseAfterWrite(source, source.positionCode(), positionSalary, gradeSalary, salaryStandardYearMonth);
      int teachingIncreaseDelta = this.teachingIncreaseDelta(source, source.positionCode(), positionSalary, gradeSalary, salaryStandardYearMonth);
      return new com.dxsoft.rsgzgl.payroll.PayrollService.BasicSalaryTeachingIncreaseAdjustment(
         salaryIncrease, this.nullToZero(baseTotal) + teachingIncreaseDelta
      );
   }

   private Integer teachingIncreaseAfterWrite(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source, String positionCode, Integer positionSalary, Integer gradeSalary, String salaryStandardYearMonth
   ) {
      return this.teachingIncreaseForPosition(
         source, positionCode, positionSalary, gradeSalary, this.firstNonBlank(salaryStandardYearMonth, source.salaryStandardYearMonth())
      );
   }

   private int teachingIncreaseDelta(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source, String positionCode, Integer positionSalary, Integer gradeSalary, String salaryStandardYearMonth
   ) {
      return this.nullToZero(this.teachingIncreaseAfterWrite(source, positionCode, positionSalary, gradeSalary, salaryStandardYearMonth))
         - this.nullToZero(source.storedSalaryIncrease());
   }

   private int normalPromotionTeachingIncreaseDelta(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source, boolean positionSalaryPromotion, Integer promotedBaseSalary
   ) {
      Integer afterIncrease = this.normalPromotionTeachingIncreaseAfterWrite(source, positionSalaryPromotion, promotedBaseSalary);
      return this.nullToZero(afterIncrease) - this.nullToZero(source.storedSalaryIncrease());
   }

   private Integer normalPromotionTeachingIncreaseAfterWrite(
      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot source, boolean positionSalaryPromotion, Integer promotedBaseSalary
   ) {
      int positionSalary = positionSalaryPromotion ? this.nullToZero(promotedBaseSalary) : this.nullToZero(source.storedPositionSalary());
      int gradeSalary = positionSalaryPromotion ? this.nullToZero(source.storedGradeSalary()) : this.nullToZero(promotedBaseSalary);
      return this.teachingIncreaseAfterWrite(source, source.positionCode(), positionSalary, gradeSalary, source.salaryStandardYearMonth());
   }

   private com.dxsoft.rsgzgl.payroll.PayrollChangeComponentComparison componentComparison(
      String fieldName, String caption, Map<String, Object> beforeValues, Map<String, Object> afterValues
   ) {
      BigDecimal beforeAmount = beforeValues == null ? BigDecimal.ZERO : this.nullToZero(this.payrollRepository.decimalValue(beforeValues, fieldName));
      BigDecimal afterAmount = afterValues == null ? BigDecimal.ZERO : this.nullToZero(this.payrollRepository.decimalValue(afterValues, fieldName));
      return new com.dxsoft.rsgzgl.payroll.PayrollChangeComponentComparison(fieldName, caption, beforeAmount, afterAmount, afterAmount.subtract(beforeAmount));
   }

   private String approvalCaption(String fieldName, String fallbackCaption) {
      String var4 = fieldName == null ? "" : fieldName.trim().toUpperCase();

      return switch (var4) {
         case "PGBC" -> "工改保留职务工资";
         case "NJBT" -> "农教补贴";
         case "JXGZ" -> "见习工资";
         default -> fallbackCaption;
      };
   }

   private String resolveDegree(String educationName) {
      String text = educationName == null ? "" : educationName.trim();
      if (text.isEmpty()) {
         return "";
      } else {
         return !text.contains("学位") && !text.contains("硕士") && !text.contains("博士") && !text.contains("学士") ? "" : text;
      }
   }

   private String firstNonBlank(String primary, String secondary) {
      if (primary != null && !primary.isBlank()) {
         return primary.trim();
      } else {
         return secondary == null ? "" : secondary.trim();
      }
   }

   private String firstNonBlank(String primary, String secondary, String tertiary) {
      String value = this.firstNonBlank(primary, secondary);
      if (value != null && !value.isBlank()) {
         return value;
      } else {
         return tertiary == null ? "" : tertiary.trim();
      }
   }

   private String valueOrEmpty(String value) {
      return value == null ? "" : value.trim();
   }

   private String textValue(Map<String, Object> values, String fieldName) {
      Object value = values.get(fieldName);
      if (value == null) {
         value = values.get(fieldName.toLowerCase());
      }

      return value == null ? "" : value.toString().trim();
   }

   private int yearOf(String yearOrYearMonth) {
      return yearOrYearMonth != null && yearOrYearMonth.length() >= 4 ? this.payrollRepository.intValue(yearOrYearMonth.substring(0, 4)) : 0;
   }

   private int nullToZero(Integer value) {
      return value == null ? 0 : value;
   }

