   private void requireSystemConfigPermission() {
      if (!this.accessControlService.hasPermission("SYSTEM_CONFIG")) {
         throw new AccessDeniedException("SYSTEM_CONFIG permission required");
      }
   }

   private BigDecimal nullToZero(BigDecimal value) {
      return value == null ? BigDecimal.ZERO : value;
   }

   private String emptyToNull(String value) {
      return value != null && !value.isBlank() ? value.trim() : null;
   }

   private boolean normalizedEquals(String left, String right) {
      String normalizedLeft = this.emptyToNull(left);
      String normalizedRight = this.emptyToNull(right);
      return normalizedLeft == null ? normalizedRight == null : normalizedLeft.equals(normalizedRight);
   }

   private String projectionPeriod(String period) {
      String normalized = period == null ? "" : period.replace(".", "").replace("-", "").trim();
      if (normalized.length() >= 6) {
         return normalized.substring(0, 6);
      } else {
         YearMonth now = YearMonth.now();
         return "%04d%02d".formatted(now.getYear(), now.getMonthValue());
      }
   }

