   private static record LevelPromotionAssessmentCache(Map<Integer, List<com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear>> byUid) {
      private static final Set<String> QUALIFIED_RESULTS = Set.of("优秀", "称职", "合格");

      static com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache empty() {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.LevelPromotionAssessmentCache(Map.of());
      }

      int countQualified(int uid, int startYear, int endYear) {
         if (startYear > 0 && endYear >= startYear) {
            LinkedHashSet<Integer> qualifiedYears = new LinkedHashSet<>();

            for (com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear assessment : this.byUid.getOrDefault(uid, List.of())) {
               if (assessment.year() >= startYear && assessment.year() <= endYear && QUALIFIED_RESULTS.contains(assessment.result())) {
                  qualifiedYears.add(Integer.valueOf(assessment.year()));
               }
            }

            return qualifiedYears.size();
         } else {
            return 0;
         }
      }

      List<Integer> missingYears(int uid, int startYear, int endYear) {
         if (startYear > 0 && endYear >= startYear) {
            Set existingYears = this.byUid
               .getOrDefault(uid, List.of())
               .stream()
               .map(com.dxsoft.rsgzgl.payroll.PersonnelAssessmentYear::year)
               .filter(year -> year >= startYear && year <= endYear)
               .collect(Collectors.toCollection(LinkedHashSet::new));
            ArrayList<Integer> missing = new ArrayList<>();

            for (int year2 = startYear; year2 <= endYear; year2++) {
               if (!existingYears.contains(year2)) {
                  missing.add(year2);
               }
            }

            return missing;
         } else {
            return List.of();
         }
      }
   }

