   private static final class PositionChangePreviewCache {
      private final com.dxsoft.rsgzgl.payroll.PayrollRepository repository;
      private final Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories;
      private final Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplays;
      private final Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> candidates;
      private final Map<String, com.dxsoft.rsgzgl.payroll.PositionLevelRange> levelRanges;
      private final Map<String, Integer> positionSalaries;
      private final Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows;
      private final Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByHistoryId;
      private final Map<String, Integer> gradeSalaries = new ConcurrentHashMap<>();

      private PositionChangePreviewCache(
         com.dxsoft.rsgzgl.payroll.PayrollRepository repository,
         Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories,
         Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplays,
         Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangeCandidate> candidates,
         Map<String, com.dxsoft.rsgzgl.payroll.PositionLevelRange> levelRanges,
         Map<String, Integer> positionSalaries,
         Map<Integer, com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRows,
         Map<String, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessorsByHistoryId
      ) {
         this.repository = repository;
         this.histories = histories == null ? Map.of() : histories;
         this.processedDisplays = processedDisplays == null ? Map.of() : processedDisplays;
         this.candidates = candidates == null ? Map.of() : candidates;
         this.levelRanges = levelRanges == null ? Map.of() : levelRanges;
         this.positionSalaries = positionSalaries == null ? new ConcurrentHashMap<>() : new ConcurrentHashMap<>(positionSalaries);
         this.candidateRows = candidateRows == null ? Map.of() : candidateRows;
         this.predecessorsByHistoryId = predecessorsByHistoryId == null ? Map.of() : predecessorsByHistoryId;
      }

      static com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache empty(com.dxsoft.rsgzgl.payroll.PayrollRepository repository) {
         return new com.dxsoft.rsgzgl.payroll.PayrollService.PositionChangePreviewCache(
            repository, Map.of(), Map.of(), Map.of(), Map.of(), Map.of(), Map.of(), Map.of()
         );
      }

      Map<Integer, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> histories() {
         return this.histories;
      }

      void mergePositionSalaries(Map<String, Integer> salaries) {
         if (salaries != null && !salaries.isEmpty()) {
            this.positionSalaries.putAll(salaries);
         }
      }

      static String positionSalaryKey(String positionCode, String standardYearMonth) {
         return positionCode + "|" + standardYearMonth;
      }

      static String technicalGradeSalaryKey(String positionCode, String standardYearMonth) {
         return "TG|" + positionCode + "|" + standardYearMonth;
      }

      private static String gradeSalaryKey(String gradeLevel, String gradeStep, String standardYearMonth) {
         return gradeLevel + "|" + gradeStep + "|" + standardYearMonth;
      }

      com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot requireHistory(int uid) {
         com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history = this.histories.get(uid);
         return history != null
            ? history
            : this.repository.findLatestHistory(uid).orElseThrow(() -> new NotFoundException("Payroll history not found for personnel record: " + uid));
      }

      Optional<com.dxsoft.rsgzgl.payroll.PositionChangePromotionCandidateRow> candidateRow(int uid) {
         return Optional.ofNullable(this.candidateRows.get(uid));
      }

      Optional<com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot> predecessor(String historyId) {
         if (historyId != null && !historyId.isBlank()) {
            com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot predecessor = this.predecessorsByHistoryId.get(historyId.trim());
            return predecessor == null ? Optional.empty() : Optional.of(predecessor);
         } else {
            return Optional.empty();
         }
      }

      Optional<com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplay(int uid, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
         com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair display = this.processedDisplays.get(uid);
         return display != null ? Optional.of(display) : this.repository.findProcessedPositionChangeDisplay(history.organizationCode(), history.personCode());
      }

      Optional<com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair> processedDisplayById(int uid, String historyId) {
         com.dxsoft.rsgzgl.payroll.PositionChangeDisplayPair display = this.processedDisplays.get(uid);
         return display != null && display.beforePositionName() != null && !display.beforePositionName().isBlank()
            ? Optional.of(display)
            : this.repository.findProcessedPositionChangeDisplayById(historyId);
      }

      com.dxsoft.rsgzgl.payroll.PositionChangeCandidate appointmentCandidate(int uid, com.dxsoft.rsgzgl.payroll.PayrollHistorySnapshot history) {
         com.dxsoft.rsgzgl.payroll.PositionChangeCandidate candidate = this.candidates.get(uid);
         return candidate != null
            ? candidate
            : this.repository
               .findCurrentPositionChangeCandidate(history.organizationCode(), history.personCode())
               .orElse(new com.dxsoft.rsgzgl.payroll.PositionChangeCandidate(history.positionCode(), history.positionName(), history.positionStartYearMonth()));
      }

      Optional<com.dxsoft.rsgzgl.payroll.PositionLevelRange> levelRange(String positionCode) {
         if (positionCode != null && !positionCode.isBlank()) {
            com.dxsoft.rsgzgl.payroll.PositionLevelRange cached = this.levelRanges.get(positionCode);
            return cached != null ? Optional.of(cached) : this.repository.findPositionLevelRange(positionCode);
         } else {
            return Optional.empty();
         }
      }

      int positionSalary(String positionCode, String standardYearMonth) {
         if (positionCode != null && !positionCode.isBlank()) {
            Integer cached = this.positionSalaries.get(positionSalaryKey(positionCode, standardYearMonth));
            return cached != null ? cached : this.repository.positionSalary(positionCode, standardYearMonth);
         } else {
            return 0;
         }
      }

      int technicalGradeSalary(String positionCode, String standardYearMonth) {
         if (positionCode != null && !positionCode.isBlank()) {
            Integer cached = this.positionSalaries.get(technicalGradeSalaryKey(positionCode, standardYearMonth));
            return cached != null ? cached : this.repository.technicalGradeSalary(positionCode, standardYearMonth);
         } else {
            return 0;
         }
      }

      int gradeSalary(String gradeLevel, String gradeStep, String standardYearMonth) {
         return this.gradeSalaries
            .computeIfAbsent(
               gradeSalaryKey(gradeLevel, gradeStep, standardYearMonth), ignored -> this.repository.gradeSalary(gradeLevel, gradeStep, standardYearMonth)
            );
      }

      int policeGradeSalary(String gradeLevel, String gradeStep, String standardYearMonth) {
         return this.gradeSalaries
            .computeIfAbsent(
               "PG|" + gradeLevel + "|" + gradeStep + "|" + standardYearMonth,
               ignored -> this.repository.policeOfficerGradeSalary(gradeLevel, gradeStep, standardYearMonth)
            );
      }
   }

